    /// Whether `war_patience` has lapsed: no foreign-city acquisition for
    /// `WAR_PATIENCE_LIMIT_TURNS` standard turns, counted from the current
    /// war's start or its last capture, whichever is later. See the constant.
    ///
    /// ★★★★ A WAR ONE TURN OLD IS NOT A STALEMATE. #1710 made
    /// `last_campaign_progress` reset only on an observed foreign city changing
    /// hands, so a fresh settlement cannot prolong a stale war — right, and it
    /// left a war declared today with a reference of the last capture (never)
    /// or the first observation. Run civvis-20260816T030249Z: "Declaring war
    /// on Arabia" at t71, and at t72 "The war is a stalemate the plan stops
    /// paying for | no foreign city captured in 47 turns" — the posture and
    /// the peace offers of a lapsed war, one turn in. `major_war_since` is
    /// the war's own start (`observe_campaign`, `None` at peace); the later of
    /// the two is the reference every war deserves.
    fn war_patience_exhausted(&self, g: &Game) -> bool {
        let reference = self
            .last_campaign_progress
            .max(self.major_war_since.unwrap_or(0));
        g.turn.saturating_sub(reference) >= g.standard_duration(WAR_PATIENCE_LIMIT_TURNS).max(1)
    }

    fn observe_campaign(&mut self, g: &Game, pid: usize) {
        let cities = g.player_city_ids(pid).len();
        if self.war_patience {
            // Civilization VI preserves a city's id when it changes hands, and
            // the live mirror preserves that identity too. A new Roman city has
            // no prior foreign owner, so it must not buy another full patience
            // window for a war that has still captured nothing. The first live
            // observation establishes a fair window after a controller restart;
            // later resets require an actual foreign-city acquisition.
            let captured_city = self.campaign_observed
                && g.cities.iter().any(|(city, observed)| {
                    observed.owner == pid
                        && self
                            .campaign_city_owners
                            .get(city)
                            .is_some_and(|owner| *owner != pid)
                });
            if !self.campaign_observed || captured_city {
                self.last_campaign_progress = g.turn;
            }
            self.campaign_city_owners = g
                .cities
                .iter()
                .map(|(city, observed)| (*city, observed.owner))
                .collect();
            self.campaign_observed = true;
        } else if cities > self.last_city_count {
            // `last_campaign_progress` also powers the frozen controller's
            // existing diplomacy fatigue. Keep that historical count-based
            // behavior intact; the ownership-aware clock is live-only.
            self.last_campaign_progress = g.turn;
        }
        self.last_city_count = cities;
        let major_war = g.players.iter().any(|p| {
            p.id != pid && p.alive && !p.is_minor && !p.is_barbarian && g.is_at_war(pid, p.id)
        });
        if major_war {
            self.major_war_since.get_or_insert(g.turn);
        } else {
            self.major_war_since = None;
        }
    }

    fn plan_stale(&self, g: &Game, pid: usize) -> bool {
        let Some(plan) = &self.plan else { return true };
        let unavailable_victory_plan = matches!(
            plan.strategy,
            GrandStrategy::Science
                | GrandStrategy::Culture
                | GrandStrategy::Religion
                | GrandStrategy::Diplomacy
        ) && !Self::victory_strategy_enabled(g, plan.strategy);
        let useful_religious_opening = plan.strategy == GrandStrategy::Religion
            && self.religious_opening_viable(g, pid);
        if unavailable_victory_plan && !useful_religious_opening {
            return true;
        }
        // A rush is re-read every turn. The five-turn cadence is right for a
        // plan measured in eras, but the rush's whole decision — "is the stack
        // staged and can it finish?" — becomes true on one specific turn, and
        // waiting up to four more to notice spends them out of a window that
        // shuts. Measured: early campaigns declare at a median turn 36 and
        // kill 14 turns later, so the target lands at 50 rather than 54 on
        // this alone.
        let cadence = if plan.rush { 1 } else { 5 };
        if g.turn.saturating_sub(plan.assessed_turn) >= cadence {
            return true;
        }
        if let Some(target) = plan.target_player {
            if !g.players.get(target).map(|p| p.alive).unwrap_or(false) {
                return true;
            }
            let emergency_target = g
                .emergency_objective(pid)
                .is_some_and(|objective| objective.target == target);
            if !g.is_at_war(pid, target)
                && !emergency_target
                && !self.campaign_target_legal(g, pid, target)
            {
                return true;
            }
        }
        if let Some(forced) = self.forced_target_player {
            if !g.players.get(forced).map(|player| player.alive).unwrap_or(false)
                || (plan.target_player != Some(forced)
                    && self.campaign_target_legal(g, pid, forced))
            {
                return true;
            }
        }
        if let Some(cid) = plan.target_city {
            if !g.cities.get(&cid).map(|c| c.owner != pid).unwrap_or(false) {
                return true;
            }
        }
        // The five-turn planning horizon keeps economic choices stable, but
        // wars and victory races are interrupts rather than ordinary inputs.
        // Waiting four more turns after a surprise attack or a rival's final
        // launch can make the eventual plan irrelevant.
        let major_wars: Vec<usize> = g
            .players
            .iter()
            .filter(|player| {
                player.id != pid
                    && player.alive
                    && !player.is_minor
                    && !player.is_barbarian
                    && g.is_at_war(pid, player.id)
            })
            .map(|player| player.id)
            .collect();
        if !major_wars.is_empty()
            && !plan
                .target_player
                .is_some_and(|target| major_wars.contains(&target))
        {
            return true;
        }
        if plan.threatened_city != self.threatened_city(g, pid) {
            return true;
        }
        if let Some((rival, counter)) = self.actionable_victory_denial(g, pid) {
            let expects_hostile_target = self.campaign_target_legal(g, pid, rival);
            if (expects_hostile_target && plan.target_player != Some(rival))
                || (!expects_hostile_target && plan.target_player == Some(rival))
                || (major_wars.is_empty() && plan.strategy != counter)
            {
                return true;
            }
        }
        false
    }

    /// Actual unit names available to this civilization, with generic units
    /// replaced by their uniques and foreign uniques removed. Keeping this in
    /// one catalog makes breakthrough selection, predecessor discovery,
    /// production, and upgrade reservation agree on the same upgrade graph.
    fn player_unit_catalog(g: &Game, pid: usize) -> Vec<Name> {
        let civ = g.players[pid].civ.as_str();
        let mut units = BTreeSet::new();
        for (name, spec) in &g.rules.units {
            if !spec.buildable || spec.unique_to.as_deref().is_some_and(|owner| owner != civ) {
                continue;
            }
            let actual = g.player_unit_replacement(pid, *name);
            let actual_spec = &g.rules.units[actual];
            if actual_spec.buildable
                && actual_spec
                    .unique_to
                    .as_deref()
                    .is_none_or(|owner| owner == civ)
            {
                units.insert(actual);
            }
        }
        units.into_iter().collect()
    }

    fn war_unit_unlocked(g: &Game, pid: usize, unit: Name) -> bool {
        let spec = &g.rules.units[unit];
        spec.tech
            .is_none_or(|tech| g.players[pid].techs.contains(&tech))
            && spec
                .civic
                .is_none_or(|civic| g.players[pid].civics.contains(&civic))
            && !g.unit_is_obsolete(pid, unit)
    }

    fn war_unit_successor(g: &Game, pid: usize, unit: Name) -> Option<Name> {
        let generic = g.rules.units[unit].upgrade_to?;
        Some(g.player_unit_replacement(pid, generic))
    }

    fn war_unit_is_at_least(g: &Game, pid: usize, unit: Name, floor: Name) -> bool {
        let mut cursor = floor;
        loop {
            if cursor == unit {
                return true;
            }
            let Some(next) = Self::war_unit_successor(g, pid, cursor) else {
                return false;
            };
            if next == cursor {
                return false;
            }
            cursor = next;
        }
    }

    fn war_direct_predecessor(g: &Game, pid: usize, assault: Name) -> Option<Name> {
        Self::player_unit_catalog(g, pid)
            .into_iter()
            .filter(|unit| Self::war_unit_unlocked(g, pid, *unit))
            .filter(|unit| Self::war_unit_successor(g, pid, *unit) == Some(assault))
            .max_by(|left, right| {
                g.rules.units[*left]
                    .strength
                    .total_cmp(&g.rules.units[*right].strength)
                    .then_with(|| right.cmp(left))
            })
    }

    fn war_strongest_current_melee(g: &Game, pid: usize) -> Option<Name> {
        Self::player_unit_catalog(g, pid)
            .into_iter()
            .filter(|unit| {
                let spec = &g.rules.units[*unit];
                spec.class == "military"
                    && spec.is_melee_capable()
                    && !matches!(spec.domain.as_deref(), Some("sea" | "air"))
                    && Self::war_unit_unlocked(g, pid, *unit)
            })
            .max_by(|left, right| {
                g.rules.units[*left]
                    .strength
                    .total_cmp(&g.rules.units[*right].strength)
                    .then_with(|| right.cmp(left))
            })
    }

    fn war_staging_route_for_unit(
        &self,
        g: &Game,
        pid: usize,
        target: usize,
        uid: u32,
        objective: Pos,
    ) -> Option<usize> {
        let mut goals: Vec<Pos> = g
            .wdisk(objective, 5)
            .into_iter()
            .filter(|position| {
                self.campaign_staging_position(g, pid, target, uid, objective, *position)
            })
            .collect();
        goals.sort();
        goals
            .into_iter()
            .filter_map(|position| g.route_distance(uid, position, 0))
            .min()
    }

    fn war_staging_route(
        &self,
        g: &Game,
        pid: usize,
        target: usize,
        objective: Pos,
    ) -> Option<(u32, usize)> {
        g.player_unit_ids(pid)
            .into_iter()
            .filter(|uid| {
                let spec = &g.rules.units[g.units[uid].kind];
                spec.class == "military"
                    && spec.is_melee_capable()
                    && !matches!(spec.domain.as_deref(), Some("sea" | "air"))
            })
            .filter_map(|uid| {
                self.war_staging_route_for_unit(g, pid, target, uid, objective)
                    .map(|distance| (uid, distance))
            })
            .min_by_key(|(uid, distance)| (*distance, *uid))
    }

    fn war_item_unit(item: &Item) -> Option<(Name, u8)> {
        match item {
            Item::Unit { unit } => Some((*unit, 0)),
            Item::Formation { unit, formation } => Some((*unit, *formation)),
            _ => None,
        }
    }

    fn war_body_kind(&self, g: &Game, pid: usize, plan: &WarPlan, unit: Name) -> bool {
        if Self::war_unit_is_at_least(g, pid, unit, plan.assault_unit) {
            return true;
        }
        !g.players[pid].techs.contains(&plan.breakthrough_tech)
            && plan.predecessor == Some(unit)
    }

    fn war_ready_body_kind(g: &Game, pid: usize, plan: &WarPlan, unit: Name) -> bool {
        Self::war_unit_is_at_least(g, pid, unit, plan.assault_unit)
    }

    fn war_has_breach_kind(plan: &WarPlan, unit: Name) -> bool {
        plan.breach_unit == Some(unit)
    }

    fn war_upgrade_bill(&self, g: &Game, pid: usize, plan: &WarPlan) -> f64 {
        let ready = g
            .player_unit_ids(pid)
            .into_iter()
            .filter(|uid| Self::war_ready_body_kind(g, pid, plan, g.units[uid].kind))
            .count();
        let needed = TIMED_WAR_BODIES.saturating_sub(ready);
        let Some(predecessor) = plan.predecessor else {
            return 0.0;
        };
        let mut quotes = Vec::new();
        for uid in g.player_unit_ids(pid) {
            let unit = &g.units[&uid];
            if unit.kind != predecessor {
                continue;
            }
            if let Some((gold, _)) =
                g.unit_upgrade_price_to(pid, predecessor, plan.assault_unit)
            {
                let multiplier = match unit.formation {
                    0 => 1.0,
                    1 => 2.0,
                    _ => 3.0,
                };
                quotes.push((gold * multiplier, uid));
            }
        }
        for cid in g.player_city_ids(pid) {
            let Some((unit, formation)) = g.cities[&cid]
                .queue
                .first()
                .and_then(Self::war_item_unit)
            else {
                continue;
            };
            if unit != predecessor {
                continue;
            }
            if let Some((gold, _)) =
                g.unit_upgrade_price_to(pid, predecessor, plan.assault_unit)
            {
                let multiplier = match formation {
                    0 => 1.0,
                    1 => 2.0,
                    _ => 3.0,
                };
                quotes.push((gold * multiplier, u32::MAX - cid));
            }
        }
        quotes.sort_by(|left, right| left.0.total_cmp(&right.0).then(left.1.cmp(&right.1)));
        quotes.into_iter().take(needed).map(|(gold, _)| gold).sum()
    }

    fn war_package_status(&self, g: &Game, pid: usize, plan: &WarPlan) -> WarPackageStatus {
        let target_pos = g.cities.get(&plan.objective_city).map(|city| city.pos);
        let mut body_ids = Vec::new();
        let mut planned_bodies = 0;
        let mut staged_ids = Vec::new();
        let mut breach_ready = plan.breach_unit.is_none();
        let mut breach_staged = plan.breach_unit.is_none();
        for uid in g.player_unit_ids(pid) {
            let unit = &g.units[&uid];
            planned_bodies += self.war_body_kind(g, pid, plan, unit.kind) as usize;
            if Self::war_ready_body_kind(g, pid, plan, unit.kind) {
                body_ids.push(uid);
                if target_pos.is_some_and(|objective| {
                    self.campaign_staging_position(
                        g,
                        pid,
                        plan.target_player,
                        uid,
                        objective,
                        unit.pos,
                    )
                }) {
                    staged_ids.push(uid);
                }
            }
            if Self::war_has_breach_kind(plan, unit.kind) {
                breach_ready = true;
                breach_staged |= target_pos.is_some_and(|objective| {
                    self.campaign_staging_position(
                        g,
                        pid,
                        plan.target_player,
                        uid,
                        objective,
                        unit.pos,
                    )
                });
            }
        }
        let queued_bodies = g
            .player_city_ids(pid)
            .into_iter()
            .filter_map(|cid| g.cities[&cid].queue.first())
            .filter_map(Self::war_item_unit)
            .filter(|(unit, _)| self.war_body_kind(g, pid, plan, *unit))
            .count();
        let fourth_one_turn_away = if staged_ids.len() >= TIMED_WAR_BODIES {
            true
        } else if staged_ids.len() >= TIMED_WAR_BODIES - 1 {
            target_pos.is_some_and(|objective| {
                body_ids
                    .iter()
                    .filter(|uid| !staged_ids.contains(uid))
                    .any(|uid| {
                        self.war_staging_route_for_unit(
                            g,
                            pid,
                            plan.target_player,
                            *uid,
                            objective,
                        )
                        .is_some_and(|distance| {
                            distance as f64 <= g.units[uid].moves_left.max(0.0) + f64::EPSILON
                        })
                    })
            })
        } else {
            false
        };
        let local_strength_ratio = target_pos.map_or(0.0, |objective| {
            self.local_strength_ratio(
                g,
                pid,
                &staged_ids,
                &[plan.target_player],
                objective,
            )
        });
        WarPackageStatus {
            planned_bodies,
            ready_bodies: body_ids.len(),
            queued_bodies,
            staged_bodies: staged_ids.len(),
            fourth_one_turn_away,
            breach_ready,
            breach_staged,
            local_strength_ratio,
            upgrade_gold: self.war_upgrade_bill(g, pid, plan),
        }
    }

    fn war_can_field_unit(g: &Game, pid: usize, unit: Name) -> bool {
        g.player_unit_ids(pid)
            .into_iter()
            .any(|uid| g.units[&uid].kind == unit)
            || g.player_city_ids(pid).into_iter().any(|cid| {
                g.cities[&cid]
                    .queue
                    .first()
                    .and_then(Self::war_item_unit)
                    .is_some_and(|(queued, _)| queued == unit)
                    || g.can_produce(pid, cid, &Item::Unit { unit })
            })
    }

    /// `Some(None)` means the objective is currently unwalled. `None` means
    /// it is walled and this empire cannot field a compatible breach element,
    /// so the target/unlock pair is not a real attack plan.
    fn war_breach_requirement(
        &self,
        g: &Game,
        pid: usize,
        city: &crate::game::City,
    ) -> Option<Option<Name>> {
        let wall_hp = if self.battlefront_observation {
            self.remembered_city(city.id)
                .map(|sighting| sighting.wall_hp)
                .unwrap_or(city.wall_hp)
        } else {
            city.wall_hp
        };
        if wall_hp <= 0 {
            return Some(None);
        }
        let wall_levels = city
            .buildings
            .iter()
            .filter(|building| g.rules.buildings[building].outer_defense > 0)
            .count();
        if !g.players[city.owner]
            .techs
            .contains(&crate::name!("steel"))
        {
            let support = if wall_levels <= 1 {
                [crate::name!("battering_ram"), crate::name!("siege_tower")]
            } else {
                [crate::name!("siege_tower"), crate::name!("battering_ram")]
            };
            for unit in support {
                let compatible = match unit.as_str() {
                    "battering_ram" => wall_levels == 1,
                    "siege_tower" => (1..=2).contains(&wall_levels),
                    _ => false,
                };
                if compatible && Self::war_can_field_unit(g, pid, unit) {
                    return Some(Some(unit));
                }
            }
        }

        let city_strength = self
            .remembered_city(city.id)
            .map(|sighting| sighting.strength)
            .unwrap_or_else(|| g.city_strength(city.id));
        Self::player_unit_catalog(g, pid)
            .into_iter()
            .filter(|unit| {
                let spec = &g.rules.units[*unit];
                spec.class == "military"
                    && spec.siege
                    && spec.bombard_strength + f64::EPSILON >= city_strength
                    && Self::war_unit_unlocked(g, pid, *unit)
                    && Self::war_can_field_unit(g, pid, *unit)
            })
            .min_by(|left, right| {
                g.rules.units[*left]
                    .cost
                    .total_cmp(&g.rules.units[*right].cost)
                    .then(left.cmp(right))
            })
            .map(Some)
    }

    fn war_remaining_research_cost(g: &Game, pid: usize, goal: Name) -> f64 {
        let mut path = g
            .rules
            .tech_ancestors
            .get(goal.as_str())
            .cloned()
            .unwrap_or_default();
        path.insert(goal.as_str().to_string());
        let mut cost: f64 = path
            .iter()
            .filter(|tech| !g.players[pid].techs.contains(&Name::new(*tech)))
            .map(|tech| g.tech_cost(tech.as_str()))
            .sum();
        if let Some(current) = g.players[pid].research.as_deref() {
            if path.contains(current) {
                cost -= g.players[pid].research_progress.min(g.tech_cost(current));
            }
        }
        cost.max(0.0)
    }

    fn war_science_per_turn(g: &Game, pid: usize) -> f64 {
        g.player_city_ids(pid)
            .into_iter()
            .map(|city| g.city_yields(city).science)
            .sum::<f64>()
            .max(1.0)
    }

    fn war_production_per_turn(g: &Game, pid: usize) -> f64 {
        g.player_city_ids(pid)
            .into_iter()
            .map(|city| g.city_yields(city).production)
            .sum::<f64>()
            .max(1.0)
    }

    fn war_candidate_defense(
        &self,
        g: &Game,
        pid: usize,
        target: usize,
        city: &crate::game::City,
    ) -> f64 {
        let city_strength = self
            .remembered_city(city.id)
            .map(|sighting| sighting.strength)
            .unwrap_or_else(|| g.city_strength(city.id));
        let visible = self.battlefront_visibility(g, pid);
        let field = g
            .units
            .values()
            .filter(|unit| unit.owner == target && g.wdist(unit.pos, city.pos) <= 6)
            .filter(|unit| {
                !self.battlefront_observation
                    || (g.sees(&visible, unit.pos)
                        && self.battlefront_unit_visible(g, pid, unit.id))
            })
            .filter(|unit| g.rules.units[unit.kind].class == "military")
            .map(|unit| g.unit_strength(unit, true))
            .fold(0.0_f64, f64::max);
        city_strength.max(field)
    }

    fn war_resource_feasible(
        g: &Game,
        pid: usize,
        unit: Name,
        launch_turns: u32,
    ) -> bool {
        let spec = &g.rules.units[unit];
        let Some(resource) = spec.requires_resource else {
            return true;
        };
        if g.connected_resource_count(pid, resource.as_str()) > 0 {
            return true;
        }
        let available = g.strategic_stockpile(pid, resource)
            + g.strategic_resource_rate(pid, resource.as_str()) * launch_turns as f64;
        let (_, required) = g.upgrade_costs(
            pid,
            0.0,
            spec.resource_cost * TIMED_WAR_BODIES as f64,
        );
        available + f64::EPSILON >= required
    }

    fn war_existing_or_queued_count(
        &self,
        g: &Game,
        pid: usize,
        assault: Name,
        predecessor: Option<Name>,
    ) -> usize {
        let counts = |unit: Name| {
            Self::war_unit_is_at_least(g, pid, unit, assault) || predecessor == Some(unit)
        };
        g.player_unit_ids(pid)
            .into_iter()
            .filter(|uid| counts(g.units[uid].kind))
            .count()
            + g.player_city_ids(pid)
                .into_iter()
                .filter_map(|cid| g.cities[&cid].queue.first())
                .filter_map(Self::war_item_unit)
                .filter(|(unit, _)| counts(*unit))
                .count()
    }

    fn war_breach_present(g: &Game, pid: usize, breach: Name) -> bool {
        g.player_unit_ids(pid)
            .into_iter()
            .any(|uid| g.units[&uid].kind == breach)
            || g.player_city_ids(pid).into_iter().any(|cid| {
                g.cities[&cid]
                    .queue
                    .first()
                    .and_then(Self::war_item_unit)
                    .is_some_and(|(unit, _)| unit == breach)
            })
    }

    fn selective_timed_war_target(&self) -> Option<usize> {
        if !self.selective_timed_war || self.war_census.appointments > 0 {
            return None;
        }
        self.plan
            .as_ref()
            .filter(|plan| plan.strategy == GrandStrategy::Conquest)
            .and_then(|plan| plan.target_player)
    }

    fn choose_war_plan(&self, g: &Game, pid: usize) -> Option<WarPlan> {
        let selective_target = if self.selective_timed_war {
            self.selective_timed_war_target()
        } else {
            None
        };
        if self.selective_timed_war && selective_target.is_none() {
            return None;
        }
        let science = Self::war_science_per_turn(g, pid);
        let production = Self::war_production_per_turn(g, pid);
        let catalog = Self::player_unit_catalog(g, pid);
        let current_body = Self::war_strongest_current_melee(g, pid)?;
        let horizon = g
            .max_turns
            .saturating_sub(g.standard_duration(TIMED_WAR_ENDGAME_RESERVE));
        let mut target_choices = Vec::new();

        for target in g.players.iter().filter(|player| {
            player.id != pid
                && player.alive
                && !player.is_minor
                && !player.is_barbarian
                && selective_target.is_none_or(|selected| player.id == selected)
                && self.campaign_target_legal(g, pid, player.id)
        }) {
            let mut objectives: Vec<_> = g
                .cities
                .values()
                .filter(|city| city.owner == target.id)
                .collect();
            objectives.sort_by(|left, right| {
                self.campaign_city_value(g, pid, left, GrandStrategy::Conquest)
                    .total_cmp(&self.campaign_city_value(
                        g,
                        pid,
                        right,
                        GrandStrategy::Conquest,
                    ))
                    .then(left.id.cmp(&right.id))
            });
            for city in objectives {
                let Some((_, route_steps)) =
                    self.war_staging_route(g, pid, target.id, city.pos)
                else {
                    continue;
                };
                let Some(breach_unit) = self.war_breach_requirement(g, pid, city) else {
                    continue;
                };
                let defense = self.war_candidate_defense(g, pid, target.id, city);
                let mut unlocks = Vec::new();
                for assault in catalog.iter().copied() {
                    let spec = &g.rules.units[assault];
                    let Some(tech) = spec.tech else {
                        continue;
                    };
                    if g.players[pid].techs.contains(&tech)
                        || spec.class != "military"
                        || !spec.is_melee_capable()
                        || matches!(spec.domain.as_deref(), Some("sea" | "air"))
                    {
                        continue;
                    }
                    let predecessor = Self::war_direct_predecessor(g, pid, assault);
                    let baseline = predecessor.unwrap_or(current_body);
                    if spec.strength - g.rules.units[baseline].strength
                        < TIMED_WAR_MIN_STRENGTH_GAIN
                    {
                        continue;
                    }
                    let expected_damage = 30.0 * ((spec.strength - defense) / 25.0).exp();
                    if expected_damage + f64::EPSILON < TIMED_WAR_MIN_EXPECTED_DAMAGE {
                        continue;
                    }
                    let research_cost = Self::war_remaining_research_cost(g, pid, tech);
                    let research_turns = (research_cost / science).ceil() as u32;
                    let body_count = self
                        .war_existing_or_queued_count(g, pid, assault, predecessor)
                        .min(TIMED_WAR_BODIES);
                    let prebuilt_floor = if self.rapid_timed_war {
                        TIMED_WAR_BODIES
                    } else {
                        SELECTIVE_TIMED_WAR_PREBUILT_BODIES
                    };
                    if self.selective_timed_war && body_count < prebuilt_floor {
                        continue;
                    }
                    let missing = TIMED_WAR_BODIES.saturating_sub(body_count);
                    let build_body = predecessor.unwrap_or(assault);
                    let mut production_cost =
                        g.rules.units[build_body].cost * missing as f64;
                    if let Some(breach) = breach_unit {
                        let breach_present = Self::war_breach_present(g, pid, breach);
                        if self.rapid_timed_war && !breach_present {
                            continue;
                        }
                        if !breach_present {
                            production_cost += g.rules.units[breach].cost;
                        }
                    }
                    let production_turns = (production_cost / production).ceil() as u32;
                    let slowest_moves = breach_unit
                        .map(|breach| spec.moves.min(g.rules.units[breach].moves))
                        .unwrap_or(spec.moves)
                        .max(1.0);
                    let march_turns = (route_steps as f64 / slowest_moves).ceil() as u32;
                    let launch_turns = research_turns
                        .saturating_add(production_turns)
                        .saturating_add(march_turns);
                    if (self.rapid_timed_war
                        && launch_turns
                            > g.standard_duration(RAPID_TIMED_WAR_LAUNCH_WINDOW))
                        || g.turn.saturating_add(launch_turns) >= horizon
                        || !Self::war_resource_feasible(g, pid, assault, launch_turns)
                    {
                        continue;
                    }
                    unlocks.push((
                        research_cost,
                        launch_turns,
                        std::cmp::Reverse((expected_damage * 1000.0).round() as i64),
                        assault,
                        tech,
                        predecessor,
                        research_turns,
                        production_turns,
                        march_turns,
                    ));
                }
                unlocks.sort_by(|left, right| {
                    left.0
                        .total_cmp(&right.0)
                        .then(left.1.cmp(&right.1))
                        .then(left.2.cmp(&right.2))
                        .then(left.3.cmp(&right.3))
                });
                let Some((
                    _,
                    launch_turns,
                    _,
                    assault_unit,
                    breakthrough_tech,
                    predecessor,
                    estimated_research_turns,
                    estimated_production_turns,
                    estimated_march_turns,
                )) = unlocks.into_iter().next()
                else {
                    continue;
                };
                let mut plan = WarPlan {
                    target_player: target.id,
                    objective_city: city.id,
                    breakthrough_tech,
                    assault_unit,
                    predecessor,
                    breach_unit,
                    estimated_research_turns,
                    estimated_production_turns,
                    estimated_upgrade_gold: 0.0,
                    estimated_march_turns,
                    phase: WarPhase::Research,
                    appointed_turn: g.turn,
                    tech_turn: None,
                    declared_turn: None,
                    last_reviewed_turn: g.turn,
                    recovery_assessments: 0,
                };
                plan.estimated_upgrade_gold = self.war_upgrade_bill(g, pid, &plan);
                let score = self.campaign_city_value(g, pid, city, GrandStrategy::Conquest)
                    + launch_turns as f64;
                target_choices.push((score, target.id, city.id, assault_unit, plan));
                // The objective list is already campaign-ranked. The first
                // routeable, breach-feasible city is this target's attack.
                break;
            }
        }
        target_choices
            .into_iter()
            .min_by(|left, right| {
                left.0
                    .total_cmp(&right.0)
                    .then(left.1.cmp(&right.1))
                    .then(left.2.cmp(&right.2))
                    .then(left.3.cmp(&right.3))
            })
            .map(|(_, _, _, _, plan)| plan)
    }

    fn may_form_war_plan(&self, g: &Game, pid: usize) -> bool {
        if !self.timed_war
            || self.war_plan.is_some()
            || (self.selective_timed_war
                && self.selective_timed_war_target().is_none())
            || g.turn < g.standard_duration(RUSH_WINDOW_CLOSES)
            || g.turn < self.peace_until
            || g.player_city_ids(pid).len() < 2
            || self.threatened_city(g, pid).is_some()
            || g.emergency_objective(pid).is_some()
            || self.victory_denial(g, pid).is_some()
            || self.early_rush_victim(g, pid).is_some()
            || (g.has_ability(pid, "taxis")
                && (g.players[pid].religion.is_some()
                    || g.players[pid]
                        .civics
                        .contains(&crate::name!("divine_right"))))
        {
            return false;
        }
        let reserve = g.standard_duration(TIMED_WAR_ENDGAME_RESERVE);
        if g.turn.saturating_add(reserve) >= g.max_turns {
            return false;
        }
        !g.players.iter().any(|player| {
            player.id != pid
                && player.alive
                && !player.is_minor
                && !player.is_barbarian
                && g.is_at_war(pid, player.id)
        })
    }

    /// One staging predicate is shared by lifecycle phase selection and the
    /// declaration site. That keeps the UI's `strike` phase from promising a
    /// launch the diplomatic executor would refuse (or vice versa).
    fn timed_war_staging_ready(&self, status: &WarPackageStatus) -> bool {
        let bodies_staged = if self.selective_timed_war {
            status.staged_bodies >= TIMED_WAR_BODIES
        } else {
            status.staged_bodies >= TIMED_WAR_BODIES - 1
                && status.fourth_one_turn_away
        };
        let strength_floor = if self.selective_timed_war {
            SELECTIVE_TIMED_WAR_STRENGTH_FLOOR
        } else {
            1.0
        };
        bodies_staged
            && status.breach_staged
            && status.local_strength_ratio + f64::EPSILON >= strength_floor
    }

    fn timed_war_launch_ready(
        &self,
        g: &Game,
        pid: usize,
        plan: &WarPlan,
        status: &WarPackageStatus,
    ) -> bool {
        g.players[pid].techs.contains(&plan.breakthrough_tech)
            && status.ready_bodies >= TIMED_WAR_BODIES
            && status.breach_ready
            && self.timed_war_staging_ready(status)
            && self.threatened_city(g, pid).is_none()
    }

    fn record_war_abort(&mut self, reason: &'static str) {
        *self.war_census.aborts.entry(reason).or_default() += 1;
        if self.journal().wants(crate::reasoning::Level::Strategy) {
            think!(self.journal(), Military, Strategy, "Standing down the appointed attack";
                   "{reason}");
        }
    }

    fn record_war_capture(&mut self, g: &Game, plan: &WarPlan) {
        self.war_census.objectives_captured += 1;
        if let Some(declared) = plan.declared_turn {
            let elapsed = g.turn.saturating_sub(declared);
            self.war_census.declaration_to_capture_turns += elapsed;
            self.war_census
                .declaration_to_capture_samples
                .push(elapsed);
            if elapsed <= TIMED_WAR_CAPTURE_WINDOW {
                self.war_census.objectives_captured_within_ten += 1;
            }
        }
        think!(self.journal(), Military, Strategy, "The appointed city has fallen";
               "{} turns from appointment and {} from declaration",
               g.turn.saturating_sub(plan.appointed_turn),
               plan.declared_turn.map_or(0, |turn| g.turn.saturating_sub(turn)));
    }

    fn refresh_war_estimates(&self, g: &Game, pid: usize, plan: &mut WarPlan) {
        plan.estimated_research_turns =
            (Self::war_remaining_research_cost(g, pid, plan.breakthrough_tech)
                / Self::war_science_per_turn(g, pid))
                .ceil() as u32;
        let status = self.war_package_status(g, pid, plan);
        let missing = TIMED_WAR_BODIES
            .saturating_sub(status.planned_bodies.saturating_add(status.queued_bodies));
        let build = if g.players[pid].techs.contains(&plan.breakthrough_tech) {
            plan.assault_unit
        } else {
            plan.predecessor.unwrap_or(plan.assault_unit)
        };
        let mut cost = g.rules.units[build].cost * missing as f64;
        if let Some(breach) = plan.breach_unit {
            let queued = g.player_city_ids(pid).into_iter().any(|cid| {
                g.cities[&cid]
                    .queue
                    .first()
                    .and_then(Self::war_item_unit)
                    .is_some_and(|(unit, _)| unit == breach)
            });
            if !status.breach_ready && !queued {
                cost += g.rules.units[breach].cost;
            }
        }
        plan.estimated_production_turns =
            (cost / Self::war_production_per_turn(g, pid)).ceil() as u32;
        plan.estimated_upgrade_gold = status.upgrade_gold;
        if let Some(city) = g.cities.get(&plan.objective_city) {
            if let Some((_, steps)) =
                self.war_staging_route(g, pid, plan.target_player, city.pos)
            {
                let slowest = plan
                    .breach_unit
                    .map(|breach| {
                        g.rules.units[plan.assault_unit]
                            .moves
                            .min(g.rules.units[breach].moves)
                    })
                    .unwrap_or(g.rules.units[plan.assault_unit].moves)
                    .max(1.0);
                plan.estimated_march_turns = (steps as f64 / slowest).ceil() as u32;
            }
        }
    }

    /// Validate and advance the one appointed campaign before any subsystem
    /// acts. This is the lifecycle authority: research, production, money,
    /// diplomacy, and movement only consume the resulting phase.
    fn maintain_war_plan(&mut self, g: &Game, pid: usize) {
        if !self.timed_war {
            self.war_plan = None;
            self.war_status = WarPackageStatus::default();
            return;
        }

        if let Some(mut plan) = self.war_plan.take() {
            let target_alive = g
                .players
                .get(plan.target_player)
                .is_some_and(|target| target.alive);
            let objective_owner = g.cities.get(&plan.objective_city).map(|city| city.owner);
            let at_war = target_alive && g.is_at_war(pid, plan.target_player);
            let mut end = None;
            if objective_owner != Some(plan.target_player) {
                if plan.declared_turn.is_some() && objective_owner == Some(pid) {
                    self.record_war_capture(g, &plan);
                } else {
                    self.record_war_abort("objective changed owner");
                }
                end = Some(());
            } else if !target_alive {
                self.record_war_abort("target no longer alive");
                end = Some(());
            } else if !at_war && !self.campaign_target_legal(g, pid, plan.target_player) {
                self.record_war_abort("diplomacy made war illegal");
                end = Some(());
            } else if at_war && plan.declared_turn.is_none() {
                self.record_war_abort("target opened the war first");
                end = Some(());
            } else if plan.declared_turn.is_some() && !at_war {
                self.record_war_abort("peace closed the war");
                end = Some(());
            }
            if end.is_some() {
                self.plan = None;
            } else {
                self.refresh_war_estimates(g, pid, &mut plan);
                let launch_turns = plan
                    .estimated_research_turns
                    .saturating_add(plan.estimated_production_turns)
                    .saturating_add(plan.estimated_march_turns);
                let horizon = g
                    .max_turns
                    .saturating_sub(g.standard_duration(TIMED_WAR_ENDGAME_RESERVE));
                if g.turn.saturating_add(launch_turns) >= horizon {
                    self.record_war_abort("launch slipped beyond the attack horizon");
                    self.plan = None;
                } else if !Self::war_resource_feasible(
                    g,
                    pid,
                    plan.assault_unit,
                    launch_turns,
                ) {
                    self.record_war_abort("strategic resource package became impossible");
                    self.plan = None;
                } else {
                    let review_cadence = g.standard_duration(5).max(1);
                    if g.turn.saturating_sub(plan.last_reviewed_turn) >= review_cadence {
                        plan.last_reviewed_turn = g.turn;
                        if self.threatened_city(g, pid).is_some() {
                            plan.recovery_assessments = plan.recovery_assessments.saturating_add(1);
                        } else {
                            plan.recovery_assessments = 0;
                        }
                    }
                    if plan.recovery_assessments >= 2 {
                        self.record_war_abort("home Recovery persisted for two assessments");
                        self.plan = None;
                    } else if at_war {
                        plan.phase = WarPhase::Exploit;
                        self.war_plan = Some(plan);
                    } else {
                        let previous = plan.phase;
                        let tech_owned = g.players[pid].techs.contains(&plan.breakthrough_tech);
                        if tech_owned && plan.tech_turn.is_none() {
                            plan.tech_turn = Some(g.turn);
                            self.war_census.breakthroughs += 1;
                            let elapsed = g.turn.saturating_sub(plan.appointed_turn);
                            self.war_census.appointment_to_tech_turns += elapsed;
                            self.war_census
                                .appointment_to_tech_samples
                                .push(elapsed);
                        }
                        let status = self.war_package_status(g, pid, &plan);
                        let package_ready = status.ready_bodies >= TIMED_WAR_BODIES
                            && status.breach_ready;
                        let staged = self.timed_war_staging_ready(&status);
                        plan.phase = if !tech_owned {
                            WarPhase::Research
                        } else if !package_ready {
                            WarPhase::Mobilize
                        } else if !staged {
                            WarPhase::Stage
                        } else {
                            WarPhase::Strike
                        };
                        if package_ready
                            && matches!(previous, WarPhase::Research | WarPhase::Mobilize)
                        {
                            self.war_census.mobilizations += 1;
                        }
                        self.war_plan = Some(plan);
                    }
                }
            }
        }

        if self.war_plan.is_none() && self.may_form_war_plan(g, pid) {
            if let Some(plan) = self.choose_war_plan(g, pid) {
                self.war_census.appointments += 1;
                if let Some(city) = g.cities.get(&plan.objective_city) {
                    think!(self.journal(), Military, Strategy,
                           "Appointing a power-spike attack on {}", city.name;
                           "research {}, prebuild {}, reserve {:.0} gold, then stage four {} bodies{}; estimated launch in {} turns",
                           plain(&plan.breakthrough_tech),
                           plan.predecessor.map(|unit| plain(&unit)).unwrap_or_else(|| plain(&plan.assault_unit)),
                           plan.estimated_upgrade_gold,
                           plain(&plan.assault_unit),
                           plan.breach_unit.map(|unit| format!(" with {}", plain(&unit))).unwrap_or_default(),
                           plan.estimated_research_turns
                               .saturating_add(plan.estimated_production_turns)
                               .saturating_add(plan.estimated_march_turns));
                }
                self.war_plan = Some(plan);
            }
        }
        let status = self
            .war_plan
            .as_ref()
            .map(|plan| self.war_package_status(g, pid, plan))
            .unwrap_or_default();
        self.war_status = status;
    }

    fn apply_war_plan_to_strategy(&self, plan: &mut StrategicPlan) {
        let Some(war) = &self.war_plan else {
            return;
        };
        // A live home emergency temporarily wins the grand-strategy posture,
        // but does not silently retarget or dissolve the appointment.
        if plan.strategy != GrandStrategy::Recovery {
            plan.strategy = GrandStrategy::Conquest;
            plan.target_player = Some(war.target_player);
            plan.target_city = Some(war.objective_city);
            plan.rush = false;
        }
    }

    fn war_treasury_floor(&self, g: &Game, pid: usize) -> f64 {
        let ordinary = 100.0 + 25.0 * g.player_city_ids(pid).len() as f64;
        self.war_plan
            .as_ref()
            .map(|plan| ordinary + self.war_upgrade_bill(g, pid, plan))
            .unwrap_or(0.0)
    }

    /// Execute the package modernization before any discretionary spending or
    /// movement. Generic upgrades run later only after this exact campaign
    /// bill has been discharged.
    fn execute_war_upgrades(&mut self, g: &mut Game, pid: usize) {
        let Some(plan) = self.war_plan.clone() else {
            return;
        };
        if !g.players[pid].techs.contains(&plan.breakthrough_tech) {
            return;
        }
        let Some(predecessor) = plan.predecessor else {
            return;
        };
        let ready = self.war_package_status(g, pid, &plan).ready_bodies;
        let mut needed = TIMED_WAR_BODIES.saturating_sub(ready);
        let mut candidates = g
            .player_unit_ids(pid)
            .into_iter()
            .filter_map(|uid| {
                let unit = &g.units[&uid];
                if unit.kind != predecessor {
                    return None;
                }
                let (target, gold, _) = g.unit_gold_upgrade_offer(pid, uid)?;
                (target == plan.assault_unit).then_some((gold, uid))
            })
            .collect::<Vec<_>>();
        candidates.sort_by(|left, right| left.0.total_cmp(&right.0).then(left.1.cmp(&right.1)));
        for (gold, uid) in candidates {
            if needed == 0 {
                break;
            }
            if g.apply(pid, &Action::UpgradeUnit { unit: uid }).is_ok() {
                needed -= 1;
                think!(self.journal(), Military, Decision,
                       "Modernizing the appointed assault body";
                       "{} gold turns {} into {} before the campaign moves",
                       gold.round(), plain(&predecessor), plain(&plan.assault_unit));
            }
        }
        self.war_status = self.war_package_status(g, pid, &plan);
    }

    /// Local military pressure on one city: *observed* hostile military
    /// strength within six tiles over the friendly strength answering it,
    /// city defenses included. Zero when no visible hostile unit is in reach.
    ///
    /// This is the number `threatened_city` has always computed and then
    /// discarded for every city but the worst one. Naming it lets the same
    /// evidence reach the city's own decisions — what it builds and what its
    /// citizens work — instead of only the empire-wide recovery alarm.
    fn city_pressure_with_visibility(
        g: &Game,
        pid: usize,
        cid: u32,
        visible: &crate::world::TileBits,
    ) -> f64 {
        let Some(city) = g.cities.get(&cid) else {
            return 0.0;
        };
        let hostile: f64 = g
            .units
            .values()
            .filter(|unit| unit.owner != pid && g.is_at_war(pid, unit.owner))
            .filter(|unit| g.sees(visible, unit.pos) && g.unit_visible_to(unit.id, pid))
            .filter(|unit| g.wdist(city.pos, unit.pos) <= 6)
            .filter(|unit| g.rules.units[unit.kind].class == "military")
            .map(|unit| crate::game::effective_strength(g.unit_strength(unit, false), unit.hp))
            .sum();
        if hostile <= 0.0 {
            return 0.0;
        }
        hostile / Self::city_friendly_strength(g, pid, cid).max(1.0)
    }

    fn city_friendly_strength(g: &Game, pid: usize, cid: u32) -> f64 {
        let Some(city) = g.cities.get(&cid) else {
            return 0.0;
        };
        g.city_strength(cid)
            + g.units
                .values()
                .filter(|unit| unit.owner == pid && g.wdist(city.pos, unit.pos) <= 6)
                .filter(|unit| g.rules.units[unit.kind].class == "military")
                .map(|unit| crate::game::effective_strength(g.unit_strength(unit, true), unit.hp))
                .sum::<f64>()
    }

    /// The stock pressure calculation sees only live contacts. The evaluator
    /// arm adds an independently auditable, decayed memory term after that
    /// calculation, so visible sightings cannot be counted twice.
    fn remembered_city_pressure(&self, g: &Game, pid: usize, cid: u32) -> f64 {
        if !self.belief_pressure {
            return 0.0;
        }
        let Some(city) = g.cities.get(&cid) else {
            return 0.0;
        };
        let remembered = self.belief.remembered_hidden_military_threat(
            g,
            pid,
            city.pos,
            THREAT_RELIEF_RADIUS,
            BELIEF_PRESSURE_HORIZON,
        );
        remembered / Self::city_friendly_strength(g, pid, cid).max(1.0)
    }

    /// Combat state at the last City Center sighting, if this controller has
    /// one. Campaign code uses this rather than re-reading a hidden city's
    /// live durability or garrison-derived strength.
    fn remembered_city(&self, cid: u32) -> Option<&CitySighting> {
        self.belief.cities.get(&cid)
    }

    /// Capture one coherent battlefront observation before any action can
    /// reveal more of the map.  The stored unit set matters for camouflage:
    /// moving a detector later in the turn must not cause the planning frame
    /// to treat a formerly hidden unit as known at turn start.
    fn capture_battlefront_frame(&mut self, g: &Game, pid: usize) {
        if !self.battlefront_observation {
            self.battlefront_frame = None;
            return;
        }
        let visible = g.player_vision_now(pid);
        let units = g
            .units
            .values()
            .filter(|unit| g.sees(&visible, unit.pos) && g.unit_visible_to(unit.id, pid))
            .map(|unit| unit.id)
            .collect();
        self.battlefront_frame = Some(BattlefrontFrame { visible, units });
    }

    /// The battlefront's turn-start tile frame, or current vision when this
    /// helper is used outside a controller turn (including focused tests).
    fn battlefront_visibility(&self, g: &Game, pid: usize) -> TileBits {
        self.battlefront_frame
            .as_ref()
            .map(|frame| frame.visible.clone())
            .unwrap_or_else(|| g.player_vision_now(pid))
    }

    /// Whether a unit belonged to the same turn-start observation frame.
    fn battlefront_unit_visible(&self, g: &Game, pid: usize, uid: u32) -> bool {
        self.battlefront_frame
            .as_ref()
            .map(|frame| frame.units.contains(&uid))
            .unwrap_or_else(|| g.unit_visible_to(uid, pid))
    }

    fn city_pressure_with_belief(
        &self,
        g: &Game,
        pid: usize,
        cid: u32,
        visible: &crate::world::TileBits,
    ) -> f64 {
        Self::city_pressure_with_visibility(g, pid, cid, visible)
            + self.remembered_city_pressure(g, pid, cid)
    }

    #[cfg(test)]
    fn city_pressure(g: &Game, pid: usize, cid: u32) -> f64 {
        let visible = g.player_vision_now(pid);
        Self::city_pressure_with_visibility(g, pid, cid, &visible)
    }

    #[cfg(test)]
    fn belief_city_pressure(&self, g: &Game, pid: usize, cid: u32) -> f64 {
        let visible = g.player_vision_now(pid);
        self.city_pressure_with_belief(g, pid, cid, &visible)
    }

    /// Evaluate the independent city/unit distance matrix from compact,
    /// immutable inputs. Strength modifiers and city defenses are resolved on
    /// the simulation thread first, so workers share no `Game` caches and the
    /// floating-point sums retain unit-ID order exactly.
    fn city_pressures(&self, g: &Game, pid: usize, cities: &[u32]) -> Vec<f64> {
        let visible = g.player_vision_now(pid);
        let Some(pool) = self.work_pool.as_ref() else {
            return cities
                .iter()
                .map(|city| self.city_pressure_with_belief(g, pid, *city, &visible))
                .collect();
        };
        let relevant = g
            .units
            .values()
            .filter(|unit| g.rules.units[unit.kind].class == "military")
            .filter(|unit| {
                unit.owner == pid
                    || (g.is_at_war(pid, unit.owner)
                        && g.sees(&visible, unit.pos)
                        && g.unit_visible_to(unit.id, pid))
            })
            .collect::<Vec<_>>();
        // Pool dispatch dominates tiny empires. This boundary is comparisons,
        // not a map/player constant: large armies with few cities and wide
        // empires with small garrisons reach the same measured work floor.
        if cities.len() < 2 || cities.len().saturating_mul(relevant.len()) < 128 {
            return cities
                .iter()
                .map(|city| self.city_pressure_with_belief(g, pid, *city, &visible))
                .collect();
        }

        // Add remembered pressure after the pool's exact live-contact result.
        // That preserves the stock summation order and makes the treatment's
        // only new contribution an explicit scalar per city.
        let remembered = cities
            .iter()
            .map(|city| self.remembered_city_pressure(g, pid, *city))
            .collect::<Vec<_>>();
        let units = relevant
            .into_iter()
            .map(|unit| {
                let friendly = unit.owner == pid;
                CityPressureUnit {
                    position: unit.pos,
                    friendly,
                    strength: crate::game::effective_strength(
                        g.unit_strength(unit, friendly),
                        unit.hp,
                    ),
                }
            })
            .collect::<Vec<_>>();
        let sites = cities
            .iter()
            .map(|city| CityPressureSite {
                position: g.cities[city].pos,
                defense: g.city_strength(*city),
            })
            .collect::<Vec<_>>();
        let distance = match g.map.topology {
            crate::world::Topology::Cylinder => CityDistance::Cylinder(g.map.width),
            crate::world::Topology::Rectangle => CityDistance::Bounded,
            crate::world::Topology::Globe(frequency) => {
                CityDistance::Globe(crate::sphere::sphere(frequency))
            }
        };
        let units = Arc::new(units);
        let sites = Arc::new(sites);
        let distance = Arc::new(distance);
        pool.map(cities.len(), move |index| {
            let site = sites[index];
            let hostile = units
                .iter()
                .filter(|unit| !unit.friendly)
                .filter(|unit| distance.between(site.position, unit.position) <= 6)
                .map(|unit| unit.strength)
                .sum::<f64>();
            if hostile <= 0.0 {
                return 0.0;
            }
            let friendly = site.defense
                + units
                    .iter()
                    .filter(|unit| unit.friendly)
                    .filter(|unit| distance.between(site.position, unit.position) <= 6)
                    .map(|unit| unit.strength)
                    .sum::<f64>();
            hostile / friendly.max(1.0)
        })
        .into_iter()
        .zip(remembered)
        .map(|(observed, remembered)| observed + remembered)
        .collect()
    }

    /// The empire's objective translated into the citizen governor's own
    /// vocabulary: how much extra appetite this lane asks for, per yield.
    ///
    /// Every number here is a *tilt*, not a takeover. The shipped weights are
    /// food 1.25 / production 1.55 / science 1.30 / culture 1.20 / gold 0.85 /
    /// faith 0.90, so a lane yield gaining ~0.5 moves it up roughly a third
    /// and never reorders the whole vector — a Science empire still builds
    /// settlers and still feeds itself.
    ///
    /// `research_tilt` is the standing beaker appetite from
    /// [`AdvancedAi::research_economy`], added on top of the lane's own tilt in
    /// *every* lane. In the live Kongo run the second city's governor carried a
    /// science weight of 1.3 against production 3.9 and worked no research
    /// tiles for the whole game; a lane-only emphasis can never reach it,
    /// because that empire was never in the Science lane.
    fn lane_emphasis(strategy: GrandStrategy, research_tilt: f64) -> Yields {
        let mut ys = Yields::default();
        match strategy {
            // Growth is the lane. Hammers still matter because a settler is
            // paid for in production even though it is gated on food.
            GrandStrategy::Expansion => {
                ys.food = 0.35;
                ys.production = 0.20;
            }
            GrandStrategy::Science => {
                ys.science = 0.50;
                ys.production = 0.15;
            }
            GrandStrategy::Culture => {
                ys.culture = 0.50;
                ys.gold = 0.10;
            }
            GrandStrategy::Religion => {
                ys.faith = 0.50;
                ys.food = 0.15;
            }
            // Envoys and city-state suzerainty are bought, so the diplomatic
            // lane is a Gold lane at the tile level.
            GrandStrategy::Diplomacy => {
                ys.gold = 0.45;
                ys.production = 0.15;
            }
            // An army is production and the population that replaces it is
            // food; nothing else on the sheet wins a war.
            GrandStrategy::Conquest => {
                ys.production = 0.55;
                ys.food = 0.15;
            }
            GrandStrategy::Recovery => {
                ys.production = 0.45;
                ys.food = 0.20;
            }
        }
        // A lane that already asks for beakers keeps its own, larger, appetite.
        ys.science = ys.science.max(research_tilt);
        ys
    }

    /// Write one [`CityDirective`] per owned city, rebuilding the map from
    /// scratch so a captured or razed city cannot leave a stale entry behind.
    ///
    /// The role choice is ranked, and the order is the argument: a city being
    /// shot at is a Bastion whatever else it is good at; an empire short of
    /// its city target puts its best food city on settlers before it optimises
    /// anything else, because expansion compounds and specialization does not;
    /// only then does the local yield mix get to speak.
    ///
    /// ⚠ **`expansion_first` is not a refinement of that rule — it is the
    /// repair of a defect the census found in it.** The comparative rungs are
    /// scale-free: they type a city by whether a yield stands `ROLE_MARGIN`
    /// above its *empire's own mean*, and with two cities the mean sits
    /// between them, so one of them is typed whatever the terrain actually
    /// says. `role_ladder_census` measured the result over 1668 city-turns —
    /// 45.5% of city-turns typed, Forge alone 17.7% and Specialist 7.1% — in
    /// empires averaging 2.14 cities. So the doc comment on `ROLE_MARGIN`
    /// claiming an empire of interchangeable cities "correctly gets no roles
    /// at all" was **false at exactly the empire size where the game is
    /// decided**, and the city most often typed a Forge is the capital, which
    /// is the settler pump whose growth `docs/OPENINGS.md` shows gates every
    /// settler.
    fn stamp_city_directives(&self, g: &mut Game, pid: usize, plan: &StrategicPlan) {
        let cities = g.player_city_ids(pid);
        if cities.is_empty() {
            if let Some(seat) = g.players.get_mut(pid) {
                seat.city_directives.clear();
            }
            return;
        }
        // While the empire is still short of its city target, only the two
        // rungs that cannot cost expansion may fire: Bastion, which answers a
        // real threat, and Breadbasket, which feeds the settler. Forge and
        // Specialist both bid citizens away from food, and a city founded
        // sixty turns earlier compounds for the rest of the game where a
        // marginally better yield mix does not.
        let expanding = self.city_strategy_expansion_first && cities.len() < plan.desired_cities;
        let research_tilt = if self.research_economy {
            RESEARCH_CITIZEN_TILT * Self::research_horizon(g)
        } else {
            0.0
        };
        let emphasis = if self.city_strategy_emphasis {
            Self::lane_emphasis(plan.strategy, research_tilt)
        } else {
            Yields::default()
        };
        let short = cities.len() < plan.desired_cities;

        let (city_yields, pressures) = {
            // City yields share empire-wide Amenity, regional-building, and
            // Great Work derivations. Keep one scope across the complete
            // census, and reuse each city's answer for both the mean and its
            // own role instead of deriving it twice.
            let _memo = g.query_memo();
            let city_yields = cities
                .iter()
                .map(|city| g.city_yields(*city))
                .collect::<Vec<_>>();
            let pressures = self.city_pressures(g, pid, &cities);
            (city_yields, pressures)
        };
        let mut totals = Yields::default();
        for yields in &city_yields {
            totals.add(*yields);
        }
        let count = cities.len() as f64;
        let mean_food = totals.food / count;
        let mean_production = totals.production / count;
        let mean_specialty = (totals.science + totals.culture + totals.faith + totals.gold) / count;

        let mut directives = BTreeMap::new();
        for ((cid, ys), pressure) in cities
            .into_iter()
            .zip(city_yields)
            .zip(pressures)
        {
            let specialty = ys.science + ys.culture + ys.faith + ys.gold;
            // `BASTION_PRESSURE` is the same 0.45 `threatened_city` treats as
            // a locally competitive hostile force, so the city's own governor
            // and the empire's recovery alarm agree on what a threat is.
            let bastion = pressure >= BASTION_PRESSURE || plan.threatened_city == Some(cid);
            let role = if !self.city_strategy_roles {
                CityRole::Balanced
            } else if bastion && self.city_strategy_bastion {
                CityRole::Bastion
            } else if short && self.city_strategy_breadbasket && ys.food >= mean_food * ROLE_MARGIN
            {
                CityRole::Breadbasket
            } else if expanding || !self.city_strategy_comparative {
                CityRole::Balanced
            } else if ys.production >= mean_production * ROLE_MARGIN {
                CityRole::Forge
            } else if specialty >= mean_specialty * ROLE_MARGIN {
                CityRole::Specialist
            } else {
                CityRole::Balanced
            };
            let pressure = if self.city_strategy_roles && self.city_strategy_pressure {
                pressure
            } else {
                0.0
            };
            directives.insert(
                cid,
                CityDirective {
                    emphasis,
                    role,
                    pressure,
                    // Measured harmful in isolation (43.8%, Elo -44,
                    // p=0.0107). Reachable only through the frozen controls.
                    halt_growth: self.city_strategy_halt_growth
                        && role == CityRole::Bastion,
                },
            );
        }
        if let Some(seat) = g.players.get_mut(pid) {
            seat.city_directives = directives;
        }
    }

    fn threatened_city(&self, g: &Game, pid: usize) -> Option<u32> {
        let visible = g.player_vision_now(pid);
        g.player_city_ids(pid)
            .into_iter()
            .filter_map(|cid| {
                let city = &g.cities[&cid];
                let danger = self.city_pressure_with_belief(g, pid, cid, &visible);
                if danger <= 0.0 {
                    return None;
                }
                let recently_hit =
                    city.last_attacked > 0 && g.turn.saturating_sub(city.last_attacked) <= 3;
                let wall_max = g.city_max_wall_hp(city);
                let damaged = city.hp < 200 || city.wall_hp < wall_max;
                let breached = city.hp < 160
                    || (wall_max > 0 && city.wall_hp.saturating_mul(2) < wall_max);
                // A scout or losing skirmisher in the outer city radius is a
                // tactical contact, not an empire-wide emergency. Recovery is
                // reserved for a locally competitive force or a damaged city
                // whose remaining defenders cannot safely absorb another hit.
                let critical = danger >= 0.90
                    || (danger >= 0.45 && (breached || (recently_hit && damaged)));
                critical.then_some((
                    danger,
                    (200 - city.hp).max(0) + (wall_max - city.wall_hp).max(0),
                    cid,
                ))
            })
            .max_by(|left, right| {
                left.0
                    .total_cmp(&right.0)
                    .then_with(|| left.1.cmp(&right.1))
                    .then_with(|| right.2.cmp(&left.2))
            })
            .map(|(_, _, cid)| cid)
    }

    fn religious_opening_rank(g: &Game, pid: usize) -> Option<(u8, f64, f64)> {
        let player = &g.players[pid];
        if !player.alive
            || player.is_minor
            || player.is_barbarian
            || player.religion.is_some()
            || player.prophet_pending
            || g.player_city_ids(pid).len() < 2
        {
            return None;
        }
        let city_ids = g.player_city_ids(pid);
        let has_holy_site = city_ids
            .iter()
            .any(|cid| g.cities[cid].districts.contains_key(crate::name!("holy_site")));
        let holy_site_planned = city_ids.iter().any(|cid| {
            matches!(
                g.cities[cid].queue.first(),
                Some(Item::District { district, .. }) if district == "holy_site"
            )
        });
        let best_site = city_ids
            .iter()
            .flat_map(|cid| g.district_sites(*cid, crate::name!("holy_site")))
            .map(|pos| g.district_yields(crate::name!("holy_site"), pos).faith)
            .max_by(f64::total_cmp);
        if !has_holy_site && !holy_site_planned && best_site.is_none() {
            return None;
        }
        // Once an empire has paid toward the race, keep that commitment ahead
        // of an uninvested late entrant. The remaining comparisons select the
        // best available Holy Site and faith economy instead of requiring the
        // unusually rare +3 adjacency that previously left most maps with a
        // single founder.
        let commitment = if has_holy_site {
            4
        } else if holy_site_planned {
            3
        } else if player.techs.contains(&crate::name!("astrology")) {
            2
        } else if player.research.as_deref() == Some("astrology") {
            1
        } else {
            0
        };
        Some((commitment, best_site.unwrap_or(0.0), player.faith))
    }

    /// What the Diplomacy lane is worth *before* it has produced anything.
    ///
    /// ⚠ **The asymmetry this repairs.** Every other lane in `best_lane` scores
    /// prospectively — Religion is handed **46** for nothing more than
    /// `religious_opening_viable`, and 55 once a rival has founded. Diplomacy
    /// alone scored `dvp * 5 + suzerain * 6`, which is **purely
    /// retrospective**: zero until the empire already holds diplomatic points
    /// or a suzerainty. The lane is chosen by an argmax over those scores, so a
    /// zero cannot be chosen, and a lane that is never chosen never emits the
    /// influence that would raise the score. **A self-fulfilling zero**, and it
    /// shows: the adaptive census puts Diplomacy at **0.9% of observed
    /// player-turns** against Conquest's 26%, while diplomatic victories (19)
    /// and domination victories (22) arrive at nearly the same rate.
    ///
    /// The prize is on record as the largest in the repository.
    /// `Grant::Suzerain` — suzerain of every met city-state — measured
    /// **56.7% against a 22.7% control**, p=0.0000 over 400 maps (PR #602),
    /// larger than the expansion grant, and unlike expansion it is a decision
    /// the agent makes. The envoy census then found the pool sits at **0.00
    /// unspent**, which reads as a resource gap — but a lane that is never
    /// entered is exactly why the resource is never produced.
    ///
    /// **The number is mirrored, not tuned.** It is Religion's own opening
    /// figure, so Diplomacy loses every tie to Religion — deliberately, because
    /// Religion is the lane that actually converts here (88% of wins). What
    /// this can win is the argmax against **Conquest and Expansion, which score
    /// 0**, in the games where the religious opening is closed. That is the
    /// 26%-of-turns lane converting at 4%.
    ///
    /// Zero unless diplomatic victory is enabled and some met city-state is
    /// still unclaimed, so a game without the condition or without a free minor
    /// is untouched.
    fn diplomatic_opening_score(&self, g: &Game, pid: usize) -> i64 {
        if !self.diplomatic_opening || !g.victory_conditions.diplomatic {
            return 0;
        }
        let claimable = g.players.iter().any(|minor| {
            minor.alive
                && minor.is_minor
                && !minor.is_barbarian
                && g.has_met(pid, minor.id)
                && g.suzerain_of(minor.id) != Some(pid)
        });
        if claimable {
            DIPLOMATIC_OPENING
        } else {
            0
        }
    }

    fn religious_opening_viable(&self, g: &Game, pid: usize) -> bool {
        let player = &g.players[pid];
        if player.religion.is_some() {
            return false;
        }
        if player.prophet_pending {
            return true;
        }
        let founded = g.religions_founded();
        let pending = g
            .players
            .iter()
            .filter(|candidate| candidate.prophet_pending)
            .count();
        let claimed = founded + pending;
        if claimed >= g.max_religions()
            || g.turn > if founded > 0 { 180 } else { 120 }
            || Self::religious_opening_rank(g, pid).is_none()
        {
            return false;
        }

        // Prophet slots are a global race. Let exactly the best uncommitted
        // contenders pursue the slots that remain, while still allowing a
        // newly founded rival religion to trigger a genuine counter-race.
        let open_slots = g.max_religions() - claimed;
        let mut contenders: Vec<_> = g
            .players
            .iter()
            .filter_map(|candidate| {
                Self::religious_opening_rank(g, candidate.id).map(|rank| (candidate.id, rank))
            })
            .collect();
        contenders.sort_by(|(left_id, left), (right_id, right)| {
            right
                .0
                .cmp(&left.0)
                .then_with(|| right.1.total_cmp(&left.1))
                .then_with(|| right.2.total_cmp(&left.2))
                .then_with(|| left_id.cmp(right_id))
        });
        contenders
            .into_iter()
            .take(open_slots)
            .any(|(contender, _)| contender == pid)
    }

    fn rocketry_readiness(&self, g: &Game, pid: usize) -> i32 {
        let player = &g.players[pid];
        let rocketry_path: Vec<_> = g
            .rules
            .techs
            .keys()
            .filter(|tech| self.tech_leads_to(g, tech, "rocketry"))
            .collect();
        let completed = rocketry_path
            .iter()
            .filter(|tech| player.techs.contains(&Name::new(tech.as_str())))
            .count();
        25 + (40 * completed / rocketry_path.len().max(1)) as i32
    }

    fn diplomatic_science_backup(&self, g: &Game, pid: usize, plan: &StrategicPlan) -> bool {
        self.victory_target.is_none()
            && g.victory_conditions.science
            && plan.strategy == GrandStrategy::Diplomacy
            && g.turn >= g.standard_duration(220)
            && self.rocketry_readiness(g, pid) >= 45
    }

    fn religious_conversion_tally(&self, g: &Game, pid: usize) -> (usize, usize) {
        let living_majors: Vec<usize> = g
            .players
            .iter()
            .filter(|player| player.alive && !player.is_minor && !player.is_barbarian)
            .map(|player| player.id)
            .collect();
        let converted = g.players[pid].religion.as_ref().map_or(0, |religion| {
            living_majors
                .iter()
                .filter(|other| {
                    let cities = g.player_city_ids(**other);
                    let following = cities
                        .iter()
                        .filter(|city| g.city_religion(&g.cities[city]) == Some(religion.as_str()))
                        .count();
                    !cities.is_empty() && following * 2 > cities.len()
                })
                .count()
        });
        (converted, living_majors.len())
    }

    fn victory_focus(&self, g: &Game, pid: usize) -> VictoryFocus {
        if let Some(target) = self.active_victory_target(g) {
            return VictoryFocus {
                strategy: target.strategy(),
                progress: 100,
            };
        }
        if !self.victory_planning {
            let preferred = if !self.civ_blind && g.players[pid].civ == "Greece" {
                GrandStrategy::Culture
            } else {
                GrandStrategy::Science
            };
            let strategy = [
                preferred,
                GrandStrategy::Science,
                GrandStrategy::Culture,
                GrandStrategy::Religion,
                GrandStrategy::Diplomacy,
                GrandStrategy::Conquest,
                GrandStrategy::Expansion,
            ]
            .into_iter()
            .find(|strategy| Self::victory_strategy_enabled(g, *strategy))
            .unwrap_or(GrandStrategy::Science);
            return VictoryFocus {
                strategy,
                progress: 25,
            };
        }
        let player = &g.players[pid];
        let living_majors: Vec<usize> = g
            .players
            .iter()
            .filter(|p| p.alive && !p.is_minor && !p.is_barbarian)
            .map(|p| p.id)
            .collect();

        // A science race starts long before the first launch.  Treating every
        // pre-space empire as exactly 25% complete made a strong researcher
        // abandon science as soon as even modest tourism appeared.  The tech
        // tree is public victory-screen information and gives the planner a
        // smooth signal until the discrete space-race milestones take over.
        let tech_progress =
            25 + (30 * player.techs.len() / g.rules.techs.len().max(1)).min(30) as i32;
        let project_progress = player.science_projects.len().min(4) as i32 * 18;
        let travel_progress = if player.science_projects.contains("exoplanet_expedition") {
            (player.exoplanet_distance * 100.0 / 50.0).clamp(0.0, 100.0) as i32
        } else {
            0
        };
        // A launch program cannot raise project progress until the AI has
        // already chosen Science long enough to unlock Rocketry and build a
        // Spaceport. Count progress along that prerequisite path so adaptive
        // agents can make the initial commitment instead of remaining stuck
        // at the old 25% floor forever.
        let readiness = self.rocketry_readiness(g, pid);
        let science = tech_progress
            .max(readiness)
            .max(project_progress)
            .max(travel_progress)
            .max((!self.civ_blind && player.civ == "China") as i32 * 45);

        let culture_target = living_majors
            .iter()
            .filter(|other| **other != pid)
            .map(|other| g.domestic_tourists(*other))
            .max()
            .unwrap_or(1)
            .max(1);
        let culture = ((100 * g.foreign_tourists(pid) / culture_target).clamp(0, 100)) as i32;

        let (converted, living_religious_rivals) = self.religious_conversion_tally(g, pid);
        let religion = if player.religion.is_some() {
            // Founding a religion normally converts the founder's own small
            // empire first. That is table stakes, not progress against a
            // Religious Victory: counting it made every founder jump from the
            // 40-point commitment floor to 55 in a four-player game before it
            // had converted a single rival. Measure expansion into foreign
            // civilizations here; rival threat scoring below still counts all
            // living majors because the actual victory rule does too.
            let religion = player.religion.as_deref().unwrap();
            let own_cities = g.player_city_ids(pid);
            let own_following = own_cities
                .iter()
                .filter(|city| g.city_religion(&g.cities[city]) == Some(religion))
                .count();
            let own_converted = !own_cities.is_empty() && own_following * 2 > own_cities.len();
            let foreign_converted = converted.saturating_sub(usize::from(own_converted));
            let foreign_rivals = living_religious_rivals.saturating_sub(1);
            40 + (60 * foreign_converted / foreign_rivals.max(1)) as i32
        } else if self.religious_opening_viable(g, pid) {
            if g.religions_founded() > 0 {
                55
            } else {
                46
            }
        } else {
            0
        };

        let suzerain = g
            .players
            .iter()
            .filter(|minor| {
                minor.alive
                    && minor.is_minor
                    && !minor.is_barbarian
                    && g.suzerain_of(minor.id) == Some(pid)
            })
            .count() as i64;
        let diplomacy = (player.dvp * 5 + suzerain * 6)
            .clamp(0, 100)
            .max(self.diplomatic_opening_score(g, pid))
            as i32;

        let candidates = [
            VictoryFocus {
                strategy: GrandStrategy::Science,
                progress: science,
            },
            VictoryFocus {
                strategy: GrandStrategy::Culture,
                progress: culture
                    .max((!self.civ_blind && player.civ == "Greece") as i32 * 45),
            },
            VictoryFocus {
                strategy: GrandStrategy::Religion,
                progress: religion,
            },
            VictoryFocus {
                strategy: GrandStrategy::Diplomacy,
                progress: diplomacy,
            },
            VictoryFocus {
                strategy: GrandStrategy::Conquest,
                progress: 0,
            },
            VictoryFocus {
                strategy: GrandStrategy::Expansion,
                progress: 0,
            },
        ];
        let mut enabled = candidates
            .into_iter()
            .filter(|candidate| Self::victory_strategy_enabled(g, candidate.strategy));
        let mut best = enabled.next().unwrap_or(VictoryFocus {
            strategy: GrandStrategy::Science,
            progress: science,
        });
        for candidate in enabled {
            if candidate.progress > best.progress {
                best = candidate;
            }
        }
        best
    }

    /// Public victory-screen information distilled into a single urgency
    /// signal. Strong opponents must be judged by how close they are to ending
    /// the game, not only by how cheap their nearest city looks to capture.
    fn rival_victory_pressure(&self, g: &Game, pid: usize) -> VictoryFocus {
        self.rival_victory_pressure_with_culture(g, pid, None)
    }

    fn rival_victory_pressure_with_culture(
        &self,
        g: &Game,
        pid: usize,
        culture_pressure: Option<i32>,
    ) -> VictoryFocus {
        let player = &g.players[pid];
        let starting_majors: Vec<usize> = g
            .players
            .iter()
            .filter(|candidate| !candidate.is_minor && !candidate.is_barbarian)
            .map(|candidate| candidate.id)
            .collect();
        let living_majors: Vec<usize> = starting_majors
            .iter()
            .copied()
            .filter(|candidate| g.players[*candidate].alive)
            .collect();

        let science = if player.science_projects.contains("exoplanet_expedition") {
            // The final expedition is an irreversible endgame commitment.  A
            // defender needs time to raise, route, and deploy a counterforce,
            // so its launch itself must cross the generic denial threshold;
            // waiting for the first six light-years discarded that reaction
            // window while the rival was already on the victory clock.
            78 + (22.0 * player.exoplanet_distance / 50.0).clamp(0.0, 22.0) as i32
        } else if player.science_projects.contains("launch_mars_colony") {
            65
        } else if player.science_projects.contains("launch_moon_landing") {
            45
        } else if player.science_projects.contains("launch_earth_satellite") {
            25
        } else {
            0
        };

        let culture = culture_pressure.unwrap_or_else(|| {
            let culture_target = living_majors
                .iter()
                .filter(|other| **other != pid)
                .map(|other| g.domestic_tourists(*other))
                .max()
                .unwrap_or(1)
                .max(1);
            (100 * g.foreign_tourists(pid) / culture_target).clamp(0, 100) as i32
        });

        let (converted, living_religious_rivals) = self.religious_conversion_tally(g, pid);
        let religion = if player.religion.is_some() {
            (100 * converted / living_religious_rivals.max(1)) as i32
        } else {
            0
        };
        let diplomacy = (player.dvp * 5).clamp(0, 100) as i32;

        let foreign_capitals = starting_majors
            .iter()
            .filter(|owner| **owner != pid)
            .count();
        let controlled_capitals = g
            .cities
            .values()
            .filter(|city| city.is_capital && city.original_owner != pid && city.owner == pid)
            .count();
        let domination = (100 * controlled_capitals)
            .checked_div(foreign_capitals)
            .unwrap_or(0) as i32;

        // The shipped score term is a clock, not an observation: it fires only
        // in the last quarter of the game, so at the recorded large map size --
        // where most games are decided on score at the turn limit -- the alarm
        // it raises arrives at turn 300 of 400 for every leader alike,
        // regardless of how far ahead they are.
        //
        // The census says score is the one instrument that predicts: at the
        // recorded large profile the score leader is the eventual winner 62% of
        // the time **200 turns out** against a 16.7% base rate, and settles on
        // them a median 135 turns before the end, while `victory_threat` sits
        // at or below the base rate at four of five leads. `early_score_alarm`
        // reads the margin instead of the clock -- 78 at 20% ahead of the next
        // empire, 100 at 50% ahead -- from the moment an early game has
        // enough history to mean anything.
        let score = if self.early_score_alarm && g.turn >= g.standard_duration(60) {
            let mine = g.score(pid);
            let best_rival = living_majors
                .iter()
                .filter(|candidate| **candidate != pid)
                .map(|candidate| g.score(*candidate))
                .max()
                .unwrap_or(0)
                .max(1);
            let margin = mine as f64 / best_rival as f64 - 1.0;
            if margin <= 0.0 {
                0
            } else if margin < 0.20 {
                (78.0 * margin / 0.20) as i32
            } else {
                (78.0 + 22.0 * ((margin - 0.20) / 0.30).clamp(0.0, 1.0)) as i32
            }
        } else if g.max_turns > 0
            && g.turn.saturating_mul(4) >= g.max_turns.saturating_mul(3)
            && living_majors
                .iter()
                .map(|candidate| g.score(*candidate))
                .max()
                == Some(g.score(pid))
        {
            (40 + 60 * g.turn.min(g.max_turns) / g.max_turns) as i32
        } else {
            0
        };

        [
            VictoryFocus {
                strategy: GrandStrategy::Science,
                progress: science,
            },
            VictoryFocus {
                strategy: GrandStrategy::Culture,
                progress: culture,
            },
            VictoryFocus {
                strategy: GrandStrategy::Religion,
                progress: religion,
            },
            VictoryFocus {
                strategy: GrandStrategy::Diplomacy,
                progress: diplomacy,
            },
            VictoryFocus {
                strategy: GrandStrategy::Conquest,
                progress: domination,
            },
            VictoryFocus {
                strategy: GrandStrategy::Expansion,
                progress: score,
            },
        ]
        .into_iter()
        .filter(|focus| Self::victory_strategy_enabled(g, focus.strategy))
        .max_by_key(|focus| focus.progress)
        .unwrap_or(VictoryFocus {
            strategy: GrandStrategy::Recovery,
            progress: 0,
        })
    }

    /// Compute every living rival's culture-race pressure in one table.
    ///
    /// A single `rival_victory_pressure` calculation asks for every rival's
    /// domestic tourists, and `victory_denial` asks for that pressure for
    /// every rival. Repeating those nested scans made the denial pass cubic in
    /// civilization count. Domestic and foreign tourist totals are public
    /// table state, so calculate each once and reuse them across the pass.
    fn rival_culture_pressures(&self, g: &Game) -> BTreeMap<usize, i32> {
        let living_majors: Vec<usize> = g
            .players
            .iter()
            .filter(|player| player.alive && !player.is_minor && !player.is_barbarian)
            .map(|player| player.id)
            .collect();
        let domestic: BTreeMap<usize, i64> = living_majors
            .iter()
            .map(|pid| (*pid, g.domestic_tourists(*pid)))
            .collect();
        living_majors
            .iter()
            .map(|pid| {
                let target = living_majors
                    .iter()
                    .filter(|other| *other != pid)
                    .map(|other| domestic[other])
                    .max()
                    .unwrap_or(1)
                    .max(1);
                (
                    *pid,
                    (100 * g.foreign_tourists(*pid) / target).clamp(0, 100) as i32,
                )
            })
            .collect()
    }

    fn victory_denial(&self, g: &Game, pid: usize) -> Option<(usize, GrandStrategy)> {
        if !self.deny_leaders || self.active_victory_target(g).is_some() {
            return None;
        }
        let culture_pressures = self.rival_culture_pressures(g);
        self.victory_denial_with_culture_pressures(g, pid, &culture_pressures)
    }

    /// A Conquest denial needs a destination the mirrored army can reach.
    ///
    /// Firaxis publishes a rival's score and victory progress before this
    /// mirror necessarily has a position for any of their cities. That is
    /// still a useful warning for Congress and in-lane counters, but an army
    /// cannot answer it. Otherwise a cityless leader can set Conquest while
    /// the target selector keeps pursuing an unrelated war already under way.
    /// The frozen anchor retains its historical all-information behaviour.
    fn conquest_denial_actionable(
        &self,
        g: &Game,
        pid: usize,
        rival: usize,
        counter: GrandStrategy,
    ) -> bool {
        counter != GrandStrategy::Conquest
            || !self.battlefront_observation
            || (self.campaign_target_legal(g, pid, rival)
                && !g.player_city_ids(rival).is_empty())
    }

    /// The denial response that can actually change an army plan. Keep the
    /// raw signal in [`Self::victory_denial`] for pressure reporting and
    /// non-military counters.
    fn actionable_victory_denial(&self, g: &Game, pid: usize) -> Option<(usize, GrandStrategy)> {
        self.victory_denial(g, pid).filter(|(rival, counter)| {
            self.conquest_denial_actionable(g, pid, *rival, *counter)
        })
    }

    fn victory_denial_with_culture_pressures(
        &self,
        g: &Game,
        pid: usize,
        culture_pressures: &BTreeMap<usize, i32>,
    ) -> Option<(usize, GrandStrategy)> {
        let own_progress = self.victory_focus(g, pid).progress;
        let (rival, pressure) = g
            .players
            .iter()
            .filter(|player| {
                player.id != pid && player.alive && !player.is_minor && !player.is_barbarian
            })
            .map(|player| {
                (
                    player.id,
                    self.rival_victory_pressure_with_culture(
                        g,
                        player.id,
                        culture_pressures.get(&player.id).copied(),
                    ),
                )
            })
            .max_by(|left, right| {
                left.1
                    .progress
                    .cmp(&right.1.progress)
                    .then_with(|| right.0.cmp(&left.0))
            })?;
        // Religious progress advances in whole-civilization jumps, and a
        // defender needs time to produce and route religious counters. Start
        // reacting with two holdouts left when the rival also leads our own
        // race, then treat one remaining holdout as an unconditional match
        // point: a slower "close" victory must not suppress that interrupt.
        if pressure.strategy == GrandStrategy::Religion {
            let living = g
                .players
                .iter()
                .filter(|player| player.alive && !player.is_minor && !player.is_barbarian)
                .count()
                .max(1) as i32;
            let match_point = 100 * living.saturating_sub(1) / living;
            let early_warning = (100 * living.saturating_sub(2) / living)
                .max(50)
                .min(match_point);
            if pressure.progress < early_warning
                || (pressure.progress < match_point && pressure.progress < own_progress + 15)
            {
                return None;
            }
        } else if pressure.progress < 78 || pressure.progress < own_progress + 15 {
            return None;
        }
        // Four of the seven races answer themselves — a culture threat is met
        // with culture, a religious one with religion. The two that answer with
        // an army are Science and Expansion, and those are the two the
        // recorded large-profile census argues against: at 60x38 and 74x46 an
        // empire fighting one or two rivals wins 4.4% and 10.7% of the time
        // against a 16.7% base rate, and the shipped response already costs terminal
        // score (44 maps to 65, p=0.055) without buying a win. Racing the
        // leader in their own lane keeps the reaction and drops the war.
        // The decomposition arm: react to the other four races unchanged and
        // to these two not at all, so the effect of dropping the war can be
        // read apart from the effect of adopting the lane.
        if self.counter_stand_down
            && matches!(
                pressure.strategy,
                GrandStrategy::Science | GrandStrategy::Expansion
            )
        {
            return None;
        }
        let counter = match pressure.strategy {
            GrandStrategy::Science if self.counter_in_lane => GrandStrategy::Science,
            GrandStrategy::Science => GrandStrategy::Conquest,
            GrandStrategy::Culture => GrandStrategy::Culture,
            GrandStrategy::Religion if g.players[pid].religion.is_some() => GrandStrategy::Religion,
            GrandStrategy::Religion => GrandStrategy::Conquest,
            GrandStrategy::Diplomacy => GrandStrategy::Diplomacy,
            GrandStrategy::Conquest => GrandStrategy::Recovery,
            GrandStrategy::Expansion if self.counter_in_lane => GrandStrategy::Expansion,
            GrandStrategy::Expansion => GrandStrategy::Conquest,
            GrandStrategy::Recovery => GrandStrategy::Recovery,
        };
        Some((rival, counter))
    }

    /// Terminal clocks require action before an ordinary Formal War countdown
    /// or a comfortable force ratio is available. Keep this predicate shared
    /// between declaration timing and campaign readiness so either response
    /// cannot silently become more permissive than the other.
    fn urgent_victory_threat(&self, g: &Game, target: usize) -> bool {
        if !self.deny_leaders {
            return false;
        }
        let pressure = self.rival_victory_pressure(g, target);
        let living_majors = g
            .players
            .iter()
            .filter(|player| player.alive && !player.is_minor && !player.is_barbarian)
            .count()
            .max(1) as i32;
        let religious_match_point = 100 * living_majors.saturating_sub(1) / living_majors;
        pressure.progress >= 90
            || (pressure.strategy == GrandStrategy::Science && pressure.progress >= 78)
            || (pressure.strategy == GrandStrategy::Religion
                && pressure.progress >= religious_match_point)
    }

    /// Diagnostic seam: what this planner believes `target`'s best race is,
    /// and how far along it reads. These are the exact numbers the denial
    /// layer gates on, exposed so a census can compare them against
    /// [`Game::victory_threat`] instead of re-deriving the formula — a second
    /// implementation is how a HUD and an AI end up disagreeing about who is
    /// about to win. Reads nothing from `self`, so any planner may ask.
    pub fn rival_pressure(&self, g: &Game, target: usize) -> (GrandStrategy, i32) {
        let focus = self.rival_victory_pressure(g, target);
        (focus.strategy, focus.progress)
    }

    /// Diagnostic seam: the rival this empire would move against right now and
    /// the counter-strategy it would adopt, or `None` when nobody clears the
    /// bar. Same actionable call `replan_needed` and `assess` make.
    pub fn denial_target(&self, g: &Game, pid: usize) -> Option<(usize, GrandStrategy)> {
        self.actionable_victory_denial(g, pid)
    }

    /// Diagnostic seam: whether `target`'s clock is short enough to skip the
    /// ordinary war-readiness checks.
    pub fn denial_is_urgent(&self, g: &Game, target: usize) -> bool {
        self.urgent_victory_threat(g, target)
    }

    fn assess(&self, g: &Game, pid: usize) -> StrategicPlan {
        let cities = g.player_city_ids(pid);
        let my_power = g.military_power(pid);
        let major_rivals: Vec<usize> = g
            .players
            .iter()
            .filter(|p| {
                p.id != pid
                    && p.alive
                    && !p.is_minor
                    && !p.is_barbarian
                    // A mirror retains empty seats for civilizations the host has
                    // not introduced. Their generated zero power must not make a
                    // real, met rival look weak enough to attack. This is part of
                    // live fog observation, not the frozen advanced_v1 anchor.
                    && (!self.battlefront_observation
                        || g.has_met(pid, p.id)
                        || g.is_at_war(pid, p.id))
            })
            .map(|p| p.id)
            .collect();
        // City-states follow their Suzerain into wars and can also be attacked
        // directly. Once hostilities exist they are real campaign actors, not
        // an uncoordinated side task for whichever unit happens to be nearby.
        let wartime_rivals: Vec<usize> = g
            .players
            .iter()
            .filter(|p| p.id != pid && p.alive && !p.is_barbarian && g.is_at_war(pid, p.id))
            .map(|p| p.id)
            .collect();
        let wartime_majors: Vec<usize> = wartime_rivals
            .iter()
            .copied()
            .filter(|rival| !g.players[*rival].is_minor)
            .collect();
        let at_war = !wartime_rivals.is_empty();
        let strongest_rival = major_rivals
            .iter()
            .map(|o| g.military_power(*o))
            .fold(0.0_f64, f64::max);
        let weakest_rival = major_rivals
            .iter()
            .map(|o| g.military_power(*o))
            .fold(f64::INFINITY, f64::min);

        let threatened_city = self.threatened_city(g, pid);
        // ★★★★ A WAR WHOSE PATIENCE HAS RUN OUT NO LONGER SETS THE GRAND
        // STRATEGY. "Already at war" used to pin the plan on Conquest for as
        // long as the enemy declined peace, whatever the war was doing. Run
        // civvis-20260815T233405Z declared on Babylon at t57 (221 power
        // against 158), took no city in 190 turns, had its bounded patience
        // lapse at t128 and its peace offers refused thirteen times, and read
        // Conquest on 63 of 142 assessments (Recovery on 63 more): a whole
        // game of war-driven production while science sat at 45–59 for fifty
        // turns and the score finished 637 against 1237. Once patience has
        // lapsed and no city of ours is critically threatened, the war is a
        // stalemate the empire cannot end and should stop paying for: the plan
        // falls through to the economic lanes, and the local-defence
        // treatments — home defence, garrison under fire, garrison walls —
        // answer raids whatever the grand strategy says. A foreign city
        // acquired (`last_campaign_progress`) or a critical threat restores
        // the war posture. Behind `war_patience`, which the frozen anchor
        // never sets.
        let stalemate = at_war
            && self.war_patience
            && threatened_city.is_none()
            && self.war_patience_exhausted(g);

        let land = g
            .map
            .tiles
            .values()
            .filter(|t| g.rules.is_passable(t) && !g.rules.is_water(t))
            .count();
        let map_capacity = if self.wide_map_capacity {
            // Live-bridge pricing: one city per 45 passable tiles, ceiling
            // twelve. A fresh live mirror knows the world's dimensions but
            // deliberately carries only revealed terrain, so its counted
            // passable land is smallest precisely when expansion must begin.
            // Treat fog as unknown capacity, not proof of a three-city map.
            // Practical-site checks still stop production when sites run out.
            //
            // The floor answers the opening; the fogged MIDDLE game is what
            // `fog_land_capacity` answers, by reading the land share of what
            // is known across the whole board. See that flag.
            let land = if self.fog_land_capacity {
                Self::fog_land_estimate(g, land)
            } else {
                land
            };
            (2 + land / 45)
                .clamp(3, 12)
                .max(PRODUCTION_CITY_TARGET_FLOOR)
        } else {
            (2 + land / 55).clamp(3, 9)
        };
        // Expansion must compound before it pays back. Add roughly one city
        // per era instead of continuously raising the target and starving a
        // young empire of districts, buildings, and population growth. Scale
        // the cadence with game speed; the old fixed turn-175 cutoff expired
        // before the five-city target even became active on Standard speed.
        // See `era_paced_expansion`: an era of the Settler game is forty
        // Online turns, not sixty.
        let city_cadence = g
            .standard_duration(if self.era_paced_expansion { 60 } else { 90 })
            .max(1) as usize;
        // Historical controls keep the old six-city planning ceiling. The
        // production delegation flag is also the compatibility boundary that
        // lets the promoted controller consume the full land-aware capacity.
        let city_ceiling = if self.plan_city_target {
            map_capacity
        } else {
            map_capacity.min(6)
        };
        // The deployed wide treatment formerly changed only the late ceiling,
        // leaving the current live opening bound at three cities. Start that
        // plan at the measured six-city floor; ordinary Advanced and the
        // frozen anchor retain three.
        let city_floor = if self.wide_map_capacity {
            self.city_target_floor.max(PRODUCTION_CITY_TARGET_FLOOR)
        } else {
            self.city_target_floor
        };
        let desired_cities =
            (city_floor + g.turn as usize / city_cadence).min(city_ceiling);
        let mut expansion_origins: Vec<Pos> = cities.iter().map(|cid| g.cities[cid].pos).collect();
        if expansion_origins.is_empty() {
            expansion_origins.extend(
                g.player_unit_ids(pid)
                    .into_iter()
                    .filter(|uid| g.units[uid].kind == "settler")
                    .map(|uid| g.units[&uid].pos),
            );
        }
        let has_site = expansion_origins.iter().any(|pos| {
            self.best_settle_site(g, pid, *pos, 10).is_some()
                || (g.players[pid].techs.contains(&crate::name!("shipbuilding"))
                    && self
                        .best_settle_site(g, pid, *pos, g.map.width + g.map.height)
                        .is_some())
        });

        let military_civ = matches!(
            g.players[pid].civ.as_str(),
            "Sumeria" | "Aztec" | "Nubia" | "Scythia" | "Byzantium"
        );
        let basil_tagma_timing = g.has_ability(pid, "taxis")
            && (g.players[pid].religion.is_some()
                || g.players[pid].civics.contains(&crate::name!("divine_right")));
        // The ancient rush is a *window*, not a preference, so it is decided
        // beside the other timing arm rather than among the victory lanes.
        let rush_victim = self.early_rush_victim(g, pid);
        let victory = self.victory_focus(g, pid);
        // Target selection needs the same public culture-race totals as
        // victory denial. Build them once for the assessment instead of
        // repeating a whole-world tourism scan for every sort comparison.
        let active_victory_target = self.active_victory_target(g);
        let rival_culture_pressures = self.rival_culture_pressures(g);
        let denial = if active_victory_target.is_some() {
            None
        } else {
            self.victory_denial_with_culture_pressures(g, pid, &rival_culture_pressures)
        };
        let actionable_denial = denial.filter(|(rival, counter)| {
            self.conquest_denial_actionable(g, pid, *rival, *counter)
        });
        let emergency_objective = g.emergency_objective(pid).cloned();
        // Each arm carries the reason it fired. The strings are static and
        // cost nothing to build; they exist so the spectator's reasoning log
        // can say which of these tests the empire's whole plan turned on
        // instead of only naming the strategy that came out.
        // ⚠ Recovery is documented one screen down as "a temporary battlefield
        // posture", and this branch is the only thing that makes it permanent.
        // A threatened city IS transient — the attacker leaves or the city
        // falls. A power gap against a runaway leader is not: Recovery does not
        // build an army, so `my_power * 1.25 < strongest_rival` stays true
        // precisely because Recovery is what we chose, and it re-fires every
        // assessment for the rest of the game.
        //
        // Measured on `civvis-20260802T205959Z` (Sweden, Settler, small): the
        // journal names this exact arm — "at war and losing ground at home" —
        // **160 times**, matching all 160 Recovery turns. The empire held that
        // posture from t65 to t229, 72% of the game, peaking at 4 cities on t61
        // and holding 1 by t85. It finished with ONE warrior, military 34
        // against the Mapuche's 1354, score 205 against 1324.
        //
        // So the power-gap half is bounded and the threatened-city half is not.
        // Local defence no longer depends on this posture in any case: #930's
        // `besieged_city_item` builds walls or a defender for a city with a
        // raiding party at its gates before the ordinary build order, whatever
        // the grand strategy says.
        //
        // ⚠ The bound is measured against the WAR's age, not the plan's. Keyed
        // on `major_war_since`, it releases Recovery until the war ends rather
        // than re-arming after one assessment. Replayed against the real
        // `civvis-20260802T205959Z`
        // mirror that produced a 1-in-25 duty cycle — recovery 86% -> 81%, with
        // only 5 of 93 assessed turns changed, at t87, t153, t176, t201 and
        // t219, each ~25 turns apart. `major_war_since` is monotone for as long
        // as the war lasts, so a posture that has already been given its turns
        // stays released until the war ends.
        let recovery_is_stale = self.bounded_recovery
            && self.major_war_since.is_some_and(|started| {
                g.turn.saturating_sub(started)
                    >= g.standard_duration(RECOVERY_POSTURE_LIMIT).max(1)
            });
        // A stale Recovery normally gives the planner permission to pursue a
        // different win condition. It must not turn a collapsing major war
        // into an offensive denial the army cannot possibly execute: recent
        // live losses repeatedly held 14--41% of the leader's power at this
        // point. Preserve ordinary terminal counters; this is only the live
        // bridge's already-stale, already-at-war, less-than-half-power case.
        let impossible_denial = self.battlefront_observation
            && recovery_is_stale
            && !wartime_majors.is_empty()
            && actionable_denial.is_some_and(|(rival, counter)| {
                counter == GrandStrategy::Conquest
                    && my_power * 2.0 < g.military_power(rival)
            });
        let (strategy, because) = if at_war
            && (threatened_city.is_some() || (my_power * 1.25 < strongest_rival && !recovery_is_stale))
        {
            (
                GrandStrategy::Recovery,
                "at war and losing ground at home",
            )
        } else if impossible_denial {
            (
                GrandStrategy::Recovery,
                "holding the line before an impossible counter-campaign",
            )
        } else if emergency_objective.is_some() {
            (
                GrandStrategy::Conquest,
                "an emergency objective is standing",
            )
        } else if basil_tagma_timing {
            (
                GrandStrategy::Conquest,
                "Tagma timing is live",
            )
        } else if rush_victim.is_some() {
            (
                GrandStrategy::Conquest,
                "a neighbour is inside the ancient window and cannot wall in time",
            )
        } else if let Some(target) = active_victory_target {
            if target == VictoryTarget::Religion
                && g.players[pid].religion.is_none()
            {
                (
                    GrandStrategy::Religion,
                    "the religion lane still needs a religion",
                )
            } else if cities.len() < desired_cities && has_site && g.turn < g.standard_duration(175)
            {
                (
                    GrandStrategy::Expansion,
                    "the assigned lane can still afford to expand first",
                )
            } else {
                (
                    target.strategy(),
                    "following the assigned victory lane",
                )
            }
        } else if let Some((_, counter)) = actionable_denial {
            (
                counter,
                "countering a rival close to winning",
            )
        } else if at_war && !stalemate {
            (
                GrandStrategy::Conquest,
                "already at war",
            )
        } else if !stalemate
            // ★★★★ Not on the live seat: see `no_elective_war` — eight games,
            // no city ever taken, sixteen lost.
            && !self.no_elective_war
            && ((g.turn >= 55 && cities.len() >= 2 && my_power > weakest_rival * 1.80 + 20.0)
                || (military_civ
                    && g.turn >= 35
                    && cities.len() >= 2
                    && my_power >= strongest_rival * 1.10))
        {
            (
                GrandStrategy::Conquest,
                "strong enough to take what a neighbour has",
            )
        } else if self.expansion_before_prophet
            && cities.len() < EXPANSION_BEFORE_PROPHET_CITIES
            && has_site
            && self.adaptive_expansion_window_open(g)
            && self.religious_opening_viable(g, pid)
        {
            // ★★★★ The Prophet branch below assumes "the rest of the empire"
            // keeps settling while one city races; with one or two cities the
            // capital is the whole empire, and on the live Settler seat the
            // race was never close. See `expansion_before_prophet`. Only the
            // Religion outcome is displaced: every other branch runs as before.
            (
                GrandStrategy::Expansion,
                "the third city comes before the Prophet",
            )
        } else if self.religious_opening_viable(g, pid) {
            // A Prophet is a finite global race, not an economic goal that can
            // wait until the generic city target is complete. Religious
            // production only occupies one city, so the baseline governor can
            // continue settlers and development in the rest of the empire.
            // Keep that commitment independent of the generic progress race:
            // improving a contender's science readiness must not make it
            // abandon a nearly earned, globally limited Prophet.
            (
                GrandStrategy::Religion,
                "a Prophet is a finite race worth entering now",
            )
        } else if victory.progress >= 65 {
            (
                victory.strategy,
                "already well down its best victory lane",
            )
        } else if cities.len() < desired_cities
            && has_site
            && self.adaptive_expansion_window_open(g)
        {
            (
                GrandStrategy::Expansion,
                "short of cities with land still open",
            )
        } else {
            (
                victory.strategy,
                "its best available victory lane",
            )
        };
        think!(self.journal(), Strategy, Strategy,
               "Grand strategy: {}", strategy.as_str();
               "{because} — {} cities of {desired_cities} wanted, power {my_power:.0} \
                against the strongest rival's {strongest_rival:.0}; \
                best lane {} at {}% progress",
               cities.len(), victory.strategy.as_str(), victory.progress);
        if stalemate && strategy != GrandStrategy::Conquest {
            think!(self.journal(), Strategy, Strategy,
                   "The war is a stalemate the plan stops paying for";
                   "still at war, but no foreign city captured in {} turns and none of ours in \
                    danger — the economy runs as in peacetime while local defence answers raids",
                   g.turn.saturating_sub(self.last_campaign_progress));
        }
        if let Some(city) = threatened_city.and_then(|id| g.cities.get(&id)) {
            think!(self.journal(), Strategy, Strategy,
                   "{} is under threat", city.name;
                   "the plan is written around defending it"; city.pos);
        }

        // Finish wars already in progress before selecting the next major
        // rival. In particular, this gives hostile city-states an explicit
        // city objective that the force-group planner can actually consume.
        let forced_target = self.forced_target_player.filter(|target| {
            g.players.get(*target).map(|player| player.alive).unwrap_or(false)
                && self.campaign_target_legal(g, pid, *target)
        });
        let target_player = if let Some(emergency) = &emergency_objective {
            Some(emergency.target)
        } else if wartime_rivals.is_empty() {
            // The rush already chose, on nearness and weakness, and the
            // generic value sort would happily re-aim the column at a richer
            // rival two weeks' march away.
            rush_victim.map(|(target, _)| target).or_else(|| {
            forced_target.or_else(|| {
                actionable_denial
                    .filter(|(rival, _)| self.campaign_target_legal(g, pid, *rival))
                    .map(|(rival, _)| rival)
                    .or_else(|| {
                        let mut candidates: Vec<_> = major_rivals
                            .iter()
                            .copied()
                            .filter(|rival| self.campaign_target_legal(g, pid, *rival))
                            .collect();
                        if strategy == GrandStrategy::Conquest {
                            candidates.extend(
                                g.players
                                    .iter()
                                    .filter(|player| player.is_minor)
                                    .filter(|player| {
                                        self.campaign_target_legal(g, pid, player.id)
                                    })
                                    .map(|player| player.id),
                            );
                        }
                        candidates
                            .into_iter()
                            .map(|rival| {
                                (
                                    rival,
                                    self.campaign_target_value_with_culture(
                                        g,
                                        pid,
                                        rival,
                                        rival_culture_pressures.get(&rival).copied(),
                                    ),
                                )
                            })
                            .min_by(|a, b| {
                                a.1.partial_cmp(&b.1)
                                    .unwrap()
                                    .then(a.0.cmp(&b.0))
                            })
                            .map(|(rival, _)| rival)
                    })
            })
            })
        } else {
            // A suzerained city-state joins its major's war, but it is not a
            // reason to abandon the weaker major city the campaign was staged
            // to capture. Only make a city-state the primary front when there
            // is no living major war left to finish.
            let active_fronts = if wartime_majors.is_empty() {
                &wartime_rivals
            } else {
                &wartime_majors
            };
            active_fronts
                .iter()
                .copied()
                .map(|rival| {
                    (
                        rival,
                        self.rival_value_with_culture(
                            g,
                            pid,
                            rival,
                            rival_culture_pressures.get(&rival).copied(),
                        ),
                    )
                })
                .min_by(|a, b| {
                    a.1.partial_cmp(&b.1)
                        .unwrap()
                        .then(a.0.cmp(&b.0))
                })
                .map(|(rival, _)| rival)
        };
        let ranked_target_city = emergency_objective
            .as_ref()
            .map(|emergency| emergency.city)
            // The rush aims at the capital and nothing else. A capital is the
            // one city whose loss can end a small neighbour outright, it is
            // where `city_strength`'s palace +3 is paid for by having the
            // whole empire's defence in one place, and the generic
            // `campaign_city_value` sort would otherwise send the column at
            // whichever border town scored best.
            .or_else(|| {
                rush_victim.filter(|(target, _)| target_player == Some(*target))
                    .map(|(_, capital)| capital)
            })
            .or_else(|| {
                target_player.and_then(|target| {
                    g.cities
                        .values()
                        .filter(|c| c.owner == target)
                        .min_by(|left, right| {
                            self.campaign_city_value(g, pid, left, strategy)
                                .total_cmp(&self.campaign_city_value(g, pid, right, strategy))
                                .then_with(|| left.id.cmp(&right.id))
                        })
                        .map(|c| c.id)
                })
            });

        // A campaign objective is a commitment, not a continuously refreshed
        // preference. The city scorer below rightly ranks a fresh objective
        // when a war opens and after a capture, but its distance and fog terms
        // also change while an army is marching. Re-ranking that city every
        // five turns made a superior force walk Batumi -> Tbilisi -> Kutaisi
        // without firing enough shots to take any of them. Keep the existing
        // foreign objective through an active major war while it is still
        // enemy-owned. A home emergency deliberately remains a hard override;
        // a city-state is excluded because its diplomacy has its own reclaim
        // path rather than a major-war capture campaign.
        let committed_target_city = if self.siege_commitment && emergency_objective.is_none() {
            target_player
                .filter(|target| {
                    g.is_at_war(pid, *target)
                        && g.players.get(*target).is_some_and(|player| {
                            !player.is_minor && !player.is_barbarian
                        })
                })
                .and_then(|target| {
                    self.plan
                        .as_ref()
                        .filter(|prior| prior.target_player == Some(target))
                        .and_then(|prior| prior.target_city)
                        .filter(|city| {
                            g.cities
                                .get(city)
                                .is_some_and(|city| city.owner == target)
                        })
                })
        } else {
            None
        };
        let target_city = committed_target_city.or(ranked_target_city);

        if let Some(committed_city) =
            committed_target_city.filter(|city| Some(*city) != ranked_target_city)
        {
            let city = &g.cities[&committed_city];
            think!(self.journal(), Strategy, Strategy,
                   "Campaign remains aimed at {}", city.name;
                   "the major-war army stays committed until it captures the city or its war target changes";
                   city.pos);
        }

        if self.journal().wants(crate::reasoning::Level::Strategy) {
            match target_player.and_then(|id| g.players.get(id)) {
                Some(rival) => {
                    let objective = target_city
                        .and_then(|id| g.cities.get(&id))
                        .map(|city| format!("first objective {}", city.name))
                        .unwrap_or_else(|| "no city objective yet".to_string());
                    let at_war_now = if g.is_at_war(pid, rival.id) {
                        "already at war"
                    } else if wartime_rivals.is_empty() {
                        "not yet at war"
                    } else {
                        "chosen from the wars already running"
                    };
                    think!(self.journal(), Strategy, Strategy,
                           "Campaign aimed at {}", rival.civ;
                           "{at_war_now}; {objective}");
                }
                None => {
                    think!(self.journal(), Strategy, Strategy, "No campaign target";
                           "no rival is both reachable and worth opening against");
                }
            }
        }

        StrategicPlan {
            strategy,
            target_player,
            target_city,
            threatened_city,
            desired_cities,
            assessed_turn: g.turn,
            // Only a plan that actually aims at the victim is a rush. If
            // something later in target selection re-aimed the campaign, the
            // production bonus must not follow it.
            rush: rush_victim.is_some_and(|(victim, _)| target_player == Some(victim)),
        }
    }

    /// Whether a settler built *here, now* would still pay for itself.
    ///
    /// `expansion_window_open` reserves a flat `standard_duration(50)` at the
    /// end of every game for every city, whatever that city can actually do.
    /// A city making 20 production a turn builds a settler in four turns; one
    /// making three takes twenty-seven. A single reserve is wrong for both, and
    /// `expansion_funnel_blocker_census` measures the cost of being wrong in
    /// the strict direction: on the recorded 6p/74x46 profile, the
    /// shut window is the **sole** blocker on 310 of 993 city-turns spent short
    /// of the empire's own city target — 31.2% of them.
    ///
    /// This asks the question the reserve was standing in for. Time enough to
    /// build the settler at this city's real production rate, walk it out, and
    /// then hold the ground long enough to return more than it cost.
    /// The whole board's passable land, extrapolated from the share of the
    /// KNOWN plots that are passable land. Never below `counted_land`, and
    /// equal to it on a board with no unknown terrain. See `fog_land_capacity`.
    pub(crate) fn fog_land_estimate(g: &Game, counted_land: usize) -> usize {
        let mut known = 0usize;
        let mut known_land = 0usize;
        for tile in g.map.tiles.values() {
            if g.rules.is_unknown(tile) {
                continue;
            }
            known += 1;
            if g.rules.is_passable(tile) && !g.rules.is_water(tile) {
                known_land += 1;
            }
        }
        if known == 0 {
            return counted_land;
        }
        let total = g.map.tiles.len();
        (known_land.saturating_mul(total) / known).max(counted_land)
    }

    fn expansion_pays_back_for(&self, g: &Game, pid: usize, cid: u32) -> bool {
        let remaining = g.max_turns.saturating_sub(g.turn) as f64;
        let production = g.city_yields(cid).production.max(1.0);
        let build = g.item_remaining_cost_for_city(
            pid,
            cid,
            &Item::Unit {
                unit: "settler".into(),
            },
        ) / production;
        remaining > build + g.standard_duration(SETTLE_LAG + SETTLE_PAYBACK) as f64
    }

    /// The stock adaptive-expansion deadline: a payoff horizon, bounded by
    /// the unchanged endgame reserve.
    fn stock_expansion_deadline(g: &Game) -> u32 {
        g.standard_duration(300)
            .min(g.max_turns.saturating_sub(g.standard_duration(50)))
    }

    /// The deadline for the late-window treatment. It deliberately removes
    /// only the absolute cap; the reserve is still part of the policy.
    fn late_expansion_deadline(g: &Game) -> u32 {
        g.max_turns.saturating_sub(g.standard_duration(50))
    }

    fn expansion_window_open(g: &Game) -> bool {
        g.turn < Self::stock_expansion_deadline(g)
    }

    fn late_expansion_window_open(g: &Game) -> bool {
        g.turn < Self::late_expansion_deadline(g)
    }

    fn adaptive_expansion_window_open(&self, g: &Game) -> bool {
        if self.late_expansion {
            Self::late_expansion_window_open(g)
        } else {
            Self::expansion_window_open(g)
        }
    }

    /// The interval the late-window treatment adds over stock. This is
    /// expressed from the live game-speed formulas so measurement cannot drift
    /// into a hard-coded Online turn range when duration scaling changes.
    fn newly_opened_late_window(g: &Game) -> bool {
        g.turn >= Self::stock_expansion_deadline(g) && g.turn < Self::late_expansion_deadline(g)
    }

    fn settler_expansion_window_open(&self, g: &Game, pid: usize, cid: u32) -> bool {
        if self.expansion_pays_back {
            self.expansion_pays_back_for(g, pid, cid)
        } else if self.victory_target.is_some() {
            // Assigned lanes have always carried a distinct cutoff. Neither
            // adaptive experiment is allowed to widen it.
            g.turn < g.standard_duration(175)
        } else {
            self.adaptive_expansion_window_open(g)
        }
    }

    /// Run the proven baseline city governor with the strategic expansion
    /// contract temporarily threaded through it.
    ///
    /// The historical treatment replaced the four-city gene with an early
    /// three-city plan and predictably made the opening smaller. Production
    /// takes the maximum instead: the plan may widen a governor, never narrow
    /// it. The speed-aware deadline similarly extends the raw turn-150 gene on
    /// slower or longer games without removing the endgame reserve.
    fn delegated_cities(&mut self, g: &mut Game, pid: usize, plan: &StrategicPlan) {
        if !self.plan_city_target {
            self.base.cities(g, pid);
            return;
        }
        let restore_target = self.base.w.city_target;
        let restore_stop = self.base.w.settler_stop_turn;
        let restore_builders = self.base.w.builder_per_city;
        self.base.w.city_target = restore_target.max(plan.desired_cities as f64);
        // The last production-only override this audit had not priced. Whether
        // it binds at all depends on the speed: the gene is 150 and the
        // deadline is `min(300 standard, max_turns - 50 standard)`, which at
        // Online/250 may already be at or below it.
        if self.production_settler_deadline {
            self.base.w.settler_stop_turn =
                restore_stop.max(Self::stock_expansion_deadline(g) as f64);
        }
        // ⚠ A call-local override with no arm until 2026-08-11. It raises the
        // genome's 0.5 by half again, is reachable only from inside this
        // function, and `docs/EVAL.md` had never mentioned it — the same
        // profile as the four flags this audit found carrying stale comments
        // and no number, one of which cost 41 Elo. Its justification is
        // reasoning, not measurement: "three active Builders per four cities
        // provide roughly two useful improvements per city".
        if self.production_builder_floor {
            self.base.w.builder_per_city = restore_builders.max(PRODUCTION_BUILDERS_PER_CITY);
        }
        self.base.cities(g, pid);
        self.base.w.city_target = restore_target;
        self.base.w.settler_stop_turn = restore_stop;
        self.base.w.builder_per_city = restore_builders;
    }

    /// Lower is a more attractive rival: nearby, weak empires with valuable
    /// cities are preferable to distant low-power distractions.
    #[cfg(test)]
    fn rival_value(&self, g: &Game, pid: usize, other: usize) -> f64 {
        self.rival_value_with_culture(g, pid, other, None)
    }

    fn rival_value_with_culture(
        &self,
        g: &Game,
        pid: usize,
        other: usize,
        culture_pressure: Option<i32>,
    ) -> f64 {
        let mine = g.player_city_ids(pid);
        let theirs = g.player_city_ids(other);
        let distance = mine
            .iter()
            .flat_map(|a| {
                theirs
                    .iter()
                    .map(move |b| g.wdist(g.cities[a].pos, g.cities[b].pos))
            })
            .min()
            .unwrap_or(40) as f64;
        let victory_pressure = self
            .rival_victory_pressure_with_culture(g, other, culture_pressure)
            .progress as f64;
        distance * 7.0 + g.military_power(other) * 1.5
            - g.score(other) as f64 * 0.35
            - victory_pressure * 2.4
    }

    /// Campaign value extends the major-rival heuristic to city-states.
    /// Conquering a city-state is strategically possible, but it burns every
    /// invested Envoy and permanently removes a potential Suzerain bonus, so
    /// a nearby minor should displace a major target only when it is a clearly
    /// cheaper objective. A city-state that can be secured immediately with
    /// free Envoys is treated as an ally to win, not territory to destroy.
    fn campaign_target_legal(&self, g: &Game, pid: usize, other: usize) -> bool {
        let Some(player) = g.players.get(other) else {
            return false;
        };
        if other == pid || !player.alive || player.is_barbarian {
            return false;
        }

        // Preserve an already active war even if a loaded legacy position has
        // contradictory diplomacy. Outside war, relationship commitments are
        // hard legality masks, never soft terms in the positional score.
        if g.is_at_war(pid, other) {
            return true;
        }
        // A host only supplies public score, military, and city facts after the
        // seat has met a civilization. The generated slots left behind for every
        // other civilization are placeholders, not actors we may target.
        if self.battlefront_observation && !g.has_met(pid, other) {
            return false;
        }
        if g.are_friends(pid, other) || g.alliance_with(pid, other).is_some() {
            return false;
        }
        if player.is_minor {
            let Some(suzerain) = g.suzerain_of(other) else {
                return true;
            };
            if suzerain == pid
                || g.are_friends(pid, suzerain)
                || g.alliance_with(pid, suzerain).is_some()
            {
                return false;
            }
        }
        true
    }

    #[cfg(test)]
    fn campaign_target_value(&self, g: &Game, pid: usize, other: usize) -> f64 {
        self.campaign_target_value_with_culture(g, pid, other, None)
    }

    fn campaign_target_value_with_culture(
        &self,
        g: &Game,
        pid: usize,
        other: usize,
        culture_pressure: Option<i32>,
    ) -> f64 {
        let mut value = self.rival_value_with_culture(g, pid, other, culture_pressure);
        if !g.players[other].is_minor {
            // A leader marches on the civilizations their agenda disdains
            // before the ones it respects. Lower is a more attractive target,
            // so approval raises the bar and contempt lowers it. The weight
            // is deliberately smaller than distance, which still decides most
            // campaigns: an agenda colours the choice, it does not make it.
            return value + g.agenda_opinion(pid, other) * 2.0;
        }

        let mine = g.envoys_at(pid, other);
        value += 90.0 + mine as f64 * 45.0;
        let rival_envoys = g
            .players
            .iter()
            .filter(|player| !player.is_minor && !player.is_barbarian && player.id != pid)
            .map(|player| g.envoys_at(player.id, other))
            .max()
            .unwrap_or(0);
        let needed = (3_i64.max(rival_envoys + 1) - mine).max(1);
        if g.players[pid].envoys_free >= needed {
            value += 180.0;
        }
        if let Some(suzerain) = g.suzerain_of(other).filter(|suzerain| *suzerain != pid) {
            value += 40.0 + g.military_power(suzerain) * 0.25;
        }
        value += match g.cs_type(&g.players[other].civ) {
            "militaristic" => 55.0,
            "industrial" => 35.0,
            "scientific" | "cultural" | "religious" => 25.0,
            _ => 15.0,
        };
        value
    }

    /// Fraction of the game still to be played, clamped to `[0, 1]`.
    ///
    /// The horizon every research term is scaled by. A game past its turn limit
    /// (the mirror runs one turn beyond it) reports 0 rather than a negative.
    /// How much the live race's wonder bonus grows with the game's progress:
    /// ×1 at the start, ×2 at the midpoint, ×3 at the tally. See
    /// `live_wonder_race`.
    fn live_wonder_race_scale(g: &Game) -> f64 {
        let progress = if g.max_turns > 0 {
            (g.turn as f64 / g.max_turns as f64).clamp(0.0, 1.0)
        } else {
            0.0
        };
        1.0 + LIVE_WONDER_RACE_LATE_SCALE * progress
    }

    /// How many wonders the live race keeps in production at once: one, plus
    /// one per `LIVE_WONDER_RACE_CITIES_PER_LANE` cities. See `live_wonder_race`.
    fn live_wonder_race_lanes(city_count: usize) -> usize {
        1 + city_count / LIVE_WONDER_RACE_CITIES_PER_LANE
    }

    /// The amenity a district of `family` unlocks through the first-tier
    /// amenity building the player can already build there (an Arena's +2 for
    /// an Entertainment Complex), discounted because it is a second build.
    /// Zero for a family with no such building. See `amenity_district_path`.
    fn hosted_amenity_path(g: &Game, pid: usize, family: &Name) -> f64 {
        let player = &g.players[pid];
        let hosted = g
            .rules
            .buildings
            .iter()
            .filter(|(_, spec)| {
                !spec.wonder
                    && spec.amenity > 0.0
                    && spec.requires.is_empty()
                    && spec.requires_any.is_empty()
                    && spec
                        .district
                        .is_some_and(|district| g.district_family(district) == *family)
                    && spec
                        .unique_to
                        .as_deref()
                        .is_none_or(|civ| civ == player.civ.as_str())
                    && spec.tech.as_ref().is_none_or(|tech| player.techs.contains(tech))
                    && spec
                        .civic
                        .as_ref()
                        .is_none_or(|civic| player.civics.contains(civic))
            })
            .map(|(_, spec)| spec.amenity)
            .fold(0.0, f64::max);
        hosted * HOSTED_AMENITY_DISCOUNT
    }

    /// The extra weight a regional amenity building earns from the other own
    /// cities it would reach that no copy already reaches, in the same units
    /// as the local `30 + 22 × need` term. Zero for a building with no range.
    /// See `amenity_district_path`.
    fn regional_amenity_reach(
        g: &Game,
        pid: usize,
        city: &crate::game::City,
        building: &Name,
        spec: &crate::rules::BuildingSpec,
    ) -> f64 {
        if spec.regional_range <= 0 || spec.amenity <= 0.0 {
            return 0.0;
        }
        let range = spec.regional_range;
        let own: Vec<&crate::game::City> =
            g.cities.values().filter(|other| other.owner == pid).collect();
        own.iter()
            .filter(|other| other.id != city.id && g.wdist(city.pos, other.pos) <= range)
            .filter(|other| {
                // Non-stacking: a city a standing copy already reaches gains
                // nothing from a second one.
                !own.iter().any(|source| {
                    source.buildings.contains(building)
                        && g.wdist(source.pos, other.pos) <= range
                })
            })
            .map(|other| {
                let need = (-g.city_amenity_surplus(other)).max(0) as f64;
                (30.0 + need * 22.0) * REGIONAL_AMENITY_REACH_DISCOUNT
            })
            .sum()
    }

    fn research_horizon(g: &Game) -> f64 {
        let budget = g.max_turns.max(1) as f64;
        ((budget - g.turn as f64) / budget).clamp(0.0, 1.0)
    }

    /// Can a Campus begun now still repay itself? Full value while more than
    /// `RESEARCH_CAMPUS_PAYBACK` of the budget remains, ramping to zero inside
    /// that window. See the constant for why a game-fraction horizon was the
    /// wrong shape for a district that repays in a few dozen turns.
    fn campus_payback_horizon(g: &Game) -> f64 {
        let budget = g.max_turns.max(1) as f64;
        let window = (budget * RESEARCH_CAMPUS_PAYBACK).max(1.0);
        ((budget - g.turn as f64) / window).clamp(0.0, 1.0)
    }

    /// Set this turn's science floor. Called once per decision, before any
    /// pricing runs.
    fn refresh_research_weight(&mut self, g: &Game) {
        self.research_weight = if self.research_economy {
            let horizon = Self::research_horizon(g);
            RESEARCH_FLOOR_LATE + (RESEARCH_FLOOR_EARLY - RESEARCH_FLOOR_LATE) * horizon
        } else {
            0.0
        };
    }

    fn yield_value(&self, yields: Yields, strategy: GrandStrategy) -> f64 {
        let (food, prod, gold, science, culture, faith): (f64, f64, f64, f64, f64, f64) =
            match strategy {
            GrandStrategy::Expansion => (2.0, 2.2, 0.9, 1.2, 1.2, 0.5),
            GrandStrategy::Science => (1.4, 2.0, 1.0, 4.2, 1.2, 0.4),
            GrandStrategy::Culture => (1.4, 1.8, 1.0, 1.3, 4.2, 0.8),
            GrandStrategy::Religion => (1.4, 1.8, 0.9, 1.1, 1.5, 4.5),
            GrandStrategy::Diplomacy => (1.4, 1.7, 2.2, 1.2, 2.8, 0.7),
            // War changes the production mix; it does not make the technology and
            // civic trees optional. In the live controller, culture at 0.8 remained
            // the empire's least valuable ordinary yield for eighty wartime turns,
            // even after the army had grown to 85 units. Keep production dominant,
            // but retain a real research/civic floor so a long campaign can unlock
            // upgrades, governments, and economic cards.
            GrandStrategy::Conquest if self.victory_planning => {
                (1.2, 2.8, 1.4, 1.9, 1.2, 0.3)
            }
            GrandStrategy::Recovery if self.victory_planning => {
                (1.6, 3.2, 1.5, 1.2, 1.1, 0.3)
            }
            GrandStrategy::Conquest => (1.2, 2.8, 1.4, 1.7, 0.8, 0.3),
            GrandStrategy::Recovery => (1.6, 3.2, 1.5, 1.0, 0.8, 0.3),
        };
        // The anchor above is the *lane's* opinion of a beaker and is left
        // exactly as promoted. `research_weight` is a floor under it, not a
        // replacement: the Science lane's 4.2 always wins, and with
        // `research_economy` off the floor is 0.0 and this line is a no-op.
        let science = science.max(self.research_weight);
        // See `tally_culture`: on the tally seat a point of culture buys at
        // least what a point of science buys.
        let culture = if self.tally_culture && strategy != GrandStrategy::Culture {
            culture.max(science)
        } else {
            culture
        };
        yields.food * food
            + yields.production * prod
            + yields.gold * gold
            + yields.science * science
            + yields.culture * culture
            + yields.faith * faith
    }

    /// Evaluate a repeatable district project as a bounded race move. The
    /// ongoing conversion is valued over the actual build horizon, while the
    /// completion award is priced against the live global Great Person race.
    /// This is deliberately analogous to an engine's passed-pawn extension:
    /// a project receives a large tempo bonus only when completing it crosses
    /// a concrete threshold, rather than from a fixed name-based preference.
    fn district_project_value(
        &self,
        g: &Game,
        pid: usize,
        cid: u32,
        project: &str,
        plan: &StrategicPlan,
    ) -> f64 {
        let spec = &g.rules.projects[project];
        let city = &g.cities[&cid];
        let production = g.city_yields(cid).production.max(1.0);
        let item = Item::Project {
            project: Name::new(project),
        };
        let turns = g.item_remaining_cost_for_city(pid, cid, &item) / production;
        let threatened = plan.threatened_city == Some(cid)
            || (city.last_attacked > 0 && g.turn.saturating_sub(city.last_attacked) <= 4);
        let denominator = 7.0 + turns.max(1.0);

        let mut ongoing = Yields::default();
        for (kind, percent) in &spec.ongoing_yields {
            let amount = production * percent / 100.0;
            match kind.as_str() {
                "food" => ongoing.food += amount,
                "production" => ongoing.production += amount,
                "gold" => ongoing.gold += amount,
                "science" => ongoing.science += amount,
                "culture" => ongoing.culture += amount,
                "faith" => ongoing.faith += amount,
                _ => {}
            }
        }
        let horizon = turns.clamp(1.0, 16.0);
        let mut value = self.yield_value(ongoing, plan.strategy) * horizon * 4.0;

        for (kind, award) in g.project_completion_gpp_awards(pid, cid, project) {
            // Patronage outcome B can set this class's completion award to
            // zero. Ongoing yield conversion may still justify the project,
            // but a disabled class has no race tempo to extend.
            if award <= f64::EPSILON {
                continue;
            }
            // A class race is not necessarily a usable named offer. Firaxis can
            // offer Hildegard of Bingen as a Scientist to an empire with no Holy
            // Site, or Mary Leakey to one with no Theater. The live mirror carries
            // that hard prerequisite separately from this simulator's generic
            // class model; once it says the current offer cannot activate, GPP has
            // no race tempo to extend. Ongoing project yields remain above.
            if g.live_great_person_offer_blocker(pid, &kind).is_some() {
                continue;
            }
            let mut affinity: f64 = match (plan.strategy, kind.as_str()) {
                (GrandStrategy::Science, "scientist") => 2.5,
                (GrandStrategy::Culture, "writer" | "artist" | "musician") => 2.6,
                (GrandStrategy::Religion, "prophet") if g.players[pid].religion.is_none() => 2.8,
                (GrandStrategy::Diplomacy, "merchant") => 2.0,
                (GrandStrategy::Conquest, "general" | "admiral") => 2.3,
                (GrandStrategy::Expansion | GrandStrategy::Recovery, "engineer" | "merchant") => {
                    1.8
                }
                (GrandStrategy::Science | GrandStrategy::Culture, "engineer") => 1.6,
                (_, "prophet") if g.players[pid].religion.is_some() => 0.15,
                _ => 0.85,
            };
            let work = match kind.as_str() {
                "writer" => Some("writing"),
                "artist" => Some("art"),
                "musician" => Some("music"),
                _ => None,
            };
            if work.is_some_and(|work| !g.can_house_additional_great_work(pid, work)) {
                affinity *= 0.20;
            }

            let cost = g.gp_cost(pid, &kind).max(1.0);
            let mine = g.players[pid].gpp.get(&kind).copied().unwrap_or(0.0);
            let rival = g
                .players
                .iter()
                .filter(|player| {
                    player.id != pid && player.alive && !player.is_minor && !player.is_barbarian
                })
                .map(|player| player.gpp.get(&kind).copied().unwrap_or(0.0))
                .fold(0.0_f64, f64::max);
            let useful = award.min((cost - mine).max(0.0));
            value += useful * (5.0 + 5.0 * affinity);
            value += (rival / cost).clamp(0.0, 1.0) * 150.0 * affinity;
            if mine + award + f64::EPSILON >= cost && mine < cost {
                value += 620.0 * affinity;
            }
            if rival > mine && mine + award > rival {
                value += 240.0 * affinity;
            }
        }

        if spec.full_power_while_active {
            let deficit = (g.city_power_demand(city) - g.city_power_supply(city)).max(0.0);
            value += deficit * 55.0 * denominator;
        }

        if project == "bread_and_circuses" {
            let loyalty_need = (100.0 - city.loyalty).max(0.0);
            let nearby_foreign_pressure = g
                .cities
                .values()
                .filter(|other| {
                    other.owner != pid
                        && !g.players[other.owner].is_barbarian
                        && g.alliance_with(pid, other.owner)
                            .is_none_or(|alliance| alliance.kind != "cultural")
                })
                .filter_map(|other| {
                    let distance = g.wdist(city.pos, other.pos);
                    (distance <= 9)
                        .then_some(other.pop.max(1) as f64 * (10 - distance) as f64 / 10.0)
                })
                .sum::<f64>();
            if loyalty_need < 5.0 && nearby_foreign_pressure < 2.0 {
                value -= 260.0;
            } else {
                value += loyalty_need * 8.0
                    + nearby_foreign_pressure * horizon * 7.0
                    + spec
                        .effects
                        .get("completion_loyalty")
                        .copied()
                        .unwrap_or(0.0)
                        * 7.0;
            }
        }

        // A project may exploit completed infrastructure, but should not
        // indefinitely postpone the first building in the district that
        // enables it. This is the economic equivalent of a quiet-move pruning
        // guard: search the forcing race only after basic development exists.
        if let Some(district) = spec.district {
            let family = g.district_family(district);
            let has_family_building = city.buildings.iter().any(|building| {
                g.rules.buildings[building]
                    .district
                    .is_some_and(|built| g.district_family(built) == family)
            });
            let family_has_building = g.rules.buildings.values().any(|building| {
                building.buildable
                    && building
                        .district
                        .is_some_and(|built| g.district_family(built) == family)
            });
            if family_has_building && !has_family_building {
                value -= 420.0;
            }
        }
        if threatened {
            value -= 360.0;
        }
        // ★★★★ THE CHEAP HALF OF A RESEARCH CITY BEFORE THE RACE IN IT. See
        // `buildings_before_projects`.
        if self.buildings_before_projects && spec.repeatable {
            let waiting_for = BUILDINGS_BEFORE_PROJECTS.iter().chain(
                CULTURE_BUILDINGS_BEFORE_PROJECTS
                    .iter()
                    .take(if self.culture_building_debt { 4 } else { 0 }),
            );
            let owed = waiting_for.into_iter().any(|building| {
                g.rules.buildings.contains_key(*building)
                    && g.can_produce(
                        pid,
                        cid,
                        &Item::Building {
                            building: Name::new(building),
                        },
                    )
            });
            if owed {
                value = value.min(PROJECT_BEHIND_BUILDINGS_CAP);
            }
        }
        value
    }

    fn product_layout_value(&self, g: &Game, pid: usize, strategy: GrandStrategy) -> f64 {
        let _memo = g.query_memo();
        g.player_city_ids(pid)
            .into_iter()
            .map(|city_id| {
                let city = &g.cities[&city_id];
                let mut value = self.yield_value(g.city_yields(city_id), strategy);
                // Housing beyond +3 no longer changes the immediate growth
                // rate. Valuing only the useful band sends Salt Products to
                // constrained cities instead of accumulating them in a city
                // that already has abundant headroom.
                let headroom = (g.city_housing(city) - city.pop as f64).clamp(-2.0, 3.0);
                value += headroom * 18.0;
                let active_salt = city
                    .products
                    .iter()
                    .take(g.product_capacity(city))
                    .filter(|product| product.as_str() == "salt")
                    .count() as f64;
                value += active_salt * city.pop.max(1) as f64 * 2.5;
                value
            })
            .sum()
    }

    /// Products are movable economic Great Works. Search every legal move on
    /// a cloned position and make one only when it strictly improves the
    /// strategy-sensitive empire evaluation; the strict threshold prevents a
    /// free relocation from oscillating between equivalent slots.
    fn advanced_products(&self, g: &mut Game, pid: usize, strategy: GrandStrategy) {
        let candidates: BTreeSet<(u32, u32, Name)> = g
            .legal_actions_within(pid, ActionFamilies::PRODUCTS)
            .into_iter()
            .filter_map(|action| match action {
                Action::MoveProduct { from, to, product } => Some((from, to, product)),
                _ => None,
            })
            .collect();
        let baseline = self.product_layout_value(g, pid, strategy);
        let mut best: Option<(f64, u32, u32, Name)> = None;
        for (from, to, product) in candidates {
            let action = Action::MoveProduct {
                from,
                to,
                product: Name::new(&product),
            };
            let mut next = g.speculative_clone();
            if next.apply(pid, &action).is_err() {
                continue;
            }
            let value = self.product_layout_value(&next, pid, strategy);
            let replace = best.as_ref().is_none_or(|current| {
                value > current.0 + 1e-9
                    || ((value - current.0).abs() <= 1e-9
                        && (to, from, product.as_str())
                            < (current.2, current.1, current.3.as_str()))
            });
            if replace {
                best = Some((value, from, to, product));
            }
        }
        let Some((value, from, to, product)) = best else {
            return;
        };
        if value <= baseline + 0.01 {
            return;
        }
        let _ = g.apply(pid, &Action::MoveProduct { from, to, product: Name::new(&product) });
    }

    /// The tech that makes the live plan's first Campus legal.
    ///
    /// A Campus valuation cannot pay for the technology that unlocks the
    /// district: before Writing, the district is absent from every production
    /// menu. That gap surfaced in live run `civvis-20260815T103152Z`: the
    /// Prophet race correctly chose Astrology at turn 32, but the live housing
    /// goal then chose Wheel toward Engineering at turn 34 and Writing did not
    /// arrive until turn 83. Three Holy Sites and two Theatre Squares filled
    /// the intervening opening without a Campus.
    ///
    /// Keep the finite-race opener and any war or victory beeline above this
    /// handoff. Once an empire has two cities including a legal Campus site,
    /// though, its live coverage promise needs Writing before the optional housing
    /// detour. `campus_every_city` is false for frozen controllers, preserving
    /// the recorded `advanced_v1` research order exactly.
    fn first_campus_tech(&self, g: &Game, pid: usize) -> Option<&'static str> {
        if !self.campus_every_city
            || g.players[pid].techs.contains(&crate::name!("writing"))
        {
            return None;
        }
        let campus = crate::name!("campus");
        let cities = g.player_city_ids(pid);
        (cities.len() >= 2
            && cities
                .iter()
                .any(|city| !g.district_sites(*city, campus).is_empty()))
        .then_some("writing")
    }

    /// The technology behind the best Campus building this empire is already
    /// equipped to use and cannot research its way to on merit.
    ///
    /// ## Why a goal is needed and a weight is not enough
    ///
    /// `advanced_research`'s ordinary path is an argmax of `tech_value` over
    /// `available_techs` — **the nodes whose prerequisites are already met.** A
    /// node one step further out is not scored low, it is *not present*. So a
    /// valuable technology sitting behind a worthless one is unreachable no
    /// matter what it is worth.
    ///
    /// That is exactly what the live games do, and #958 is the control that
    /// proves it. Run `civvis-20260803T082856Z` finished turn 251 with **seven
    /// cities, six Campuses, six Universities and zero Research Labs**:
    ///
    /// | tech | held | unlocks |
    /// |---|---|---|
    /// | `scientific_theory` | yes | — |
    /// | **`sanitation`** | **no** | Sewer, Medic — nothing this planner wants |
    /// | **`chemistry`** | **no, and never *available*** | **`research_lab`** |
    /// | `replaceable_parts` | yes | — |
    ///
    /// The empire took Replaceable Parts — one of Chemistry's two prerequisites
    /// — and went on to Composites, Plastics and Combined Arms, while Chemistry
    /// stayed out of reach behind a Sewer. #958 raised what a Research Lab is
    /// worth to `tech_value` by 2.1-2.5x and changed nothing, because the node
    /// was never in the list being scored.
    ///
    /// ## What this returns
    ///
    /// The most valuable science building whose **district and prerequisite
    /// building the empire already owns** and whose technology it does not.
    /// Owning the Campus and the University is the whole qualification: it means
    /// the empire has already paid for everything except the node, so the node
    /// is worth a detour. An empire with no Campus is not sent shopping for
    /// Chemistry.
    ///
    /// Data-driven rather than naming Chemistry, so the same rule reaches
    /// Education for a Library-only empire and keeps working if the ruleset
    /// moves a building to a different node.
    fn unreachable_science_building_tech(&self, g: &Game, pid: usize) -> Option<&'static str> {
        if !self.research_economy {
            return None;
        }
        let campus = crate::name!("campus");
        let equipped: Vec<&crate::game::City> = g
            .cities
            .values()
            .filter(|city| city.owner == pid)
            .filter(|city| {
                city.districts
                    .keys()
                    .any(|district| g.district_family(*district) == campus)
            })
            .collect();
        if equipped.is_empty() {
            return None;
        }
        let mut best: Option<(f64, &str)> = None;
        for spec in g.rules.buildings.values() {
            if spec.wonder || spec.yields.science <= 0.0 {
                continue;
            }
            if spec.district.map(|d| g.district_family(d)) != Some(campus) {
                continue;
            }
            let Some(tech) = spec.tech.as_deref() else {
                continue;
            };
            if g.players[pid].techs.contains(&Name::new(tech)) {
                continue;
            }
            // Every prerequisite building must already stand somewhere the
            // district does, or this is a goal the empire cannot cash in.
            let ready = equipped.iter().any(|city| {
                spec.requires
                    .iter()
                    .all(|needed| city.buildings.iter().any(|built| built == needed))
            });
            if !ready {
                continue;
            }
            if best.is_none_or(|(science, _)| spec.yields.science > science) {
                best = Some((spec.yields.science, tech));
            }
        }
        best.map(|(_, tech)| Box::leak(tech.to_string().into_boxed_str()) as &'static str)
    }

    /// The tech that lets a housing-capped empire raise its own ceiling.
    ///
    /// ⚠⚠ THE RESEARCH CHOOSER HAS A GOAL FOR SCIENCE AND NONE FOR GROWTH, AND
    /// GROWTH IS WHERE THE SCIENCE COMES FROM. Housing is the dominant band:
    /// over 13,214 host-exported city-turns **71.7% are housing-capped**
    /// (headroom < 2) at a mean growth multiplier of **0.510**, against the
    /// Amenity band's 0.872. Science is ~1.16 per citizen, so the housing
    /// ceiling is the science ceiling.
    ///
    /// And the repair is behind a tech the argmax never aims at. Measured over
    /// 94 live runs (median final tech count **30 of 77**):
    ///
    /// | tech | unlocks | runs reaching it | median turn |
    /// |---|---|---|---|
    /// | `writing` | Library | 90% | 59 |
    /// | `education` | University | 73% | 107 |
    /// | **`engineering`** | **Aqueduct** | **73%** | **116** |
    /// | `sanitation` | Sewer | **11%** | 170 |
    /// | `chemistry` | Research Lab | **11%** | 195 |
    ///
    /// So **27% of runs never unlock the Aqueduct at all**, and the ones that do
    /// get it at turn 116 — which is why the live median Aqueduct ORDER lands at
    /// turn 164. Making the district reachable in the build lists (#1087, #1091)
    /// cannot beat the tech that gates it.
    ///
    /// Same shape and the same last-place slot as
    /// `unreachable_science_building_tech`: a goal that exists because the
    /// target is absent from what the argmax will ever take on merit, not
    /// because it ranks below something else. Gated on the empire ACTUALLY being
    /// housing-capped, so a comfortable empire never diverts a beaker to it.
    /// The tech that unlocks the first Walls, when a major war is on (or a
    /// city of ours is threatened), some city of ours has no walls at all and
    /// cannot start them for want of that tech.
    ///
    /// ★★★★ THE WALLS DOCTRINE NEEDS THE WALL TECH. `garrison_walls` and
    /// `besieged_city_item` both put Ancient Walls first for a threatened city
    /// — and both are silent when Masonry is unresearched. Run
    /// civvis-20260816T040537Z: Khmer declared at t61 on a nine-tech empire
    /// with Bronze Working but no Masonry; the research chooser then took Iron
    /// Working, Irrigation, Shipbuilding, Currency and Celestial Navigation
    /// (Masonry "at 16" against Celestial Navigation's 18 on t78) while Rome,
    /// unwalled at defence 27, went 0 → 156 damage from t72 and fell on t79 —
    /// the capital, to a Settler AI. Behind `garrison_walls`, the live walls
    /// doctrine, which the frozen anchor never sets. Asked from the ruleset
    /// (`buildings["walls"].tech`), so a moved unlock stays correct.
    fn walls_tech_goal(&self, g: &Game, pid: usize) -> Option<&'static str> {
        if !self.base.garrison_walls {
            return None;
        }
        let major_war = g.players.iter().any(|other| {
            other.id != pid
                && other.alive
                && !other.is_minor
                && !other.is_barbarian
                && g.is_at_war(pid, other.id)
        });
        if !major_war && self.threatened_city(g, pid).is_none() {
            return None;
        }
        let walls = crate::name!("walls");
        let spec = g.rules.buildings.get(&walls)?;
        let tech = spec.tech.as_ref()?;
        if g.players[pid].techs.contains(tech) {
            return None;
        }
        let unwalled = g.cities.values().any(|city| {
            city.owner == pid
                && !city.buildings.iter().any(|built| {
                    g.rules
                        .buildings
                        .get(built)
                        .is_some_and(|spec| spec.outer_defense > 0)
                })
        });
        if !unwalled {
            return None;
        }
        // The chooser walks the cheapest step toward the goal, so name the
        // tech itself; a static name is what the goal chain carries.
        g.rules
            .techs
            .keys()
            .find(|known| **known == *tech)
            .map(|known| known.as_str())
            .and_then(|name| WALL_TECH_NAMES.iter().copied().find(|w| *w == name))
    }

    fn unreachable_housing_tech(&self, g: &Game, pid: usize) -> Option<&'static str> {
        if !self.housing_research {
            return None;
        }
        // Only when the ceiling is genuinely being paid. `housing_growth_mult`
        // pays 1.0 at headroom 2 and halves below it, so 2 is the break-even.
        let capped = g
            .cities
            .values()
            .filter(|city| city.owner == pid)
            .any(|city| g.city_housing_headroom(city) < HOUSING_CARD_HEADROOM);
        if !capped {
            return None;
        }
        // The cheapest un-researched tech that unlocks a district this empire
        // could actually place. Asking the ruleset rather than naming
        // `engineering` keeps this correct if Firaxis moves the Aqueduct, and
        // picks up the Sewer's tech on the rare game that gets that far.
        let mut best: Option<(f64, &str)> = None;
        for (family, spec) in g.rules.districts.iter() {
            let raises_housing = matches!(family.as_str(), "aqueduct" | "neighborhood");
            if !raises_housing {
                continue;
            }
            let Some(tech) = spec.tech.as_deref() else {
                continue;
            };
            if g.players[pid].techs.contains(&Name::new(tech)) {
                continue;
            }
            let cost = g.rules.techs.get(&Name::new(tech)).map(|t| t.cost).unwrap_or(0.0);
            if best.is_none_or(|(cheapest, _)| cost < cheapest) {
                best = Some((cost, tech));
            }
        }
        best.map(|(_, tech)| Box::leak(tech.to_string().into_boxed_str()) as &'static str)
    }

    fn advanced_research(&self, g: &mut Game, pid: usize, plan: &StrategicPlan) {
        // Explicit evaluator targets and the adaptive live plan must drive the
        // same prerequisite search.  Previously only `victory_target` enabled
        // milestone routing, so a normal spectator AI could correctly assess
        // Science or Culture yet wander through generic unlocks indefinitely.
        let objective = self
            .victory_target
            .map(VictoryTarget::strategy)
            .unwrap_or(plan.strategy);
        if g.players[pid].research.is_none() {
            let available = g.available_techs(pid);
            let science_commitment = objective == GrandStrategy::Science
                || self.diplomatic_science_backup(g, pid, plan);
            let great_person_goal =
                BasicAi::live_great_person_tech_goal(g, pid);
            // ★★★★ A city under attack that cannot wall itself researches the
            // wall before anything else. See `walls_tech_goal`.
            let walls_goal = self.walls_tech_goal(g, pid);
            let forced_goal = match objective {
                _ if walls_goal.is_some() => walls_goal,
                _ if self.war_plan.as_ref().is_some_and(|plan| {
                    !g.players[pid].techs.contains(&plan.breakthrough_tech)
                }) => self
                    .war_plan
                    .as_ref()
                    .map(|plan| plan.breakthrough_tech.as_str()),
                _ if g.has_ability(pid, "taxis")
                    && g.players[pid].religion.is_none()
                    && !g.players[pid].techs.contains(&crate::name!("astrology")) =>
                {
                    Some("astrology")
                }
                // An ancient rush rides. `rush_census` measures **0% of
                // empires holding `horseback_riding` at turn 50**, so the
                // stack is warriors — and a warrior attacking the measured
                // capital takes 28 damage a blow and dies on its fourth,
                // having dealt 134 of the 200 needed. That is the whole
                // reason a war declared at turn 30 does not take a city until
                // turn 53: the stack trades itself, and the next one has to be
                // built and marched all over again.
                //
                // A horseman is strength 36 for 80 production against a
                // warrior's 20 for 40 — it takes 15 a blow instead of 28, so
                // it survives the siege rather than paying for it — and it has
                // **4 movement against 2**, which halves the nine-to-twelve
                // turn march that is the lane's other binding cost. At 195
                // science it is also cheaper to reach than iron working's 225.
                _ if plan.rush && !g.players[pid].techs.contains(&crate::name!("horseback_riding")) => {
                    Some("horseback_riding")
                }
                _ if great_person_goal.is_some() => great_person_goal.as_deref(),
                _ if science_commitment => [
                    "rocketry",
                    "satellites",
                    "nanotechnology",
                    "smart_materials",
                    "offworld_mission",
                ]
                .into_iter()
                .find(|tech| !g.players[pid].techs.contains(&Name::new(tech))),
                GrandStrategy::Culture => ["printing", "radio", "computers"]
                    .into_iter()
                    .find(|tech| !g.players[pid].techs.contains(&Name::new(tech))),
                GrandStrategy::Diplomacy if !g.players[pid].techs.contains(&crate::name!("seasteads")) => {
                    Some("seasteads")
                }
                GrandStrategy::Religion if !g.players[pid].techs.contains(&crate::name!("astrology")) => {
                    Some("astrology")
                }
                _ => None,
            };
            // Last, so no lane loses its own opening to it: a Campus building
            // the empire is already equipped for but cannot reach. This is the
            // only goal here that exists because the target is **absent from
            // the candidate list**, not because it ranks below something else —
            // see `unreachable_science_building_tech`. `goal_pick` below walks
            // the cheapest legal step toward it, which is what crosses the
            // worthless prerequisite the argmax will never take on merit.
            let forced_goal =
                forced_goal.or_else(|| self.unreachable_science_building_tech(g, pid));
            // A live Campus promise has to make its first district legal before
            // an optional housing detour can spend the same slot. Strategy
            // openings above this point (including Astrology) still win; this
            // only bridges their handoff to the production treatment below.
            let forced_goal = forced_goal.or_else(|| self.first_campus_tech(g, pid));
            // And after THAT, the growth ceiling: a Campus the empire can reach
            // still only makes beakers out of citizens it is allowed to have.
            // Behind the science goals on purpose — this never takes a slot the
            // science chain wanted, it takes one the argmax would have spent on
            // whatever happened to be cheapest.
            let forced_goal = forced_goal.or_else(|| self.unreachable_housing_tech(g, pid));
            let goal_pick = forced_goal.and_then(|goal| {
                available
                    .iter()
                    .filter(|tech| self.tech_leads_to(g, tech, goal))
                    .min_by(|a, b| {
                        g.rules.techs[*a]
                            .cost
                            .partial_cmp(&g.rules.techs[*b].cost)
                            .unwrap()
                            .then(a.cmp(b))
                    })
                    .cloned()
            });
            let pick = goal_pick.or_else(|| {
                available
                    .iter()
                    .max_by(|a, b| {
                        self.tech_value(g, pid, a, plan.strategy)
                            .partial_cmp(&self.tech_value(g, pid, b, plan.strategy))
                            .unwrap()
                            .then_with(|| b.cmp(a))
                    })
                    .cloned()
            });
            if let Some(tech) = pick {
                if self.journal().wants(crate::reasoning::Level::Decision) {
                    let why = match (forced_goal, &goal_pick) {
                        (Some(goal), Some(_)) => {
                            format!("the cheapest step toward {}, which {} needs",
                                    plain(goal), objective.as_str())
                        }
                        _ => {
                            let runner_up = available
                                .iter()
                                .filter(|other| **other != tech)
                                .max_by(|a, b| {
                                    self.tech_value(g, pid, a, plan.strategy)
                                        .partial_cmp(&self.tech_value(g, pid, b, plan.strategy))
                                        .unwrap()
                                        .then_with(|| b.cmp(a))
                                })
                                .map(|other| {
                                    format!("ahead of {} at {:.0}", plain(other),
                                            self.tech_value(g, pid, other, plan.strategy))
                                })
                                .unwrap_or_else(|| "with nothing else on offer".to_string());
                            format!("worth {:.0} to the {} plan, {runner_up}",
                                    self.tech_value(g, pid, &tech, plan.strategy),
                                    plan.strategy.as_str())
                        }
                    };
                    think!(self.journal(), Research, Decision, "Researching {}", plain(&tech); "{why}");
                }
                let _ = g.apply(pid, &Action::Research { tech: Name::new(&tech) });
            }
        }
        if g.players[pid].civic.is_none() {
            let available = g.available_civics(pid);
            // A victory beeline cannot usefully precede the government's
            // policy capacity. Science formerly aimed at Space Race from turn
            // one, letting Games and Drama delay Political Philosophy while
            // the empire needed Colonization. Secure the first government,
            // then resume the victory lane.
            let first_government = self.wide_map_capacity
                && !g.players[pid]
                    .civics
                    .contains(&crate::name!("political_philosophy"));
            let great_person_goal =
                BasicAi::live_great_person_civic_goal(g, pid);
            let forced_goal = match objective {
                _ if g.has_ability(pid, "taxis")
                    && !g.players[pid].civics.contains(&crate::name!("divine_right")) =>
                {
                    Some("divine_right")
                }
                _ if great_person_goal.is_some() => great_person_goal.as_deref(),
                _ if first_government => Some("political_philosophy"),
                GrandStrategy::Culture => [
                    "humanism",
                    "conservation",
                    "professional_sports",
                    "cultural_heritage",
                    "space_race",
                    "environmentalism",
                    "social_media",
                ]
                .into_iter()
                .find(|civic| !g.players[pid].civics.contains(&Name::new(civic))),
                GrandStrategy::Science if !g.players[pid].civics.contains(&crate::name!("space_race")) => {
                    Some("space_race")
                }
                GrandStrategy::Diplomacy
                    if !g.players[pid].civics.contains(&crate::name!("global_warming_mitigation")) =>
                {
                    Some("global_warming_mitigation")
                }
                GrandStrategy::Religion if !g.players[pid].civics.contains(&crate::name!("theology")) => {
                    Some("theology")
                }
                _ => None,
            };
            let goal_pick = forced_goal.and_then(|goal| {
                available
                    .iter()
                    .filter(|civic| self.civic_leads_to(g, civic, goal))
                    .min_by(|a, b| {
                        g.rules.civics[*a]
                            .cost
                            .partial_cmp(&g.rules.civics[*b].cost)
                            .unwrap()
                            .then(a.cmp(b))
                    })
                    .cloned()
            });
            let pick = goal_pick.or_else(|| {
                available
                    .iter()
                    .max_by(|a, b| {
                        self.civic_value(g, pid, a, plan.strategy)
                            .partial_cmp(&self.civic_value(g, pid, b, plan.strategy))
                            .unwrap()
                            .then_with(|| b.cmp(a))
                    })
                    .cloned()
            });
            if let Some(civic) = pick {
                if self.journal().wants(crate::reasoning::Level::Decision) {
                    let why = match (forced_goal, &goal_pick) {
                        (Some(goal), Some(_)) => {
                            format!("the cheapest step toward {}, which {} needs",
                                    plain(goal), objective.as_str())
                        }
                        _ => {
                            let runner_up = available
                                .iter()
                                .filter(|other| **other != civic)
                                .max_by(|a, b| {
                                    self.civic_value(g, pid, a, plan.strategy)
                                        .partial_cmp(&self.civic_value(g, pid, b, plan.strategy))
                                        .unwrap()
                                        .then_with(|| b.cmp(a))
                                })
                                .map(|other| {
                                    format!("ahead of {} at {:.0}", plain(other),
                                            self.civic_value(g, pid, other, plan.strategy))
                                })
                                .unwrap_or_else(|| "with nothing else on offer".to_string());
                            format!("worth {:.0} to the {} plan, {runner_up}",
                                    self.civic_value(g, pid, &civic, plan.strategy),
                                    plan.strategy.as_str())
                        }
                    };
                    think!(self.journal(), Research, Decision, "Adopting the {} civic", plain(&civic);
                           "{why}");
                }
                let _ = g.apply(pid, &Action::Civic { civic: Name::new(&civic) });
            }
        }
    }

    fn tech_leads_to(&self, g: &Game, candidate: &str, target: &str) -> bool {
        candidate == target
            || g.rules
                .tech_ancestors
                .get(target)
                .is_some_and(|ancestors| ancestors.contains(candidate))
    }

    fn civic_leads_to(&self, g: &Game, candidate: &str, target: &str) -> bool {
        candidate == target
            || g.rules
                .civic_ancestors
                .get(target)
                .is_some_and(|ancestors| ancestors.contains(candidate))
    }

    fn advanced_secret_society(&self, g: &mut Game, pid: usize, strategy: GrandStrategy) {
        if !g.game_mode("secret_societies")
            || g.players[pid].secret_society.is_some()
            || !g.players[pid].civics.contains(&crate::name!("code_of_laws"))
        {
            return;
        }
        let long_term = self
            .victory_target
            .map(VictoryTarget::strategy)
            .unwrap_or(strategy);
        let society = match long_term {
            GrandStrategy::Science => "hermetic_order",
            GrandStrategy::Culture | GrandStrategy::Religion => "voidsingers",
            GrandStrategy::Diplomacy
            | GrandStrategy::Conquest
            | GrandStrategy::Expansion
            | GrandStrategy::Recovery => "owls_of_minerva",
        };
        let _ = g.apply(
            pid,
            &Action::ChooseSecretSociety {
                society: Name::new(society),
            },
        );
    }

    fn strategic_government(&self, g: &mut Game, pid: usize, strategy: GrandStrategy) {
        let objective = self
            .victory_target
            .map(VictoryTarget::strategy)
            .unwrap_or(strategy);
        let unlocked = |government: &str| {
            g.rules.governments.get(government).is_some_and(|spec| {
                spec.civic
                    .as_ref()
                    .is_none_or(|civic| g.players[pid].civics.contains(civic))
            })
        };

        // Matching the leading Culture defender removes the full -40%
        // Gathering Storm penalty between distinct Tier 3/4 governments.
        // Lower-tier governments have zero intolerance and do not justify
        // giving up the stronger late-game government effects.
        let culture_match = (objective == GrandStrategy::Culture)
            .then(|| {
                g.players
                    .iter()
                    .filter(|rival| {
                        rival.id != pid && rival.alive && !rival.is_minor && !rival.is_barbarian
                    })
                    .max_by_key(|rival| (g.domestic_tourists(rival.id), rival.id))
                    .and_then(|rival| rival.government.clone())
            })
            .flatten()
            .filter(|government| {
                matches!(
                    government.as_str(),
                    "communism"
                        | "democracy"
                        | "fascism"
                        | "corporate_libertarianism"
                        | "digital_democracy"
                        | "synthetic_technocracy"
                ) && unlocked(government)
            });

        let faith_mobilization =
            matches!(strategy, GrandStrategy::Conquest | GrandStrategy::Recovery)
                && g.players[pid].faith >= 600.0
                && unlocked("theocracy");
        let priorities: &[&str] = match objective {
            GrandStrategy::Culture | GrandStrategy::Diplomacy => &[
                "digital_democracy",
                "democracy",
                "merchant_republic",
                "monarchy",
                "theocracy",
                "classical_republic",
                "chiefdom",
            ],
            GrandStrategy::Science => &[
                "synthetic_technocracy",
                "communism",
                "democracy",
                "merchant_republic",
                "monarchy",
                "theocracy",
                "classical_republic",
                "chiefdom",
            ],
            GrandStrategy::Conquest if faith_mobilization => &[
                "theocracy",
                "corporate_libertarianism",
                "fascism",
                "communism",
                "monarchy",
                "merchant_republic",
                "oligarchy",
                "chiefdom",
            ],
            GrandStrategy::Conquest => &[
                "corporate_libertarianism",
                "fascism",
                "communism",
                "monarchy",
                "merchant_republic",
                "theocracy",
                "oligarchy",
                "chiefdom",
            ],
            GrandStrategy::Religion => &[
                "theocracy",
                "monarchy",
                "merchant_republic",
                "classical_republic",
                "chiefdom",
            ],
            GrandStrategy::Expansion => &[
                "corporate_libertarianism",
                "communism",
                "merchant_republic",
                "monarchy",
                "theocracy",
                "classical_republic",
                "chiefdom",
            ],
            GrandStrategy::Recovery if faith_mobilization => &[
                "theocracy",
                "digital_democracy",
                "democracy",
                "communism",
                "merchant_republic",
                "monarchy",
                "classical_republic",
                "chiefdom",
            ],
            GrandStrategy::Recovery => &[
                "digital_democracy",
                "democracy",
                "communism",
                "merchant_republic",
                "monarchy",
                "theocracy",
                "classical_republic",
                "chiefdom",
            ],
        };
        let choice = culture_match.or_else(|| {
            priorities
                .iter()
                .copied()
                .find(|government| unlocked(government))
                .map(str::to_string)
        });
        if let Some(government) = choice
            .filter(|government| g.players[pid].government.as_deref() != Some(government.as_str()))
        {
            // Returning to any previously used government costs two complete
            // turns of Anarchy. An adaptive plan can legitimately change its
            // mind as a victory race moves, but a lateral return between (for
            // example) Democracy and Fascism must not zero every empire yield
            // on alternating turns. Only pay that recurring cost for a real
            // policy-capacity upgrade; first-time governments remain free.
            let policy_capacity = |name: &str| {
                g.rules.governments.get(name).map_or(0, |spec| {
                    spec.slots.military
                        + spec.slots.economic
                        + spec.slots.diplomatic
                        + spec.slots.wildcard
                })
            };
            let returning = g.players[pid].past_governments.contains(&government);
            let current_capacity = g.players[pid]
                .government
                .as_deref()
                .map_or(0, policy_capacity);
            let choice_capacity = policy_capacity(&government);
            // A newly tried government is free, but dropping from a mature
            // eight-slot government to a six-slot faith or military stopgap
            // invites an expensive return as soon as the adaptive plan moves
            // again. Never give up policy capacity; among equal-capacity
            // governments a first adoption remains free, while a repeat is
            // still blocked by the Anarchy guard below.
            if choice_capacity < current_capacity
                || (returning && choice_capacity == current_capacity)
            {
                think!(self.journal(), Government, Detail,
                       "Staying under {}",
                       plain(g.players[pid].government.as_deref().unwrap_or("no government"));
                       "{} offers {choice_capacity} policy slots against the \
                        current {current_capacity}{}, and two turns of Anarchy is not \
                        worth paying for that",
                       plain(&government),
                       if returning { " and has been run before" } else { "" });
                return;
            }
            think!(self.journal(), Government, Decision, "Changing government to {}", plain(&government);
                   "{choice_capacity} policy slots against {current_capacity} now; \
                    the {} plan wants it",
                   objective.as_str());
            let _ = g.apply(pid, &Action::Government { government: Name::new(&government) });
        }
    }

    /// Whether replacing one active card with another can fit in the current
    /// typed and wildcard policy slots. This mirrors the engine's set-level
    /// seating rule before either action is applied: probing by actually
    /// unslotting a card writes a real action even when the candidate then
    /// fails and the old card is restored.
    fn policy_swap_fits(g: &Game, pid: usize, current: &Name, candidate: &str) -> bool {
        let slots = g.gov_slots(pid);
        let (mut military, mut economic, mut diplomatic, mut wildcard) =
            (0i64, 0i64, 0i64, 0i64);
        let mut count = |card: &str| match g.rules.policies[card].slot.as_str() {
            "military" => military += 1,
            "economic" => economic += 1,
            "diplomatic" => diplomatic += 1,
            _ => wildcard += 1,
        };
        for card in g.players[pid]
            .policies
            .iter()
            .filter(|card| *card != current)
        {
            count(card);
        }
        count(candidate);
        let overflow = (military - slots.military).max(0)
            + (economic - slots.economic).max(0)
            + (diplomatic - slots.diplomatic).max(0);
        overflow + wildcard <= slots.wildcard
    }

    /// Reassess policy cards as the civic tree advances instead of treating
    /// the first cards which filled a government as permanent.  Each plan has
    /// a complete late-game portfolio, while temporary Dark Age cards are
    /// admitted only when their explicit downside is safe for the live empire.
    /// Typed cards preferentially replace cards of their own type so wildcard
    /// capacity remains useful.
    fn strategic_policies(&self, g: &mut Game, pid: usize, strategy: GrandStrategy) {
        let objective = self
            .victory_target
            .map(VictoryTarget::strategy)
            .unwrap_or(strategy);

        // A successor card removes its predecessor from the policy menu.  An
        // already slotted predecessor used to survive forever, which is how
        // future governments reached the archive still running Ilkum and
        // Colonization.  Retire those cards before choosing the new portfolio.
        let obsolete: HashSet<Name> = g
            .rules
            .policies
            .values()
            .filter(|policy| {
                policy
                    .civic
                    .as_ref()
                    .is_none_or(|civic| g.players[pid].civics.contains(civic))
            })
            .flat_map(|policy| policy.replaces.iter().copied())
            .collect();
        let obsolete_active: Vec<Name> = g.players[pid]
            .policies
            .iter()
            .filter(|card| obsolete.contains(&Name::new(card.as_str())))
            .cloned()
            .collect();
        for card in obsolete_active {
            think!(self.journal(), Policies, Decision, "Retiring {}", plain(&card);
                   "a successor card has replaced it on the menu");
            let _ = g.apply(pid, &Action::UnslotPolicy { policy: card });
        }

        let mut desired: Vec<&str> = match objective {
            GrandStrategy::Science => vec![
                "integrated_space_cell",
                "future_victory_science",
                "five_year_plan",
                "rationalism",
                "nobel_prize",
                "international_space_agency",
                "ecommerce",
                "market_economy",
                "new_deal",
                "levee_en_masse",
                "military_research",
                "cryptography",
                "future_counter_science",
            ],
            GrandStrategy::Culture => vec![
                "future_victory_culture",
                "heritage_tourism",
                "satellite_broadcasts",
                "online_communities",
                "collective_activism",
                "sports_media",
                "grand_opera",
                "symphonies",
                "ecommerce",
                "new_deal",
                "gunboat_diplomacy",
                "cryptography",
                "communications_office",
                "levee_en_masse",
            ],
            GrandStrategy::Religion => vec![
                "religious_orders",
                "simultaneum",
                "scripture",
                "revelation",
                "wars_of_religion",
                "collectivization",
                "new_deal",
                "ecommerce",
                "levee_en_masse",
                "gunboat_diplomacy",
                "cryptography",
                "wisselbanken",
                "raj",
            ],
            GrandStrategy::Diplomacy => vec![
                "future_victory_diplomatic",
                "gunboat_diplomacy",
                "charismatic_leader",
                "raj",
                "merchant_confederation",
                "diplomatic_league",
                "containment",
                "collective_activism",
                "international_space_agency",
                "cryptography",
                "communications_office",
                "wisselbanken",
                "ecommerce",
                "new_deal",
                "levee_en_masse",
            ],
            GrandStrategy::Conquest => vec![
                "future_victory_domination",
                "future_counter_domination",
                "military_first",
                "strategic_air_force",
                "lightning_warfare",
                "total_war",
                "propaganda",
                "levee_en_masse",
                "force_modernization",
                "after_action_reports",
                "logistics",
                "five_year_plan",
                "ecommerce",
                "gunboat_diplomacy",
                "cryptography",
                "new_deal",
            ],
            GrandStrategy::Expansion => vec![
                "expropriation",
                "public_works",
                "five_year_plan",
                "economic_union",
                "collectivization",
                "ecommerce",
                "market_economy",
                "new_deal",
                "colonial_taxes",
                "colonial_offices",
                "gunboat_diplomacy",
                "levee_en_masse",
                "logistics",
                "rationalism",
                "cryptography",
            ],
            GrandStrategy::Recovery => vec![
                "new_deal",
                "liberalism",
                "civil_prestige",
                "collectivization",
                "five_year_plan",
                "ecommerce",
                "market_economy",
                "wisselbanken",
                "raj",
                "gunboat_diplomacy",
                "cryptography",
                "communications_office",
                "levee_en_masse",
                "logistics",
                "public_works",
            ],
        };

        // ⚠ FRONT of the list, not appended: these portfolios are preference
        // ordered and the military slot is contested from the ancient era, which is
        // exactly when loyalty pressure starts. Appending would put `limitanei`
        // behind sixteen late-game cards and it would never be reached — which is
        // indistinguishable from today's behaviour and would make the arm measure
        // nothing.
        if self.garrison_loyalty_policy
            && matches!(objective, GrandStrategy::Conquest | GrandStrategy::Expansion)
        {
            desired.insert(0, "limitanei");
        }
        if g.has_ability(pid, "taxis") && objective == GrandStrategy::Conquest {
            desired.splice(0..0, ["chivalry", "maneuver", "raid", "conscription"]);
        }

        let city_ids = g.player_city_ids(pid);
        let unit_ids = g.player_unit_ids(pid);
        let settlers = unit_ids
            .iter()
            .filter(|unit| g.units[unit].kind == "settler")
            .count();
        let city_goal = self
            .plan
            .as_ref()
            .map(|plan| plan.desired_cities)
            .unwrap_or_else(|| self.base.w.city_target.ceil().max(1.0) as usize);
        let expansion_complete = strategy != GrandStrategy::Expansion
            && settlers == 0
            && !city_ids.is_empty()
            && city_ids.len() >= city_goal;
        // Time live economic slots to what their cities are producing. Static
        // victory portfolios begin with late cards, so Science used to replace
        // Colonization and Ilkum while actively building their units. Policy
        // selection also precedes production, which makes the city-plan gap
        // the signal for pre-slotting Colonization this turn.
        if self.wide_map_capacity {
            let settler_queued = city_ids.iter().any(|city| {
                matches!(
                    g.cities[city].queue.first(),
                    Some(Item::Unit { unit }) if unit == "settler"
                )
            });
            let builder_queued = city_ids.iter().any(|city| {
                matches!(
                    g.cities[city].queue.first(),
                    Some(Item::Unit { unit }) if unit == "builder"
                )
            });
            let expansion_active = settler_queued || city_ids.len() + settlers < city_goal;
            if expansion_active || builder_queued {
                const TIMED_ECONOMY: [&str; 6] = [
                    "expropriation",
                    "colonization",
                    "public_works",
                    "serfdom",
                    "ilkum",
                    "urban_planning",
                ];
                desired.retain(|card| !TIMED_ECONOMY.contains(card));
                let mut timed = Vec::new();
                if expansion_active {
                    timed.extend(["expropriation", "colonization"]);
                }
                if builder_queued {
                    timed.extend(["public_works", "serfdom", "ilkum"]);
                }
                let committed_slots = usize::from(expansion_active) + usize::from(builder_queued);
                if g.gov_slots(pid).economic.max(0) as usize > committed_slots {
                    timed.push("urban_planning");
                }
                timed.extend(desired);
                desired = timed;
            }
        }
        let at_war = g
            .at_war
            .iter()
            .any(|(first, second)| *first == pid || *second == pid);
        let military = unit_ids
            .iter()
            .filter(|unit| g.rules.units[g.units[unit].kind].class == "military")
            .count();
        let at_major_war = g.players.iter().any(|player| {
            player.id != pid
                && player.alive
                && !player.is_minor
                && !player.is_barbarian
                && g.is_at_war(pid, player.id)
        });
        // A zero treasury turns a negative cash flow into an immediate
        // empire-wide Amenity penalty before recovery production can finish a
        // Commercial Hub. The live war governor already knows it must keep
        // the defending force, so use the current maintenance discount before
        // asking that force to carry another turn of bankruptcy.
        //
        // This must also happen while a confirmed Conquest campaign is still
        // staging. On the live Rome board, the counter-leader plan held 85
        // Gold at -59 per turn before it declared: waiting for the declaration
        // (or for Gold to reach exactly zero) let the maintenance bill consume
        // its entire emergency reserve first. The same `100 + 25/city`
        // runway that diverts production into recovery is the relevant bound
        // here. An ordinary peaceful deficit still keeps its normal policy
        // portfolio; only a major war or a named Conquest target may trade a
        // military card for solvency.
        //
        // `levee_en_masse` is deliberately listed first: its civic retires
        // `conscription`, so the loop below takes the strongest available
        // version without a second card-selection path.
        let recovery_reserve = 100.0 + 25.0 * city_ids.len() as f64;
        let staged_conquest = objective == GrandStrategy::Conquest
            && self
                .plan
                .as_ref()
                .is_some_and(|plan| {
                    plan.target_player.is_some_and(|target| {
                        g.players.get(target).is_some_and(|player| {
                            player.alive && !player.is_minor && !player.is_barbarian
                        })
                    })
                });
        let maintenance_emergency = self.war_economy
            && (at_major_war || staged_conquest)
            && military > 0
            && g.players[pid].gold < recovery_reserve
            && g.players[pid].gold_per_turn < -0.5;
        if maintenance_emergency {
            desired.retain(|card| !matches!(*card, "conscription" | "levee_en_masse"));
            desired.splice(0..0, ["levee_en_masse", "conscription"]);
        }
        if self.victory_planning
            && objective == GrandStrategy::Conquest
            && military >= city_ids.len().max(1).saturating_mul(2)
        {
            // Military and economic cards mostly use different typed slots. Once the
            // field army has reached the same two-per-city ceiling as production,
            // promote the science/culture multipliers which keep that army current.
            // This preserves the conquest plan and all of its tactical behavior; it
            // only prevents a winning war from freezing the civic economy forever.
            const WARTIME_ECONOMY: [&str; 5] = [
                "rationalism",
                "grand_opera",
                "five_year_plan",
                "aesthetics",
                "natural_philosophy",
            ];
            desired.retain(|card| !WARTIME_ECONOMY.contains(card));
            desired.splice(0..0, WARTIME_ECONOMY);
        }
        // The deck has the same lane-keyed shape as every other science term.
        // Counted over the six lists above, the Campus multipliers appear in
        // exactly two: Science and Expansion. **The Religion and Culture decks
        // contain no science card at all** — and the deployment genome is
        // `adv-religious`, so in the live game Rationalism and Natural
        // Philosophy are unreachable unless a Conquest army happens to saturate
        // and trigger `WARTIME_ECONOMY` above. That is exactly what the two
        // recorded runs show: the religion-heavy `civvis-20260803T005930Z`
        // finished with all three science cards *available and unslotted*,
        // while `civvis-20260802T220818Z` had Rationalism and Natural
        // Philosophy in and reached 60.9 science against the other's 12.3.
        //
        // Both cards multiply Campus buildings, so the empire must own a Campus
        // for them to mean anything — that gate is the whole precondition, and
        // it is why this cannot fire in a seat these cards would be wasted in.
        // Inserted after the lane's own leading cards rather than in front of
        // them: a Religion empire keeps its opening, and picks these up with a
        // slot it would otherwise fill from the tail of its list.
        if self.research_economy {
            const RESEARCH_MULTIPLIERS: [&str; 2] = ["rationalism", "natural_philosophy"];
            let has_campus = city_ids.iter().any(|city| {
                g.city_has_district_family(&g.cities[city], crate::name!("campus"))
            });
            if has_campus {
                desired.retain(|card| !RESEARCH_MULTIPLIERS.contains(card));
                let at = desired.len().min(RESEARCH_DECK_INSERT);
                desired.splice(at..at, RESEARCH_MULTIPLIERS);
            }
        }
        // The same shape for the growth band the empire actually pays. A card
        // that multiplies something we do not have is worth zero, so this is
        // gated on a city that is BOTH short of housing and already carrying
        // enough specialty districts for the card to fire — never on the mere
        // existence of the card. See `HOUSING_DECK_INSERT` for the corpus.
        //
        // Medina Quarter before Insulae: +2 against +1, and a city with three
        // specialty districts has two, so the stronger card is never blocked by
        // the weaker one taking the slot first.
        if self.housing_cards {
            const HOUSING_CARDS: [&str; 2] = ["medina_quarter", "insulae"];
            let pays = city_ids.iter().any(|cid| {
                let city = &g.cities[cid];
                g.city_housing_headroom(city) < HOUSING_CARD_HEADROOM
                    && g.city_specialty_district_count(city) >= 2
            });
            if pays {
                desired.retain(|card| !HOUSING_CARDS.contains(card));
                let at = desired.len().min(HOUSING_DECK_INSERT);
                desired.splice(at..at, HOUSING_CARDS);
            }
        }
        // ⚠⚠ A CARD THAT MULTIPLIES SOMETHING WE DO NOT HAVE IS WORTH ZERO, and
        // the deck lists above are static, so nothing noticed. Every one of these
        // scales off SUZERAIN city-states:
        //
        //   raj                         suzerain_all_yields          2
        //   wisselbanken                allied_suzerain_trade_*      2
        //   collective_activism         culture_pct_per_suzerain     5
        //   international_space_agency  science_pct_per_suzerain     5
        //
        // At zero suzerainties each pays exactly nothing, and they sit in the
        // Religion, Diplomacy and Recovery lists unconditionally. Live run
        // `civvis-20260803T191900Z` finished holding **0 suzerainties with 56
        // unspent envoys** and had slotted BOTH `raj` and `wisselbanken` — two of
        // six slots returning zero for the whole game.
        //
        // Demoted, not dropped: they are the right cards the moment a suzerainty
        // exists, and the empire that takes one mid-game should pick them up
        // without a second mechanism. Sending them to the tail lets the slot go
        // to a card that pays now, and self-corrects when the board changes.
        //
        // Same shape as the Campus gate directly above — "the empire must own a
        // Campus for them to mean anything" — applied to the other precondition
        // the deck ignores.
        const SUZERAIN_CONDITIONAL: [&str; 4] = [
            "raj",
            "wisselbanken",
            "collective_activism",
            "international_space_agency",
        ];
        let suzerainties = g
            .players
            .iter()
            .filter(|p| p.is_minor && p.alive)
            .map(|p| p.id)
            .filter(|minor| g.suzerain_of(*minor) == Some(pid))
            .count();
        if self.suzerain_cards_need_a_suzerainty && suzerainties == 0 {
            desired.retain(|card| !SUZERAIN_CONDITIONAL.contains(card));
            desired.extend(SUZERAIN_CONDITIONAL);
        }

        // A host-observed Amenity deficit is an immediate yield loss, but a
        // repair district needs several turns before it changes that fact. If
        // Liberalism can help at least two already-developed cities, use the
        // one card that repairs both now. `desired_set` below intentionally
        // protects every ordinary desired card from replacement, so merely
        // inserting Liberalism would leave a currently slotted Aesthetics
        // untouched. Demote that narrow, same-slot culture-adjacency donor
        // explicitly; Grand Opera and expansion's Expropriation stay wanted.
        //
        // This shares the live-only crisis arm with the concrete repair chain:
        // normal and frozen controller decks return before reading city
        // Amenities at all.
        if self.amenity_project_preemption
            && city_ids
                .iter()
                .filter(|cid| {
                    let city = &g.cities[cid];
                    g.city_specialty_district_count(city) >= 2
                        && g.city_amenity_surplus(city) < 0
                })
                .count()
                >= 2
        {
            desired.retain(|card| !matches!(*card, "aesthetics" | "liberalism"));
            desired.insert(0, "liberalism");
        }

        let elite_active = g.players[pid].policies.contains(&crate::name!("elite_forces"));
        let elite_affordable = if elite_active {
            g.players[pid].gold_per_turn >= 5.0
        } else {
            g.players[pid].gold_per_turn >= military as f64 * 2.0 + 5.0
        };
        let robber_active = g.players[pid].policies.contains(&crate::name!("robber_barons"));
        let robber_pays = city_ids.iter().any(|city| {
            let city = &g.cities[city];
            city.buildings.iter().any(|building| {
                matches!(building.as_str(), "stock_exchange" | "factory")
                    && !city.pillaged_buildings.contains(building)
            })
        });
        let robber_safe = robber_pays
            && city_ids.iter().all(|city| {
                g.city_amenity_surplus(&g.cities[city]) >= if robber_active { 0 } else { 2 }
            });
        let holy_site_cities = city_ids
            .iter()
            .filter(|city| g.city_has_district_family(&g.cities[city], crate::name!("holy_site")))
            .count();

        let mut temporary = Vec::new();
        match objective {
            GrandStrategy::Science if holy_site_cities * 2 >= city_ids.len().max(1) => {
                temporary.push("monasticism");
            }
            GrandStrategy::Religion if g.players[pid].religion.is_some() => {
                temporary.push("inquisition");
            }
            GrandStrategy::Conquest if at_war => {
                temporary.push("twilight_valor");
                if elite_affordable {
                    temporary.push("elite_forces");
                }
            }
            _ => {}
        }
        if expansion_complete
            && matches!(
                objective,
                GrandStrategy::Science
                    | GrandStrategy::Culture
                    | GrandStrategy::Diplomacy
                    | GrandStrategy::Recovery
            )
        {
            temporary.push("isolationism");
        }
        if robber_safe
            && matches!(
                objective,
                GrandStrategy::Science
                    | GrandStrategy::Culture
                    | GrandStrategy::Expansion
                    | GrandStrategy::Recovery
            )
        {
            temporary.push("robber_barons");
        }
        // ★★★★★ CITIES BLEEDING LOYALTY HAVE ONE LEVER AND FIVE UNUSED ONES.
        //
        // `loyalty_emergency` reads the RATE (that is what #981 fixed) but its only
        // consumer is `reassign_governor_for_loyalty`, so moving a governor is the
        // entire response and it is capped by how many governors exist.
        //
        // Measured over 117 city losses in 91 runs: **47 were revolts**, and they died
        // at loyalty 0.1-1.9 carrying -13 to -22 a turn. The warning is long and
        // nothing spends it:
        //
        // ```text
        //   turns loyalty_per_turn was NEGATIVE before the loss   median 13, max 39
        //   turns from loyalty crossing 50 to the loss            median  8
        // ```
        //
        // Five policy cards carry loyalty effects and every one is already honoured by
        // `Game::city_loyalty_per_turn`. **Across those 91 runs only COLONIAL_OFFICES
        // was ever slotted, in 5 of them; the other four never once** — including
        // `limitanei`, which needs only `early_empire`, an ancient civic reached in
        // essentially every game, and sits in a MILITARY slot nothing competes for.
        //
        // ★ This is also what makes a garrison worth anything. Garrisoning has measured
        // null as a military mechanism (~2pp, parity), but with Limitanei slotted the
        // same unit is +2 loyalty a turn in the city it stands in — the same action
        // priced on the axis that actually loses us cities.
        //
        // Ranked ahead of the plan's ordinary cards because a revolt is unrecoverable
        // and a yield card is not.
        let bleeding = if !self.loyalty_policy_defence {
            0
        } else {
            g.player_city_ids(pid)
                .into_iter()
                .filter(|cid| {
                    g.cities
                        .get(cid)
                        .is_some_and(|city| g.city_loyalty_per_turn(city) < 0.0)
                })
                .count()
        };
        if bleeding > 0 {
            let mut loyalty_cards = vec![
                "limitanei",
                "praetorium",
                "colonial_offices",
                "communications_office",
                "martial_law",
            ];
            loyalty_cards.extend(temporary);
            temporary = loyalty_cards;
        }

        temporary.extend(desired);
        desired = temporary;
        desired.retain(|card| {
            g.rules.policies[*card].offered(&g.players[pid].age, g.world_era)
        });

        // If circumstances changed, remove a downside-bearing Dark Age card
        // immediately.  Most importantly, Isolationism can never coexist with
        // a live settler or an Expansion plan.
        let desired_set: HashSet<&str> = desired.iter().copied().collect();
        let unsafe_dark_cards: Vec<Name> = g.players[pid]
            .policies
            .iter()
            .filter(|card| {
                g.rules.policies[card].dark_age
                    && !desired_set.contains(card.as_str())
            })
            .cloned()
            .collect();
        for card in unsafe_dark_cards {
            think!(self.journal(), Policies, Decision, "Dropping the Dark Age card {}", plain(&card);
                   "its downside no longer suits the {} plan", objective.as_str());
            let _ = g.apply(pid, &Action::UnslotPolicy { policy: card });
        }

        // The portfolio itself is a decision, and the order is the whole of
        // the reasoning behind every slot below: an observer who can see the
        // ranking can tell a card that was skipped from one that never made
        // the list.
        if self.journal().wants(crate::reasoning::Level::Detail) {
            let held: Vec<&str> = desired
                .iter()
                .copied()
                .filter(|card| g.players[pid].policies.contains(&Name::new(card)))
                .collect();
            think!(self.journal(), Policies, Detail,
                   "Policy portfolio for the {} plan", objective.as_str();
                   "wants, in order: {}; already slotted: {}",
                   desired.iter().map(|card| plain(card)).collect::<Vec<_>>().join(", "),
                   if held.is_empty() {
                       "none".to_string()
                   } else {
                       held.iter().map(|card| plain(card)).collect::<Vec<_>>().join(", ")
                   });
        }

        let wanted = desired.len();
        let available: HashSet<Name> = g.available_policies(pid).into_iter().collect();
        for (rank, card) in desired.iter().copied().enumerate() {
            if g.players[pid].policies.contains(&Name::new(card))
                || !available.contains(&Name::new(card))
            {
                continue;
            }
            if g.apply(
                pid,
                &Action::SlotPolicy {
                    policy: Name::new(card),
                },
            )
            .is_ok()
            {
                think!(self.journal(), Policies, Decision, "Slotted {}", plain(card);
                       "priority {} of {wanted} for the {} plan, into a free slot",
                       rank + 1, objective.as_str());
                continue;
            }

            let slot = g.rules.policies[card].slot.clone();
            let mut replaceable: Vec<Name> = g.players[pid]
                .policies
                .iter()
                .filter(|current| !desired_set.contains(current.as_str()))
                .filter(|current| Self::policy_swap_fits(g, pid, current, card))
                .cloned()
                .collect();
            replaceable.sort_by(|first, second| {
                let key = |current: &str| {
                    let policy = &g.rules.policies[current];
                    let era = policy
                        .civic
                        .as_ref()
                        .and_then(|civic| g.rules.civics.get(civic))
                        .map_or(0, |civic| civic.era);
                    (usize::from(policy.slot != slot), era)
                };
                key(first).cmp(&key(second)).then(first.cmp(second))
            });
            for current in replaceable {
                let _ = g.apply(
                    pid,
                    &Action::UnslotPolicy {
                        policy: current,
                    },
                );
                if g.apply(
                    pid,
                    &Action::SlotPolicy {
                        policy: Name::new(card),
                    },
                )
                .is_ok()
                {
                    think!(self.journal(), Policies, Decision,
                           "Slotted {} over {}", plain(card), plain(&current);
                           "priority {} of {wanted} for the {} plan; {} was the oldest \
                            card the plan does not want",
                           rank + 1, objective.as_str(), plain(&current));
                    break;
                }
                // A type mismatch can make one particular swap invalid. Put
                // the old card back before trying another candidate so policy
                // reassessment can never silently empty a government.
                let _ = g.apply(pid, &Action::SlotPolicy { policy: current });
            }
        }
    }

    fn tech_value(&self, g: &Game, pid: usize, tech: &str, strategy: GrandStrategy) -> f64 {
        let spec = &g.rules.techs[tech];
        let mut value = if g.players[pid].boosted_techs.contains(&Name::new(tech)) {
            28.0
        } else {
            0.0
        };
        for (name, unit) in &g.rules.units {
            if unit.tech.as_deref() == Some(tech)
                && unit
                    .unique_to
                    .as_ref()
                    .is_none_or(|c| c == &g.players[pid].civ)
            {
                let power = unit.strength.max(unit.ranged_attack_strength());
                value += if strategy == GrandStrategy::Conquest {
                    power * 3.2
                } else {
                    power * 1.1
                };
                if !self.civ_blind
                    && g.rules.civs[&g.players[pid].civ].unique_unit.as_deref() == Some(name)
                {
                    value += 55.0;
                }
            }
        }
        // A node that unlocks the successor of units already on the map buys
        // an upgrade for every one of them, not merely the option to train
        // something new. Counted over a whole game, the commonest reason an
        // upgrade was unavailable was a node its owner had simply never taken
        // — Archery, Iron Working, Machinery — while empires holding ten to
        // thirty technologies still fielded the Slingers and Warriors those
        // nodes would have retired.
        let stranded: f64 = g
            .units
            .values()
            .filter(|unit| unit.owner == pid)
            .filter_map(|unit| {
                let held = &g.rules.units[unit.kind];
                let successor = g.rules.units.get(held.upgrade_to.as_deref()?)?;
                (successor.tech.as_deref() == Some(tech)).then(|| {
                    (successor.strength.max(successor.ranged_attack_strength())
                        - held.strength.max(held.ranged_attack_strength()))
                    .max(0.0)
                })
            })
            .sum();
        // Capped so a large stale army nudges the order rather than dictating
        // it: at the ceiling this is worth about as much as an embarkation
        // prerequisite, which is the largest bonus already in this function.
        value += (stranded
            * if strategy == GrandStrategy::Conquest {
                2.4
            } else {
                1.4
            })
        .min(150.0);
        for building in g
            .rules
            .buildings
            .values()
            .filter(|b| b.tech.as_deref() == Some(tech))
        {
            value += self.yield_value(building.yields, strategy) * 14.0
                + building.housing * 12.0
                + building.amenity * 18.0;
        }
        for district in g
            .rules
            .districts
            .values()
            .filter(|d| d.tech.as_deref() == Some(tech))
        {
            value += self.yield_value(district.yields, strategy) * 18.0
                + district.defense * 1.5
                + district.amenity * 18.0;
        }
        for project in g
            .rules
            .projects
            .values()
            .filter(|p| p.tech.as_deref() == Some(tech))
        {
            value += if strategy == GrandStrategy::Science {
                if project.repeatable {
                    120.0
                } else {
                    260.0
                }
            } else if project.repeatable {
                25.0
            } else {
                65.0
            };
        }
        for improvement in g
            .rules
            .improvements
            .values()
            .filter(|i| i.tech.as_deref() == Some(tech))
        {
            value += self.yield_value(improvement.yields, strategy) * 10.0 + 18.0;
        }
        if strategy == GrandStrategy::Religion && tech == "astrology" {
            value += 95.0;
        }
        if let Some(goal) = BasicAi::water_research_goal(g, pid) {
            if self.tech_leads_to(g, tech, goal) {
                // Embarkation and ocean access change which parts of the map
                // are strategically reachable, so their prerequisites must
                // compete with ordinary yield unlocks rather than wait for a
                // naval unit to happen to win a generic score comparison.
                value += match goal {
                    "sailing" => 190.0,
                    "shipbuilding" => 230.0,
                    "celestial_navigation" => 150.0,
                    "cartography" => 210.0,
                    "square_rigging" | "steam_power" | "refining" | "electricity"
                    | "combined_arms" | "lasers" | "telecommunications" => 185.0,
                    _ => 0.0,
                };
            }
        }
        if strategy == GrandStrategy::Science {
            let milestone = if !g.players[pid]
                .science_projects
                .contains("launch_earth_satellite")
            {
                "rocketry"
            } else if !g.players[pid]
                .science_projects
                .contains("launch_moon_landing")
            {
                "satellites"
            } else if !g.players[pid]
                .science_projects
                .contains("launch_mars_colony")
            {
                "nanotechnology"
            } else if !g.players[pid]
                .science_projects
                .contains("exoplanet_expedition")
            {
                "smart_materials"
            } else {
                "offworld_mission"
            };
            if self.tech_leads_to(g, tech, milestone) {
                value += if self.victory_target == Some(VictoryTarget::Science) {
                    900.0
                } else {
                    260.0
                };
            }
        }
        // The nuclear lane used to carry a terminal reward and no
        // instrumental one: a Conquest empire prices a finished device at
        // 2,600 but the technology that permits one at barely two points, so
        // no empire ever researched its way to the doctrine it already had.
        // Price the path like the other victory beelines, from the industrial
        // era on so the ancient rush book keeps its own ordering. Gated on
        // victory_planning like the strike doctrine itself, which keeps the
        // frozen advanced_v1 anchor's research untouched.
        if self.victory_planning && strategy == GrandStrategy::Conquest && g.world_era >= 4 {
            let arsenal = &g.players[pid].science_projects;
            let milestone = if !arsenal.contains("manhattan_project") {
                Some("nuclear_fission")
            } else if !arsenal.contains("operation_ivy") {
                Some("nuclear_fusion")
            } else {
                // Both gates are open: the lane is production now, not
                // research.
                None
            };
            if milestone.is_some_and(|milestone| self.tech_leads_to(g, tech, milestone)) {
                value += if self.victory_target == Some(VictoryTarget::Domination) {
                    900.0
                } else {
                    260.0
                };
            }
        }
        // One-step lookahead prevents cheap prerequisites from being ignored.
        for (future, child) in &g.rules.techs {
            if child.requires.iter().any(|r| r == tech) {
                let unlocks = g
                    .rules
                    .units
                    .values()
                    .filter(|u| u.tech.as_deref() == Some(future))
                    .count()
                    + g.rules
                        .buildings
                        .values()
                        .filter(|b| b.tech.as_deref() == Some(future))
                        .count()
                    + g.rules
                        .districts
                        .values()
                        .filter(|d| d.tech.as_deref() == Some(future))
                        .count()
                    + g.rules
                        .projects
                        .values()
                        .filter(|p| p.tech.as_deref() == Some(future))
                        .count();
                value += unlocks as f64 * 8.0;
            }
        }
        // Discount by opportunity cost so a flashy late-era unlock does not
        // stall several cheaper advances. Square root still lets a genuinely
        // transformative breakthrough win the comparison.
        (value + 35.0) / spec.cost.max(10.0).sqrt()
    }

    fn civic_value(&self, g: &Game, pid: usize, civic: &str, strategy: GrandStrategy) -> f64 {
        let spec = &g.rules.civics[civic];
        let mut value = if g.players[pid].boosted_civics.contains(&Name::new(civic)) {
            28.0
        } else {
            0.0
        };
        for building in g
            .rules
            .buildings
            .values()
            .filter(|b| b.civic.as_deref() == Some(civic))
        {
            value += self.yield_value(building.yields, strategy) * 15.0
                + building.housing * 12.0
                + building.amenity * 18.0;
        }
        for district in g
            .rules
            .districts
            .values()
            .filter(|d| d.civic.as_deref() == Some(civic))
        {
            value += self.yield_value(district.yields, strategy) * 18.0 + district.amenity * 18.0;
        }
        value += g
            .rules
            .governments
            .values()
            .filter(|gov| gov.civic.as_deref() == Some(civic))
            .map(|gov| {
                let slots = gov.slots.military
                    + gov.slots.economic
                    + gov.slots.diplomatic
                    + gov.slots.wildcard;
                45.0 + slots as f64 * 18.0
            })
            .sum::<f64>();
        value += g
            .rules
            .policies
            .values()
            .filter(|p| p.civic.as_deref() == Some(civic))
            .count() as f64
            * 13.0;
        if strategy == GrandStrategy::Expansion && matches!(civic, "early_empire" | "foreign_trade")
        {
            value += 45.0;
        }
        if strategy == GrandStrategy::Culture && civic == "drama_poetry" {
            value += 60.0;
        }
        if strategy == GrandStrategy::Diplomacy
            && matches!(civic, "political_philosophy" | "civil_service" | "guilds")
        {
            value += 60.0;
        }
        if strategy == GrandStrategy::Religion && civic == "theology" {
            value += 120.0;
        }
        value += match civic {
            "foreign_trade" | "craftsmanship" => 25.0,
            "early_empire" | "state_workforce" => 38.0,
            "political_philosophy" => 70.0,
            // Culture infrastructure is a prerequisite for every strategy,
            // not only a culture-victory plan.
            "drama_poetry" => 55.0,
            _ => 0.0,
        };
        (value + 32.0) / spec.cost.max(10.0).sqrt()
    }

    fn incoming_deal_value(
        &self,
        g: &Game,
        pid: usize,
        deal: &DiplomaticDeal,
        plan: &StrategicPlan,
    ) -> f64 {
        let partner = deal.from;
        let my_power = g.military_power(pid);
        let partner_power = g.military_power(partner);
        let grievance = g.players[pid]
            .grievances
            .get(&partner)
            .copied()
            .unwrap_or(0.0);
        // `war_patience`: the stall clause stands down while the empire
        // overwhelmingly outweighs its own campaign target, so a slow wall
        // does not sue a walkover out. The 0.85 outmatched clause below is
        // deliberately untouched — if the advantage is ever lost, so is the
        // patience.
        let overwhelming = self.war_patience
            && plan.strategy == GrandStrategy::Conquest
            && plan.target_player == Some(partner)
            && my_power >= partner_power * OVERWHELMING_WAR_RATIO
            && !self.war_patience_exhausted(g);
        let fatigued = !overwhelming
            && self.major_war_since.is_some_and(|started| {
                g.turn.saturating_sub(started) >= 24
                    && g.turn.saturating_sub(self.last_campaign_progress) >= 12
            });
        let denied_partner = plan.target_player == Some(partner)
            && (plan.strategy == GrandStrategy::Conquest
                || g.is_at_war(pid, partner)
                || self.rival_victory_pressure(g, partner).progress >= 78);

        let mut value = deal.give_gold - deal.request_gold;
        if deal.peace {
            value += if my_power < partner_power * 0.85 || fatigued {
                320.0
            } else if denied_partner {
                // Recovery is a temporary battlefield posture, not an order
                // to abandon the campaign. A locally threatened city can put
                // an overwhelmingly stronger attacker into Recovery for one
                // assessment window; keep refusing its active target's white
                // peace until the army is actually outmatched or fatigued.
                -260.0
            } else if plan.strategy == GrandStrategy::Recovery {
                320.0
            } else {
                35.0
            };
        } else if denied_partner {
            return -1_000.0;
        }
        if deal.open_borders {
            value += match plan.strategy {
                GrandStrategy::Culture => 70.0,
                GrandStrategy::Conquest => 45.0,
                _ => 25.0,
            };
        }
        if deal.friendship {
            value += if plan.strategy == GrandStrategy::Diplomacy {
                80.0
            } else {
                40.0
            };
        }
        if let Some(alliance) = deal.alliance.as_deref() {
            value += match (plan.strategy, alliance) {
                (GrandStrategy::Science, "research")
                | (GrandStrategy::Culture, "cultural")
                | (GrandStrategy::Religion, "religious")
                | (GrandStrategy::Conquest | GrandStrategy::Recovery, "military")
                | (GrandStrategy::Expansion | GrandStrategy::Diplomacy, "economic") => 150.0,
                (GrandStrategy::Diplomacy, _) => 110.0,
                _ => 55.0,
            };
        }
        if deal.defensive_pact {
            // The engine only offers a pact to an existing Ally. Its value is
            // protection against a surprise declaration, but it is never
            // worth protecting the campaign target (handled above).
            value += if partner_power > my_power * 0.8 { 95.0 } else { 55.0 };
        }
        if let Some(target) = deal.joint_war_target {
            let strategic_target = plan.target_player == Some(target)
                || self.rival_victory_pressure(g, target).progress >= 78;
            value += if strategic_target {
                300.0
            } else {
                // A Joint War is a 30-turn commitment, not a free diplomatic
                // favour. Do not accept a human/AI proposal that pulls this
                // plan off its own objective.
                -300.0
            };
        }
        if let Some(promise) = deal.promise.as_deref() {
            let conflicts_with_plan = matches!(
                (plan.strategy, promise),
                (GrandStrategy::Expansion, "no_settling")
                    | (GrandStrategy::Religion, "no_conversion")
                    | (GrandStrategy::Conquest | GrandStrategy::Recovery, "no_city_state_attack")
            );
            value += if conflicts_with_plan { -130.0 } else { 20.0 };
        }
        value - grievance * 0.8
    }

    fn strategic_bilateral_trade(
        &self,
        g: &mut Game,
        pid: usize,
        excluded_partner: Option<usize>,
        strategy: GrandStrategy,
    ) {
        let objective = self
            .victory_target
            .map(VictoryTarget::strategy)
            .unwrap_or(strategy);
        if objective == GrandStrategy::Culture && g.turn % 6 == pid as u32 % 6 {
            let best = g
                .quick_deals(pid)
                .into_iter()
                .filter(|deal| Some(deal.partner) != excluded_partner)
                .filter(|deal| {
                    deal.item == "open_borders"
                        && deal.direction == "buy"
                        && deal.my_value >= 2.0
                        && deal.partner_value >= 2.0
                })
                .max_by(|left, right| {
                    g.domestic_tourists(left.partner)
                        .cmp(&g.domestic_tourists(right.partner))
                        .then_with(|| {
                            left.my_value
                                .min(left.partner_value)
                                .partial_cmp(&right.my_value.min(right.partner_value))
                                .unwrap()
                        })
                        .then_with(|| right.partner.cmp(&left.partner))
                });
            if let Some(deal) = best {
                if g.apply(
                    pid,
                    &Action::Trade {
                        player: deal.partner,
                        offer: Box::new(deal.offer),
                        request: Box::new(deal.request),
                    },
                )
                .is_ok()
                {
                    return;
                }
            }

            let best = g
                .quick_deals(pid)
                .into_iter()
                .filter(|deal| Some(deal.partner) != excluded_partner)
                .filter(|deal| {
                    deal.category == "great_work"
                        && deal.direction == "buy"
                        && deal.my_value >= 2.0
                        && deal.partner_value >= 2.0
                })
                .max_by(|left, right| {
                    left.my_value
                        .min(left.partner_value)
                        .partial_cmp(&right.my_value.min(right.partner_value))
                        .unwrap()
                        .then_with(|| right.partner.cmp(&left.partner))
                        .then_with(|| right.item.cmp(&left.item))
                });
            if let Some(deal) = best {
                if g.apply(
                    pid,
                    &Action::Trade {
                        player: deal.partner,
                        offer: Box::new(deal.offer),
                        request: Box::new(deal.request),
                    },
                )
                .is_ok()
                {
                    return;
                }
            }

            // A Culture objective preserves its own Great Works. If neither
            // the strategically useful Open Borders direction nor a housed
            // purchase is available, it may still take the best ordinary
            // mutually beneficial quote.
            let best = g
                .quick_deals(pid)
                .into_iter()
                .filter(|deal| Some(deal.partner) != excluded_partner)
                .filter(|deal| {
                    !(deal.category == "great_work" && deal.direction == "sell")
                        && deal.my_value >= 2.0
                        && deal.partner_value >= 2.0
                })
                .max_by(|left, right| {
                    left.my_value
                        .min(left.partner_value)
                        .partial_cmp(&right.my_value.min(right.partner_value))
                        .unwrap()
                });
            if let Some(deal) = best {
                let _ = g.apply(
                    pid,
                    &Action::Trade {
                        player: deal.partner,
                        offer: Box::new(deal.offer),
                        request: Box::new(deal.request),
                    },
                );
            }
            return;
        }
        self.base
            .bilateral_trade_excluding(g, pid, excluded_partner);
    }

    fn propose_strategic_alliance(
        &self,
        g: &mut Game,
        pid: usize,
        plan: &StrategicPlan,
        denied_partner: Option<usize>,
    ) {
        if g.turn % 12 != pid as u32 % 12 || !g.players[pid].civics.contains(&crate::name!("civil_service")) {
            return;
        }
        let kind = match plan.strategy {
            GrandStrategy::Science => "research",
            GrandStrategy::Culture => "cultural",
            GrandStrategy::Religion => "religious",
            GrandStrategy::Conquest | GrandStrategy::Recovery => "military",
            GrandStrategy::Expansion | GrandStrategy::Diplomacy => "economic",
        };
        if kind == "research" && g.tree_effect(pid, "research_agreements") <= 0.0 {
            return;
        }
        if g.players[pid]
            .alliances
            .values()
            .any(|alliance| alliance.ends > g.turn && alliance.kind == kind)
        {
            return;
        }
        let pending_with = |partner: usize| {
            g.pending_deals.iter().any(|deal| {
                deal.expires >= g.turn
                    && ((deal.from == pid && deal.to == partner)
                        || (deal.from == partner && deal.to == pid))
            })
        };
        let partner = g
            .players
            .iter()
            .filter(|other| {
                other.id != pid
                    && other.alive
                    && !other.is_minor
                    && !other.is_barbarian
                    && g.has_met(pid, other.id)
                    && Some(other.id) != denied_partner
                    && !g.is_at_war(pid, other.id)
                    && other.civics.contains(&crate::name!("civil_service"))
                    && g.alliance_with(pid, other.id).is_none()
                    && !pending_with(other.id)
                    && (kind != "research" || g.tree_effect(other.id, "research_agreements") > 0.0)
                    && !other
                        .alliances
                        .values()
                        .any(|alliance| alliance.ends > g.turn && alliance.kind == kind)
                    && g.players[pid]
                        .grievances
                        .get(&other.id)
                        .copied()
                        .unwrap_or(0.0)
                        < 75.0
                    && self.rival_victory_pressure(g, other.id).progress < 82
            })
            .max_by(|left, right| {
                let score = |other: usize| {
                    let friendship = if g.are_friends(pid, other) {
                        180.0
                    } else {
                        0.0
                    };
                    let connected = if g.routes.iter().any(|route| {
                        route.ends > g.turn
                            && ((route.owner == pid
                                && g.cities
                                    .get(&route.dest)
                                    .is_some_and(|destination| destination.owner == other))
                                || (route.owner == other
                                    && g.cities
                                        .get(&route.dest)
                                        .is_some_and(|destination| destination.owner == pid)))
                    }) {
                        70.0
                    } else {
                        0.0
                    };
                    let complement = match kind {
                        "research" => {
                            g.players[other]
                                .techs
                                .difference(&g.players[pid].techs)
                                .count() as f64
                                * 4.0
                        }
                        "cultural" => g.tourism_per_turn(other).min(300.0) * 0.15,
                        "economic" => {
                            g.players
                                .iter()
                                .filter(|minor| minor.alive && minor.is_minor)
                                .filter(|minor| g.suzerain_of(minor.id) == Some(other))
                                .count() as f64
                                * 35.0
                        }
                        "military" => g.military_power(other).min(250.0) * 0.25,
                        "religious" => g.players[other].religion.is_some() as usize as f64 * 45.0,
                        _ => 0.0,
                    };
                    friendship + connected + complement
                        - g.players[pid]
                            .grievances
                            .get(&other)
                            .copied()
                            .unwrap_or(0.0)
                };
                score(left.id)
                    .partial_cmp(&score(right.id))
                    .unwrap()
                    .then_with(|| right.id.cmp(&left.id))
            })
            .map(|other| other.id);
        if let Some(partner) = partner {
            let _ = g.apply(
                pid,
                &Action::ProposeDeal {
                    player: partner,
                    give_gold: 0.0,
                    request_gold: 0.0,
                    open_borders: g.players[pid].civics.contains(&crate::name!("early_empire")),
                    friendship: true,
                    peace: false,
                    alliance: Some(kind.to_string()),
                },
            );
        }
    }

    fn congress_choice(
        &self,
        g: &Game,
        pid: usize,
        resolution: &CongressResolution,
        strategy: GrandStrategy,
    ) -> Option<String> {
        if let Some(proposal) = g.emergency_proposal_for_resolution(&resolution.id) {
            if proposal.target == pid {
                return Some("B:oppose".to_string());
            }
            if !proposal.eligible.contains(&pid) {
                return None;
            }
            let grievance = g.players[pid]
                .grievances
                .get(&proposal.target)
                .copied()
                .unwrap_or(0.0);
            let threat = self.rival_victory_pressure(g, proposal.target).progress;
            let affordable_war =
                g.military_power(pid) * 1.75 + 20.0 >= g.military_power(proposal.target);
            let support = proposal.kind == "city_state"
                || strategy == GrandStrategy::Diplomacy
                || grievance >= 25.0
                || threat >= 55
                || affordable_war;
            return Some(if support { "A:support" } else { "B:oppose" }.to_string());
        }
        // Legacy saves encoded only a target. Preserve their old strategic
        // behavior while new sessions use explicit `A:target`/`B:target`
        // ballots.
        if resolution
            .choices
            .iter()
            .all(|choice| !choice.contains(':'))
        {
            let own = pid.to_string();
            return match resolution.id.as_str() {
                "world_leader" | "international_aid" if strategy == GrandStrategy::Diplomacy => {
                    resolution
                        .choices
                        .iter()
                        .find(|choice| **choice == own)
                        .cloned()
                }
                "world_leader" | "international_aid" => resolution
                    .choices
                    .iter()
                    .filter_map(|choice| {
                        choice.parse::<usize>().ok().map(|target| (choice, target))
                    })
                    .min_by_key(|(_, target)| (g.players[*target].dvp, *target))
                    .map(|(choice, _)| choice.clone()),
                "world_fair" if strategy == GrandStrategy::Culture => resolution
                    .choices
                    .iter()
                    .find(|choice| **choice == own)
                    .cloned(),
                "world_fair" => resolution
                    .choices
                    .iter()
                    .filter_map(|choice| {
                        choice.parse::<usize>().ok().map(|target| (choice, target))
                    })
                    .max_by(|left, right| {
                        g.players[left.1]
                            .culture_lifetime
                            .partial_cmp(&g.players[right.1].culture_lifetime)
                            .unwrap_or(std::cmp::Ordering::Equal)
                            .then_with(|| right.1.cmp(&left.1))
                    })
                    .map(|(choice, _)| choice.clone()),
                _ => resolution.choices.first().cloned(),
            };
        }

        let diplomatic_leader = g
            .players
            .iter()
            .filter(|player| player.alive && !player.is_minor && !player.is_barbarian)
            .max_by_key(|player| (player.dvp, std::cmp::Reverse(player.id)))
            .map(|player| player.id);
        // Who a targeted penalty is pointed at. `world_leader` keeps aiming at
        // the diplomatic leader because its +/-2 moves Diplomatic Victory
        // Points and nothing else; the resolutions that cost an empire real
        // yields aim at whoever is actually about to win. See
        // [`Self::congress_counter_leader`] for what the census measured.
        let denied = self
            .congress_counter_leader
            .then(|| self.victory_denial(g, pid).map(|(rival, _)| rival))
            .flatten();
        let counter_target = denied.or(diplomatic_leader);
        let preferred_district = match strategy {
            GrandStrategy::Science => "campus",
            GrandStrategy::Culture => "theater_square",
            GrandStrategy::Religion => "holy_site",
            GrandStrategy::Conquest | GrandStrategy::Recovery => "encampment",
            GrandStrategy::Diplomacy => "diplomatic_quarter",
            GrandStrategy::Expansion => "commercial_hub",
        };
        let preferred_person = match strategy {
            GrandStrategy::Science => "scientist",
            GrandStrategy::Culture => "artist",
            GrandStrategy::Religion => "prophet",
            GrandStrategy::Conquest | GrandStrategy::Recovery => "general",
            GrandStrategy::Diplomacy | GrandStrategy::Expansion => "merchant",
        };
        let preferred_work = match strategy {
            GrandStrategy::Culture => "art",
            GrandStrategy::Religion => "relic",
            _ => "writing",
        };
        let observed = |choice: &str| {
            resolution
                .ballots
                .values()
                .filter(|(cast, _)| cast == choice)
                .map(|(_, votes)| *votes as f64)
                .sum::<f64>()
        };

        resolution.choices.iter().cloned().max_by(|left, right| {
            let score = |choice: &str| {
                let (outcome, target) = Game::congress_choice_parts(choice);
                let target_player = target.parse::<usize>().ok();
                let base = match resolution.id.as_str() {
                    "world_leader" => match (outcome, target_player) {
                        ("A", Some(target))
                            if target == pid && strategy == GrandStrategy::Diplomacy =>
                        {
                            1_000.0
                        }
                        ("B", Some(target))
                            if Some(target) == diplomatic_leader && target != pid =>
                        {
                            900.0
                        }
                        ("A", Some(target)) => 100.0 - 12.0 * g.players[target].dvp as f64,
                        ("B", Some(target)) => 20.0 + 18.0 * g.players[target].dvp as f64,
                        _ => 0.0,
                    },
                    "mercenary_companies" => match (outcome, target) {
                        ("B", "production") => 340.0,
                        ("B", "gold") => 180.0,
                        ("B", "faith") if strategy == GrandStrategy::Religion => 230.0,
                        ("B", "faith") => 90.0,
                        ("A", _) => -120.0,
                        _ => 0.0,
                    },
                    "luxury_policy" => {
                        let own = g.resource_access_count(pid, target) as f64;
                        let rival = g
                            .players
                            .iter()
                            .filter(|player| player.id != pid)
                            .map(|player| g.resource_access_count(player.id, target))
                            .max()
                            .unwrap_or(0) as f64;
                        if outcome == "A" {
                            own * 75.0
                        } else {
                            rival * 55.0 - own * 85.0
                        }
                    }
                    "trade_policy" => match target_player {
                        // Outcome B embargoes every inter-civ trade route the
                        // target has. Against an empire about to win that is
                        // worth more than a trade slot of our own, which is all
                        // outcome A on ourselves buys.
                        Some(target)
                            if outcome == "B"
                                && Some(target) == denied
                                && target != pid =>
                        {
                            420.0
                        }
                        Some(target) if outcome == "A" && target == pid => 260.0,
                        Some(target)
                            if outcome == "B"
                                && Some(target) == counter_target
                                && target != pid =>
                        {
                            150.0
                        }
                        Some(target)
                            if outcome == "A" && g.alliance_with(pid, target).is_some() =>
                        {
                            120.0
                        }
                        _ => 10.0,
                    },
                    "world_religion" => {
                        let mine = g.players[pid].religion.as_deref() == Some(target);
                        if outcome == "A" && mine {
                            320.0
                        } else if outcome == "B" && !mine {
                            150.0
                        } else {
                            0.0
                        }
                    }
                    "urban_development_treaty" => {
                        if outcome == "A" && target == preferred_district {
                            280.0
                        } else if outcome == "A" {
                            80.0
                        } else {
                            -80.0
                        }
                    }
                    "patronage" => {
                        if outcome == "A" && target == preferred_person {
                            280.0
                        } else if outcome == "A" {
                            70.0
                        } else {
                            -100.0
                        }
                    }
                    "military_advisory" => {
                        let own = g
                            .units
                            .values()
                            .filter(|unit| {
                                unit.owner == pid
                                    && g.rules.units[unit.kind].promotion_class == target
                            })
                            .count() as f64;
                        let rival = g
                            .units
                            .values()
                            .filter(|unit| {
                                unit.owner != pid
                                    && g.rules.units[unit.kind].promotion_class == target
                            })
                            .count() as f64;
                        if outcome == "A" {
                            own * 45.0 - rival * 10.0
                        } else {
                            rival * 35.0 - own * 50.0
                        }
                    }
                    "migration_treaty" => match (outcome, target_player) {
                        // Outcome B costs its target 20% growth and pushes its
                        // loyalty. Shipped, it scores 0.0 against every rival,
                        // so the penalty can never be aimed at anybody.
                        ("B", Some(target)) if Some(target) == denied && target != pid => 300.0,
                        ("A", Some(target))
                            if target == pid && strategy == GrandStrategy::Expansion =>
                        {
                            220.0
                        }
                        ("B", Some(target)) if target == pid => 140.0,
                        ("A", Some(target)) if target != pid => 35.0,
                        _ => 0.0,
                    },
                    "public_relations" => match (outcome, target_player) {
                        ("B", Some(target)) if target == pid => 230.0,
                        ("A", Some(target))
                            if Some(target) == counter_target && target != pid =>
                        {
                            150.0
                        }
                        _ => 0.0,
                    },
                    "heritage_organization" => {
                        if outcome == "A" && target == preferred_work {
                            300.0
                        } else if outcome == "A" {
                            90.0
                        } else {
                            -120.0
                        }
                    }
                    "arms_control" => match target_player {
                        Some(target) => {
                            let inventory = |player: usize| {
                                [
                                    "project_effect:nuclear_devices",
                                    "project_effect:thermonuclear_devices",
                                ]
                                .into_iter()
                                .map(|key| {
                                    g.players[player]
                                        .counters
                                        .get(key)
                                        .copied()
                                        .unwrap_or(0)
                                        .max(0)
                                })
                                .sum::<i64>() as f64
                            };
                            let mine = inventory(pid);
                            let theirs = inventory(target);
                            let major_inventories: Vec<f64> = g
                                .players
                                .iter()
                                .filter(|player| {
                                    player.alive && !player.is_minor && !player.is_barbarian
                                })
                                .map(|player| inventory(player.id))
                                .collect();
                            let world_total = major_inventories.iter().sum::<f64>();
                            let equalized_total =
                                theirs * major_inventories.len().max(1) as f64;
                            let disarmament = world_total - equalized_total;
                            match outcome {
                                // Outcome A copies the target's stockpile to every
                                // major. Peaceful strategies therefore nominate the
                                // smallest arsenal, not the nuclear leader.
                                "A" if strategy != GrandStrategy::Conquest => {
                                    180.0 + 55.0 * disarmament
                                        - 75.0 * (-disarmament).max(0.0)
                                }
                                "A" => 20.0 + 35.0 * (theirs - mine)
                                    - 45.0 * (equalized_total - world_total).max(0.0),
                                "B" if target != pid => {
                                    let aggression = if matches!(
                                        strategy,
                                        GrandStrategy::Conquest | GrandStrategy::Recovery
                                    ) {
                                        100.0
                                    } else {
                                        55.0
                                    };
                                    90.0 + aggression * theirs
                                }
                                "B" => -500.0,
                                _ => 0.0,
                            }
                        }
                        None => 0.0,
                    },
                    "world_ideology" => {
                        let mine = g.players[pid].government.as_deref() == Some(target);
                        let rival_users = g
                            .players
                            .iter()
                            .filter(|player| {
                                player.id != pid
                                    && player.alive
                                    && !player.is_minor
                                    && !player.is_barbarian
                                    && player.government.as_deref() == Some(target)
                            })
                            .count() as f64;
                        match outcome {
                            "A" if mine => 320.0,
                            "A" => 30.0,
                            "B" if mine => -260.0,
                            "B" => 90.0 + 70.0 * rival_users,
                            _ => 0.0,
                        }
                    }
                    "border_control_treaty" => match (outcome, target_player) {
                        // Outcome B stops the target annexing tiles by border
                        // growth. Shipped, it is aimed by raw territory -- the
                        // one leader-targeting term in this table that already
                        // uses something other than Diplomatic Victory Points,
                        // and still not the empire about to win.
                        ("B", Some(target)) if Some(target) == denied && target != pid => 400.0,
                        ("A", Some(target)) if target == pid => 300.0,
                        ("B", Some(target)) if target == pid => -240.0,
                        ("B", Some(target)) => {
                            let territory = g
                                .player_city_ids(target)
                                .into_iter()
                                .map(|city| g.cities[&city].owned_tiles.len())
                                .sum::<usize>() as f64;
                            80.0 + territory
                        }
                        _ => 20.0,
                    },
                    "public_works_program" => {
                        let queued = |owner: usize| {
                            g.cities
                                .values()
                                .filter(|city| city.owner == owner)
                                .filter(|city| {
                                    city.queue.iter().any(|item| {
                                        matches!(item, Item::Project { project } if project == target)
                                    })
                                })
                                .count() as f64
                        };
                        let own_queued = queued(pid);
                        let rival_queued = g
                            .players
                            .iter()
                            .filter(|player| {
                                player.id != pid
                                    && player.alive
                                    && !player.is_minor
                                    && !player.is_barbarian
                            })
                            .map(|player| queued(player.id))
                            .sum::<f64>();
                        let aligned = match strategy {
                            GrandStrategy::Science => {
                                target.contains("launch_")
                                    || target.contains("laser_station")
                                    || target == "exoplanet_expedition"
                            }
                            GrandStrategy::Conquest | GrandStrategy::Recovery => {
                                target.contains("nuclear")
                                    || matches!(target, "manhattan_project" | "operation_ivy")
                            }
                            GrandStrategy::Diplomacy => target == "carbon_recapture",
                            _ => false,
                        };
                        match (outcome, aligned) {
                            ("A", true) => 300.0 + 160.0 * own_queued,
                            ("A", false) => 65.0 + 180.0 * own_queued,
                            ("B", true) => {
                                -220.0 + 140.0 * rival_queued - 180.0 * own_queued
                            }
                            ("B", false) => {
                                25.0 + 140.0 * rival_queued - 180.0 * own_queued
                            }
                            _ => 0.0,
                        }
                    }
                    "global_energy_treaty" => {
                        let queued = |owner: usize| {
                            g.cities
                                .values()
                                .filter(|city| city.owner == owner)
                                .filter(|city| {
                                    city.queue.iter().any(|item| {
                                        matches!(item, Item::Building { building } if building == target)
                                    })
                                })
                                .count() as f64
                        };
                        let own_queued = queued(pid);
                        let rival_queued = g
                            .players
                            .iter()
                            .filter(|player| {
                                player.id != pid
                                    && player.alive
                                    && !player.is_minor
                                    && !player.is_barbarian
                            })
                            .map(|player| queued(player.id))
                            .sum::<f64>();
                        let preferred = match strategy {
                            GrandStrategy::Science | GrandStrategy::Diplomacy => {
                                "nuclear_power_plant"
                            }
                            GrandStrategy::Conquest | GrandStrategy::Recovery => "coal_power_plant",
                            _ => "oil_power_plant",
                        };
                        match (outcome, target) {
                            ("A", candidate) if candidate == preferred => {
                                270.0 + 160.0 * own_queued
                            }
                            ("A", _) => 90.0 + 160.0 * own_queued,
                            ("B", "coal_power_plant") if strategy == GrandStrategy::Diplomacy => {
                                180.0 + 120.0 * rival_queued - 180.0 * own_queued
                            }
                            ("B", candidate) if candidate == preferred => {
                                -180.0 + 120.0 * rival_queued - 180.0 * own_queued
                            }
                            ("B", _) => 35.0 + 120.0 * rival_queued - 180.0 * own_queued,
                            _ => 0.0,
                        }
                    }
                    "deforestation_treaty" => {
                        let owned_copies = |owner: usize| {
                            g.cities
                                .values()
                                .filter(|city| city.owner == owner)
                                .flat_map(|city| city.owned_tiles.iter())
                                .filter(|position| {
                                    g.map.tiles[*position].feature.as_deref() == Some(target)
                                })
                                .count() as f64
                        };
                        let own_copies = owned_copies(pid);
                        let rival_copies = g
                            .players
                            .iter()
                            .filter(|player| {
                                player.id != pid
                                    && player.alive
                                    && !player.is_minor
                                    && !player.is_barbarian
                            })
                            .map(|player| owned_copies(player.id))
                            .sum::<f64>();
                        match outcome {
                            "A" => {
                                65.0
                                    + 35.0 * own_copies
                                    + if strategy == GrandStrategy::Expansion {
                                        90.0
                                    } else {
                                        0.0
                                    }
                            }
                            "B" if strategy == GrandStrategy::Culture && target == "forest" => {
                                165.0 + 5.0 * (own_copies + rival_copies)
                            }
                            "B" => 20.0 + 5.0 * rival_copies - 20.0 * own_copies,
                            _ => 0.0,
                        }
                    }
                    _ => 0.0,
                };
                base + observed(choice) * 35.0
            };
            score(left)
                .partial_cmp(&score(right))
                .unwrap_or(std::cmp::Ordering::Equal)
                .then_with(|| right.cmp(left))
        })
    }

    /// Prefer an available low-Grievance casus belli. If none is ready, a
    /// major rival is denounced and the campaign waits for Formal War rather
    /// than opening with a Surprise War. The sole exception is a rival already
    /// on the brink of victory, where five setup turns can lose the game.
    /// City-states cannot be denounced and therefore remain direct targets.
    fn preferred_war_opening(&self, g: &Game, pid: usize, target: usize) -> Option<Action> {
        let legal = g.legal_actions_within(pid, ActionFamilies::DIPLOMACY);
        let casus_belli = legal
            .iter()
            .filter_map(|action| match action {
                Action::DeclareWarWithCasusBelli {
                    player,
                    casus_belli,
                } if *player == target => {
                    let grievance_cost = match casus_belli.as_str() {
                        "reconquest_war" | "protectorate_war" | "liberation_war" => 0,
                        "golden_age_war" => 25,
                        "holy_war" | "colonial_war" | "retribution_war" | "ideological_war" => 50,
                        "territorial_war" => 75,
                        // Formal War is the baseline. This branch is also a
                        // conservative fallback if another legal profile is
                        // added without teaching the planner its cost.
                        _ => 100,
                    };
                    Some((grievance_cost, casus_belli, action))
                }
                _ => None,
            })
            .min_by_key(|(cost, name, _)| (*cost, *name))
            .map(|(_, _, action)| action.clone());
        if casus_belli.is_some() {
            return casus_belli;
        }

        let surprise = legal.iter().find_map(|action| match action {
            Action::DeclareWar { player } if *player == target => Some(action.clone()),
            _ => None,
        });
        if g.players[target].is_minor {
            return surprise;
        }

        // A final exoplanet launch and a religious match point are both
        // irreversible victory clocks. They already interrupt strategic
        // planning before 90%, so waiting five turns for a Formal War here
        // would make the counter-campaign start after the game can end.
        let urgent = self.urgent_victory_threat(g, target);
        let denounced = g.players[pid]
            .denounced_until
            .get(&target)
            .is_some_and(|until| *until > g.turn);
        if !urgent && !denounced {
            return legal.iter().find_map(|action| match action {
                Action::Denounce { player } if *player == target => Some(action.clone()),
                _ => None,
            });
        }
        if urgent {
            surprise
        } else {
            // The denouncement is active but its five-turn preparation period
            // has not elapsed, so preserve the army and wait for Formal War.
            None
        }
    }

    /// A peacetime tile from which a ground force can begin the selected
    /// campaign without trespassing through the target's borders. Keeping the
    /// ring several tiles outside the city leaves room for different combat
    /// roles to assemble while keeping the army close enough to exploit the
    /// opening turns of the war.
    fn campaign_staging_position(
        &self,
        g: &Game,
        pid: usize,
        target: usize,
        uid: u32,
        objective: Pos,
        position: Pos,
    ) -> bool {
        let Some(tile) = g.map.get(position) else {
            return false;
        };
        let distance = g.wdist(position, objective);
        if !(3..=5).contains(&distance)
            || g.rules.is_water(tile)
            || g.city_at(position).is_some()
            || !g.unit_can_traverse(uid, position)
        {
            return false;
        }
        let territory = tile
            .owner_city
            .and_then(|city| g.cities.get(&city))
            .map(|city| city.owner);
        territory != Some(target)
            && territory.is_none_or(|owner| {
                owner == pid || g.has_open_borders(pid, owner)
            })
    }

    fn staged_campaign_units(
        &self,
        g: &Game,
        pid: usize,
        target: usize,
        objective: Pos,
    ) -> Vec<u32> {
        g.player_unit_ids(pid)
            .into_iter()
            .filter(|uid| {
                let unit = &g.units[uid];
                let spec = &g.rules.units[unit.kind];
                spec.class == "military"
                    && !matches!(spec.domain.as_deref(), Some("sea" | "air"))
                    && (spec.is_melee_capable() || spec.has_ranged_attack())
                    && unit.hp as f64 > self.base.w.withdraw_hp
                    && self.campaign_staging_position(
                        g,
                        pid,
                        target,
                        *uid,
                        objective,
                        unit.pos,
                    )
            })
            .collect()
    }

    /// Freeze the rivals the connected-rush treatment may ever target.
    ///
    /// Waiting until every living major has founded its capital prevents seat
    /// order from deciding which rivals exist. Returning whether the freeze
    /// happened lets the caller reassess immediately: the same turn is the
    /// treatment's first opportunity to differ from ordinary `advanced`.
    fn freeze_rush_route_targets(&mut self, g: &Game, pid: usize) -> bool {
        if !self.early_rush || !self.route_connected_rush || self.rush_route_targets.is_some() {
            return false;
        }

        let Some(majors) = g
            .players
            .iter()
            .filter(|player| player.alive && !player.is_minor && !player.is_barbarian)
            .map(|player| {
                g.player_city_ids(player.id)
                    .into_iter()
                    .find(|city| g.cities[city].is_capital)
                    .map(|city| (player.id, g.cities[&city].pos))
            })
            .collect::<Option<Vec<_>>>()
        else {
            return false;
        };

        let land_melee: Vec<u32> = g
            .player_unit_ids(pid)
            .into_iter()
            .filter(|unit| {
                let spec = &g.rules.units[g.units[unit].kind];
                spec.class == "military"
                    && spec.is_melee_capable()
                    && !matches!(spec.domain.as_deref(), Some("sea" | "air"))
            })
            .collect();
        let reachable = majors
            .into_iter()
            .filter(|(target, _)| *target != pid)
            .filter(|(_, capital)| {
                land_melee.iter().any(|unit| {
                    g.wdist(g.units[unit].pos, *capital) <= RUSH_STAGING_RANGE
                        || g.route_step(*unit, *capital, RUSH_STAGING_RANGE).is_some()
                })
            })
            .map(|(target, _)| target)
            .collect();
        self.rush_route_targets = Some(reachable);
        true
    }

    /// Global power answers whether a war is affordable; this answers whether
    /// the army is actually in position to prosecute it. At least one melee
    /// unit is mandatory because ranged and siege units cannot capture a city.
    /// The neighbour an ancient rush should open on, and their capital.
    ///
    /// Returns `None` unless every measured precondition holds, because the
    /// whole value of the lane is that it plays a window rather than a
    /// preference. See `early_rush` for where each number comes from.
    fn early_rush_victim(&self, g: &Game, pid: usize) -> Option<(usize, u32)> {
        if !self.early_rush {
            return None;
        }
        // A war already running is not re-opened every turn, and dropping the
        // lane at `RUSH_WINDOW_CLOSES` mid-siege abandons the campaign with
        // the stack on the ring: melee adjacent to the objective fell to zero
        // at turn 80 for exactly this reason. The window governs **opening** a
        // rush; finishing one is governed by the war.
        let already_committed = g.players.iter().any(|player| {
            player.id != pid
                && player.alive
                && !player.is_minor
                && !player.is_barbarian
                && g.is_at_war(pid, player.id)
        });
        if g.turn >= RUSH_WINDOW_CLOSES && !already_committed {
            return None;
        }
        let mine: Vec<Pos> = g
            .player_city_ids(pid)
            .into_iter()
            .map(|cid| g.cities[&cid].pos)
            .collect();
        if mine.is_empty() {
            return None;
        }
        let my_power = g.military_power(pid);
        g.players
            .iter()
            .filter(|player| {
                player.id != pid && player.alive && !player.is_minor && !player.is_barbarian
            })
            .filter(|player| {
                !self.route_connected_rush
                    || self
                        .rush_route_targets
                        .as_ref()
                        .is_some_and(|targets| targets.contains(&player.id))
            })
            .filter(|player| self.campaign_target_legal(g, pid, player.id))
            // Not stronger than us. The stack is what makes the rush work, so
            // this is a floor against opening on somebody who can answer it,
            // not the 1.32-plus-12 superiority `advanced` waits for.
            //
            // It is a test for *opening* a war, not for continuing one. Once
            // the war is running, losing this test would switch the whole lane
            // off mid-campaign — dropping the army floor and handing the
            // column's objective back to the empire-global `threatened_city` —
            // which is the campaign abandoning itself at exactly the moment
            // the victim starts fighting back.
            // ⚠ Tightened to `* 0.85` — "genuinely weaker, not merely
            // comparable" — and measured clearly worse: early wars fell 33 to
            // 14, the median declaration slipped turn 32 to 47, and kills
            // slipped 47 to 70. Early empires are *all* near-parity because
            // they all field one or two units, so a superiority test does not
            // select weak victims, it just postpones the rush out of its own
            // window. What makes the rush work is the staged stack against an
            // unwalled capital, which is what the readiness gate checks.
            .filter(|player| {
                g.is_at_war(pid, player.id)
                    || g.military_power(player.id) <= my_power * 1.15 + 5.0
            })
            .filter_map(|player| {
                // The capital while they have one, otherwise whatever is
                // left. Wiping a neighbour means taking *every* city, and a
                // rush that stops the moment the palace falls leaves a
                // one-city rump alive — which is the difference between a
                // capture and an elimination.
                let capital = g
                    .player_city_ids(player.id)
                    .into_iter()
                    .find(|cid| g.cities[cid].is_capital)
                    .or_else(|| {
                        g.player_city_ids(player.id)
                            .into_iter()
                            .min_by_key(|cid| {
                                let pos = g.cities[cid].pos;
                                (mine.iter().map(|own| g.wdist(*own, pos)).min().unwrap_or(i32::MAX), *cid)
                            })
                    })?;
                let city = &g.cities[&capital];
                // The window is defined by the walls, so test the walls rather
                // than trusting the turn number. `rush_census` reports 0%
                // walled capitals through turn 60, but a modded ruleset, a
                // faster speed, or a defender who reacted would all show up
                // here and close the lane honestly.
                if city
                    .buildings
                    .iter()
                    .any(|b| g.rules.buildings[b].outer_defense > 0)
                {
                    return None;
                }
                let reach = mine.iter().map(|pos| g.wdist(*pos, city.pos)).min()?;
                (reach <= RUSH_REACH).then_some((player.id, capital, reach))
            })
            // Nearest first: the march is the binding cost, not the siege.
            // Break ties on the weaker army, then on id so the choice is
            // deterministic across a mirrored pair.
            .min_by(|a, b| {
                a.2.cmp(&b.2)
                    .then(
                        g.military_power(a.0)
                            .total_cmp(&g.military_power(b.0)),
                    )
                    .then(a.0.cmp(&b.0))
            })
            .map(|(target, capital, _)| (target, capital))
    }

    /// Whether the stack standing off the victim's capital is the size the
    /// engine's own combat math says takes it.
    ///
    /// A Monte Carlo over `damage`, `effective_strength` and `city_strength`
    /// against the measured turn-50 capital (strength 17.2, mean garrison 0.7,
    /// no walls) puts two melee units at 100% and one at 0%. Four is the
    /// figure that still reads 100% when the defender pulls its entire field
    /// army home — the case this lane cannot rule out, since it declares
    /// three tiles from the victim's capital.
    fn early_rush_stack_ready(&self, g: &Game, pid: usize, target: usize, cid: u32) -> bool {
        let Some(city) = g.cities.get(&cid) else {
            return false;
        };
        let objective = city.pos;
        let units = self.staged_campaign_units(g, pid, target, objective);
        let takers: Vec<u32> = units
            .into_iter()
            .filter(|uid| g.rules.units[g.units[uid].kind].is_melee_capable())
            .collect();
        if takers.len() < RUSH_STACK {
            return false;
        }
        // Counting takers is not the same as being able to finish, and the
        // difference cost this lane twenty turns. War was declared at turn 30
        // on two warriors and the first city did not fall until turn 54: a
        // warrior against the measured capital takes 28 damage a blow and dies
        // on its fourth, having dealt 134 of the 200 needed. The stack traded
        // itself and the next one had to be built and marched all over again.
        //
        // So ask the engine's own combat math whether this force can take the
        // city *before it dies*, using the same `damage` curve the fight will
        // use. `30 * exp((att - def) / 25)` per blow each way, `100 / incoming`
        // blows survived.
        let defense = g.city_strength(cid);
        let deliverable: f64 = takers
            .iter()
            .filter_map(|uid| g.units.get(uid))
            .map(|unit| {
                let attack = crate::game::effective_strength(
                    g.unit_strength(unit, false),
                    unit.hp,
                );
                let out = 30.0 * ((attack - defense) / 25.0).exp();
                let incoming = (30.0 * ((defense - attack) / 25.0).exp()).max(1.0);
                let blows = (unit.hp as f64 / incoming).floor().max(1.0);
                out * blows
            })
            .sum();
        // The city's pool, plus a turn of the 20 HP/turn it regenerates
        // whenever the ring is not fully sealed.
        deliverable >= city.hp as f64 + 20.0
    }

    fn campaign_staged_for_war(
        &self,
        g: &Game,
        pid: usize,
        target: usize,
        objective: Pos,
        committed_domination: bool,
    ) -> bool {
        let units = self.staged_campaign_units(g, pid, target, objective);
        let has_capturer = units.iter().any(|uid| {
            g.rules.units[g.units[uid].kind].is_melee_capable()
        });
        let ratio = self.local_strength_ratio(g, pid, &units, &[target], objective);
        let formation_ready = units.len() >= 3 || (units.len() >= 2 && ratio >= 1.60);
        let minimum_ratio = if committed_domination { 0.90 } else { 1.05 };
        formation_ready && has_capturer && ratio + 1e-9 >= minimum_ratio
    }

    /// Drive one melee unit of an ancient rush directly at the objective
    /// capital, bypassing the force-group heuristics entirely.
    ///
    /// Four separate attempts to make those heuristics conduct a siege made
    /// things measurably worse (see the rejected notes on `focus_target` and
    /// on the `relieving`/`Muster` postures). They are tuned for a field
    /// campaign between comparable armies, and a rush is not that: it is four
    /// melee units against an unwalled capital holding a garrison of 0.7,
    /// inside a window that shuts.
    ///
    /// The routine is the Monte Carlo's own recipe, in order:
    ///
    /// 1. **Walk into a depleted city.** An ordinary ranged attack cannot take
    ///    a city below 1 HP, so a city at 0 was opened by a Bombard and is
    ///    standing open for whoever steps in.
    /// 2. **Attack from the ring** if already on it.
    /// 3. **Take a free ring tile.** Every melee unit on the ring both adds a
    ///    blow and helps seal the siege, and an unsealed city heals 20 HP a
    ///    turn — which is what actually defeated this lane before: the stack
    ///    reached the 3-5 tile staging ring at full strength (measured max 4)
    ///    while the city's own ring never held more than two.
    ///
    /// Returns `None` when this unit is not part of a live rush, leaving the
    /// ordinary wartime behaviour untouched.
    fn rush_siege_step(
        &mut self,
        g: &mut Game,
        pid: usize,
        uid: u32,
        plan: &StrategicPlan,
    ) -> Option<bool> {
        if !plan.rush {
            return None;
        }
        let target = plan.target_player?;
        if !g.is_at_war(pid, target) {
            return None;
        }
        let cid = plan.target_city?;
        let city = g.cities.get(&cid).filter(|city| city.owner == target)?;
        let objective = city.pos;
        let depleted = city.hp <= 0;
        let spec = &g.rules.units[g.units.get(&uid)?.kind];
        if !spec.is_melee_capable() || matches!(spec.domain.as_deref(), Some("sea" | "air")) {
            return None;
        }
        let here = g.units[&uid].pos;

        if g.wdist(here, objective) <= 1 {
            if depleted && g.can_move(uid, objective) {
                // The city is open. Walking in *is* the capture.
                return Some(g.apply(pid, &Action::Move { unit: uid, to: objective }).is_ok());
            }
            let attacked = g
                .apply(
                    pid,
                    &Action::Attack {
                        unit: uid,
                        target: objective,
                    },
                )
                .is_ok();
            if attacked {
                return Some(true);
            }
            // Out of moves this turn: hold the ring rather than give it up.
            // A vacated ring tile is 20 HP a turn handed back.
            return Some(self.base.fortify_or_stop(g, pid, uid));
        }

        // Close on a free ring tile — but *which* ring tile decides whether
        // this is a siege or a queue.
        //
        // `district_under_siege` needs every passable neighbour of the city
        // occupied or covered by our zone of control, and a city that is not
        // besieged heals 20 HP a turn. A ZOC unit covers its own ring tile
        // plus both ring-neighbours, three of six, so **two units placed three
        // apart seal the ring and two units side by side do not**. Routing to
        // the nearest free tile bunches them, which is why an unsealed capital
        // took 23 turns to fall against a Monte Carlo estimate of three.
        //
        // So prefer the free tile furthest from the ones we already hold, and
        // only then the one we can reach.
        let held: Vec<Pos> = g
            .player_unit_ids(pid)
            .into_iter()
            .filter(|other| *other != uid)
            .filter_map(|other| g.units.get(&other))
            .filter(|other| g.rules.units[other.kind].is_melee_capable())
            .map(|other| other.pos)
            .filter(|pos| g.wdist(*pos, objective) <= 1)
            .collect();
        let mut ring: Vec<Pos> = g
            .wdisk(objective, 1)
            .into_iter()
            .filter(|pos| {
                *pos != objective
                    && g.unit_can_traverse(uid, *pos)
                    && g.units_at(*pos).iter().all(|other| {
                        g.units.get(other).is_some_and(|other| other.owner != pid)
                    })
            })
            .collect();
        if ring.is_empty() {
            return None;
        }
        // Spread first, then nearness to us, then position for determinism.
        ring.sort_by_key(|pos| {
            let spread = held
                .iter()
                .map(|other| g.wdist(*pos, *other))
                .min()
                .unwrap_or(i32::MAX);
            (std::cmp::Reverse(spread), g.wdist(here, *pos), pos.0, pos.1)
        });
        // Walk the preference order: the best tile may be unroutable this
        // turn, and giving up on it would leave the unit standing still.
        for goal in ring.iter().take(3) {
            let goals: HashSet<Pos> = std::iter::once(*goal).collect();
            if let Some(next) = g
                .route_step_to_any(uid, &goals)
                .filter(|pos| g.can_move(uid, *pos))
            {
                return Some(g.apply(pid, &Action::Move { unit: uid, to: next }).is_ok());
            }
        }
        None
    }

    /// Redirect an otherwise idle field unit to the active conquest front.
    /// Returning `Some` means the campaign owns this unit's peacetime order,
    /// including holding a completed staging position; `None` leaves ordinary
    /// patrol, exploration, and naval-escort behavior unchanged.
    fn campaign_staging_step(
        &mut self,
        g: &mut Game,
        pid: usize,
        uid: u32,
        plan: &StrategicPlan,
    ) -> Option<bool> {
        if plan.strategy != GrandStrategy::Conquest {
            return None;
        }
        let target = plan.target_player?;
        let objective = plan
            .target_city
            .and_then(|city| g.cities.get(&city))
            .filter(|city| city.owner == target)
            .map(|city| city.pos)?;
        if !self.campaign_target_legal(g, pid, target) || g.is_at_war(pid, target) {
            return None;
        }
        let unit = &g.units[&uid];
        let spec = &g.rules.units[unit.kind];
        if !matches!(spec.class.as_str(), "military" | "support")
            || matches!(spec.domain.as_deref(), Some("sea" | "air"))
            || (BasicAi::unit_doctrine(g, uid) == UnitDoctrine::Recon
                && self.base.has_exploration_target(g, pid, uid))
        {
            return None;
        }
        // An appointed campaign owns an exact package, not every military
        // unit in the empire. Scouts, home defenders, and unrelated ranged
        // units keep their normal jobs while the four assault bodies and real
        // breach element assemble without independently changing target.
        if let Some(war) = self.war_plan.as_ref().filter(|war| {
            war.target_player == target && war.objective_city == plan.target_city.unwrap_or(0)
        }) {
            let designated = self.war_body_kind(g, pid, war, unit.kind)
                || war.breach_unit == Some(unit.kind);
            if !designated {
                return None;
            }
        }
        if self.campaign_staging_position(g, pid, target, uid, objective, unit.pos) {
            return Some(self.base.fortify_or_stop(g, pid, uid));
        }

        let current = unit.pos;
        let goals: HashSet<Pos> = {
            let _memo = g.query_memo();
            g.wdisk(objective, 5)
                .into_iter()
                .filter(|position| {
                    self.campaign_staging_position(g, pid, target, uid, objective, *position)
                        && g.units_at(*position).is_empty()
                })
                .collect()
        };
        let next = g
            .route_step_to_any(uid, &goals)
            .filter(|position| g.can_move(uid, *position))?;
        // Do not use an Open Borders shortcut through the intended victim.
        // The next turn's route search will find a lawful way around it.
        let next_territory = g.map.tiles[&next]
            .owner_city
            .and_then(|city| g.cities.get(&city))
            .map(|city| city.owner);
        if next_territory == Some(target) {
            return Some(self.base.fortify_or_stop(g, pid, uid));
        }
        debug_assert_ne!(next, current);
        Some(g.apply(pid, &Action::Move { unit: uid, to: next }).is_ok())
    }

    /// March a rear unit toward the campaign objective while the war is on.
    ///
    /// `campaign_staging_step` assembles the army before the declaration and
    /// then deliberately stands down: at war, every field unit belongs to a
    /// force group. But groups are cliques at `command_radius`, so the
    /// reinforcement trickle — fresh production, healed units, released
    /// garrisons — forms one- and two-body groups at home whose local
    /// strength at the objective can never clear `LOCAL_SUPERIORITY_FLOOR`.
    /// They hold forever, and the front fights the whole war with whatever
    /// staged on declaration day. Measured on live run
    /// `civvis-20260808T033223Z`: the why ledger shows land forces of one,
    /// two and three against the same objective from t217 to t225, every one
    /// "too weak locally to advance", while the empire fielded 10-14 units.
    ///
    /// Deliberately narrow, in order of what it declines: the homeland keeps
    /// first claim (any threatened city stands the march down empire-wide),
    /// the front group and any group already moving keep their measured
    /// posture logic, a unit in contact belongs to the tactical layer, and a
    /// unit below `withdraw_hp` heals where it stands. What remains is
    /// exactly the standing-still rear, and it walks the same road the
    /// pre-war assembly walked: routed to the objective's 3..=5 staging
    /// ring, never onto the city tile itself. Groups are rebuilt from the
    /// board every turn, so an arrival within `command_radius` of the front
    /// merges into it and takes the front's orders from then on.
    fn wartime_reinforcement_step(
        &mut self,
        g: &mut Game,
        pid: usize,
        uid: u32,
        plan: &StrategicPlan,
        group: Option<&ForceGroup>,
        enemies: &[usize],
    ) -> Option<bool> {
        if !self.war_reinforcement || plan.strategy != GrandStrategy::Conquest {
            return None;
        }
        if plan.threatened_city.is_some() {
            return None;
        }
        let target = plan.target_player?;
        if !g.is_at_war(pid, target) {
            return None;
        }
        let objective = plan
            .target_city
            .and_then(|city| g.cities.get(&city))
            .filter(|city| city.owner == target)
            .map(|city| city.pos)?;
        let rear = group.is_none_or(|group| {
            matches!(group.posture, ForcePosture::Hold | ForcePosture::Muster)
                && g.wdist(group.anchor, objective) > REINFORCEMENT_FRONT_RADIUS
        });
        if !rear {
            return None;
        }
        let unit = &g.units[&uid];
        let spec = &g.rules.units[unit.kind];
        if !matches!(spec.class.as_str(), "military" | "support")
            || matches!(spec.domain.as_deref(), Some("sea" | "air"))
            || (BasicAi::unit_doctrine(g, uid) == UnitDoctrine::Recon
                && self.base.has_exploration_target(g, pid, uid))
        {
            return None;
        }
        if (unit.hp as f64) <= self.base.w.withdraw_hp {
            return None;
        }
        let in_contact = g
            .units
            .values()
            .any(|enemy| enemies.contains(&enemy.owner) && g.wdist(unit.pos, enemy.pos) <= 2);
        if in_contact {
            return None;
        }
        let here = unit.pos;
        let kind = unit.kind;
        // The same road the pre-war assembly walks: route to the objective's
        // staging ring, never onto the city tile itself (a city is attacked,
        // not entered, so a route aimed at its tile finds nothing).
        let goals: HashSet<Pos> = {
            let _memo = g.query_memo();
            g.wdisk(objective, 5)
                .into_iter()
                .filter(|position| {
                    (3..=5).contains(&g.wdist(*position, objective))
                        && g.units_at(*position).is_empty()
                        && g.city_at(*position).is_none()
                        && g.map
                            .get(*position)
                            .is_some_and(|tile| !g.rules.is_water(tile))
                })
                .collect()
        };
        let next = g
            .route_step_to_any(uid, &goals)
            .filter(|position| *position != here && g.can_move(uid, *position))?;
        if self.journal().wants(crate::reasoning::Level::Detail) {
            think!(self.journal(), Military, Detail,
                   "Reinforcing the campaign with {}", plain(&kind);
                   "the front at {:?} is {} tiles away and this unit's group cannot \
                    advance from here",
                   objective, g.wdist(here, objective);
                   objective);
        }
        Some(g.apply(pid, &Action::Move { unit: uid, to: next }).is_ok())
    }

    /// A predecessor that missed the breakthrough upgrade because it was
    /// abroad returns to the nearest owned city before joining the staging
    /// column. This keeps Mobilize from marching an obsolete body away from
    /// the only territory where its reserved upgrade can be executed.
    fn war_return_home_step(
        &mut self,
        g: &mut Game,
        pid: usize,
        uid: u32,
    ) -> Option<bool> {
        let war = self.war_plan.as_ref()?;
        if !matches!(war.phase, WarPhase::Mobilize | WarPhase::Stage)
            || war.predecessor != Some(g.units.get(&uid)?.kind)
        {
            return None;
        }
        let here = g.units[&uid].pos;
        let in_owned_territory = g.map.get(here).is_some_and(|tile| {
            tile.owner_city
                .and_then(|city| g.cities.get(&city))
                .is_some_and(|city| city.owner == pid)
        });
        if in_owned_territory {
            return Some(self.base.fortify_or_stop(g, pid, uid));
        }
        let home = g
            .player_city_ids(pid)
            .into_iter()
            .min_by_key(|city| (g.wdist(here, g.cities[city].pos), *city))
            .map(|city| g.cities[&city].pos)?;
        Some(self.base.step_toward(g, pid, uid, home))
    }

    /// Finish the appointed city as soon as ranged/siege setup opens it. The
    /// normal unit order already resolves those roles before melee; this hook
    /// only claims a body when the city is actually depleted, so it does not
    /// repeat the rejected ancient behavior of ignoring field defenders.
    fn timed_war_finisher_step(
        &mut self,
        g: &mut Game,
        pid: usize,
        uid: u32,
    ) -> Option<bool> {
        let war = self
            .war_plan
            .as_ref()
            .filter(|war| war.phase == WarPhase::Exploit)?;
        let unit = g.units.get(&uid)?;
        if !Self::war_ready_body_kind(g, pid, war, unit.kind)
            || !g.is_at_war(pid, war.target_player)
        {
            return None;
        }
        let city = g
            .cities
            .get(&war.objective_city)
            .filter(|city| city.owner == war.target_player && city.hp <= 0)?;
        let objective = city.pos;
        if g.can_move(uid, objective) {
            return Some(g.apply(pid, &Action::Move { unit: uid, to: objective }).is_ok());
        }
        if g.wdist(unit.pos, objective) <= 1 {
            return Some(
                g.apply(
                    pid,
                    &Action::Attack {
                        unit: uid,
                        target: objective,
                    },
                )
                .is_ok(),
            );
        }
        Some(self.base.step_toward(g, pid, uid, objective))
    }

    /// Press the pinned objective without blinding the tactical solver. A
    /// package unit yields to ordinary combat whenever a field defender is in
    /// its immediate way; otherwise siege fires first (the unit loop already
    /// orders it before melee) and assault bodies close directly on the city.
    fn timed_war_objective_step(
        &mut self,
        g: &mut Game,
        pid: usize,
        uid: u32,
    ) -> Option<bool> {
        if let Some(finished) = self.timed_war_finisher_step(g, pid, uid) {
            return Some(finished);
        }
        let war = self
            .war_plan
            .as_ref()
            .filter(|war| war.phase == WarPhase::Exploit)?
            .clone();
        if !g.is_at_war(pid, war.target_player) {
            return None;
        }
        let city = g
            .cities
            .get(&war.objective_city)
            .filter(|city| city.owner == war.target_player)?;
        let objective = city.pos;
        let unit = g.units.get(&uid)?.clone();
        let is_body = Self::war_ready_body_kind(g, pid, &war, unit.kind);
        let is_breach = war.breach_unit == Some(unit.kind);
        if !is_body && !is_breach {
            return None;
        }
        let defender_in_the_way = g
            .nbrs(unit.pos)
            .into_iter()
            .flat_map(|position| g.units_at(position))
            .any(|other| {
                g.units.get(&other).is_some_and(|other| {
                    other.owner == war.target_player
                        && g.rules.units[other.kind].class == "military"
                })
            });
        if defender_in_the_way {
            return None;
        }

        let spec = &g.rules.units[unit.kind];
        if is_breach && spec.has_ranged_attack() {
            if g.wdist(unit.pos, objective) <= g.unit_attack_range(uid)
                && g
                    .apply(
                        pid,
                        &Action::Ranged {
                            unit: uid,
                            target: objective,
                        },
                    )
                    .is_ok()
            {
                return Some(true);
            }
            return self
                .base
                .step_toward_range(g, pid, uid, objective, g.unit_attack_range(uid).max(1))
                .then_some(true);
        }
        if is_body && g.wdist(unit.pos, objective) <= 1 {
            return g
                .apply(
                    pid,
                    &Action::Attack {
                        unit: uid,
                        target: objective,
                    },
                )
                .is_ok()
                .then_some(true);
        }
        (is_body && self.base.step_toward(g, pid, uid, objective)).then_some(true)
    }

    /// Own the diplomatic end of an appointed attack. Returning `true` means
    /// the frozen appointment consumed the war-opening decision this turn,
    /// even when it deliberately held for staging or a Formal-War timer.
    fn timed_war_opening(&mut self, g: &mut Game, pid: usize, target: usize) -> bool {
        let Some(plan) = self
            .war_plan
            .as_ref()
            .filter(|plan| plan.target_player == target)
            .cloned()
        else {
            return false;
        };
        if self.urgent_victory_threat(g, target) {
            self.record_war_abort("victory denial superseded the appointment");
            self.war_plan = None;
            self.war_status = WarPackageStatus::default();
            return false;
        }

        // Denounce during mobilization so the legal preparation clock and the
        // physical march run together. A ready casus belli is never exercised
        // until the package itself reaches Strike.
        if plan.phase != WarPhase::Strike {
            if !matches!(plan.phase, WarPhase::Research) {
                if let Some(action @ Action::Denounce { .. }) =
                    self.preferred_war_opening(g, pid, target)
                {
                    let _ = g.apply(pid, &action);
                }
            }
            return true;
        }

        let status = self.war_package_status(g, pid, &plan);
        let complete = self.timed_war_launch_ready(g, pid, &plan, &status);
        if !complete {
            // Phase and package are recomputed at turn start, but a deal,
            // upgrade failure, or other earlier action can change the board.
            // The launch gate is repeated immediately before the declaration.
            return true;
        }
        let Some(action) = self.preferred_war_opening(g, pid, target) else {
            return true;
        };
        let declares = matches!(
            action,
            Action::DeclareWar { .. } | Action::DeclareWarWithCasusBelli { .. }
        );
        // The appointment's Gold reserve is an upgrade bill, and this pass only
        // ever adds to the treasury, so it runs even while elective bilateral
        // spending is held.
        self.base.war_eve_liquidation(g, pid, &action);
        if g.apply(pid, &action).is_err() || !declares {
            return true;
        }

        if let Some(active) = self.war_plan.as_mut() {
            active.declared_turn = Some(g.turn);
            active.phase = WarPhase::Exploit;
        }
        self.war_census.declarations += 1;
        self.war_census.complete_package_declarations += 1;
        if let Some(tech_turn) = plan.tech_turn {
            let elapsed = g.turn.saturating_sub(tech_turn);
            self.war_census.tech_to_declaration_turns += elapsed;
            self.war_census
                .tech_to_declaration_samples
                .push(elapsed);
        }
        self.major_war_since = Some(g.turn);
        self.last_campaign_progress = g.turn;
        think!(self.journal(), Military, Strategy,
               "Launching the appointed attack on {}", g.players[target].civ;
               "four modern bodies and the breach package are staged at {:.2} local strength; objective city {} is pinned",
               status.local_strength_ratio, plan.objective_city);
        true
    }

    /// Return the cheapest city-state that an idle Envoy pool can take once a
    /// peace with `other` ends the Suzerain-derived war.
    ///
    /// Envoys run before diplomacy. Any pool that remains here therefore
    /// survived the ordinary positive-placement pass; this is a bridge-only
    /// way to turn that deliberately banked remainder into an immediate
    /// city-state investment. A direct city-state war does not qualify: peace
    /// with its Suzerain would not make Envoys legal there.
    fn banked_envoy_reclaim_after_peace(
        &self,
        g: &Game,
        pid: usize,
        other: usize,
        plan: &StrategicPlan,
    ) -> Option<(usize, i64)> {
        if !self.bank_envoys {
            return None;
        }
        let held = g.players.get(pid)?.envoys_free;
        let active_campaign = plan.target_player == Some(other)
            || self
                .war_plan
                .as_ref()
                .is_some_and(|war| war.target_player == other);
        let hostile_suzerain = g.players.get(other).is_some_and(|player| {
            player.alive
                && !player.is_minor
                && !player.is_barbarian
                && !player.is_free_city
        });
        if held <= 0 || active_campaign || !hostile_suzerain {
            return None;
        }

        g.players
            .iter()
            .filter(|minor| {
                minor.alive
                    && minor.is_minor
                    && !minor.is_barbarian
                    && !minor.is_free_city
                    && g.has_met(pid, minor.id)
                    && g.is_at_war(pid, minor.id)
                    && !g
                        .at_war
                        .contains(&(pid.min(minor.id), pid.max(minor.id)))
                    && g.suzerain_of(minor.id) == Some(other)
            })
            .filter_map(|minor| {
                let ours = g.envoys_at(pid, minor.id);
                let rival = g
                    .players
                    .iter()
                    .filter(|player| {
                        player.id != pid
                            && player.alive
                            && !player.is_minor
                            && !player.is_barbarian
                            && !player.is_free_city
                    })
                    .map(|player| g.envoys_at(player.id, minor.id))
                    .max()
                    .unwrap_or_default();
                let needed = (3_i64.max(rival.saturating_add(1)) - ours).max(1);
                (held >= needed).then_some((minor.id, needed))
            })
            .min_by_key(|(minor, needed)| (*needed, *minor))
    }

    fn advanced_diplomacy(&mut self, g: &mut Game, pid: usize, plan: &StrategicPlan) {
        crate::ai::choose_dedications(g, pid, self.base.w.dedication_choice);
        let incoming: Vec<u32> = g
            .pending_deals
            .iter()
            .filter(|deal| deal.to == pid && deal.expires >= g.turn)
            .map(|deal| deal.id)
            .collect();
        for deal_id in incoming {
            let Some((accept, peace, worth, from)) = g
                .pending_deals
                .iter()
                .find(|deal| deal.id == deal_id)
                .map(|deal| {
                    let worth = self.incoming_deal_value(g, pid, deal, plan);
                    let pins_objective = deal.peace
                        && self.war_plan.as_ref().is_some_and(|war| {
                            war.phase == WarPhase::Exploit
                                && war.target_player == deal.from
                                && g.cities
                                    .get(&war.objective_city)
                                    .is_some_and(|city| city.owner == deal.from)
                        });
                    (worth >= 0.0 && !pins_objective, deal.peace, worth, deal.from)
                })
            else {
                continue;
            };
            if self.journal().wants(crate::reasoning::Level::Decision) {
                let who = g
                    .players
                    .get(from)
                    .map(|player| player.civ.clone())
                    .unwrap_or_else(|| format!("player {from}"));
                let kind = if peace { "peace offer" } else { "deal" };
                think!(self.journal(), Diplomacy, Decision,
                       "{} {who}'s {kind}", if accept { "Accepting" } else { "Refusing" };
                       "worth {worth:+.0} to the {} plan", plan.strategy.as_str());
            }
            let action = if accept {
                Action::AcceptDeal { deal: deal_id }
            } else {
                Action::RejectDeal { deal: deal_id }
            };
            if g.apply(pid, &action).is_ok() && accept && peace {
                // An accepted peace offer is the negotiated equivalent of
                // MakePeace: remember the stand-down so this AI does not
                // redeclare as soon as the mandatory treaty expires.
                self.peace_until = g.turn.saturating_add(30);
                self.major_war_since = None;
            }
        }
        if let Some(session) = g.congress.clone() {
            for resolution in session.resolutions {
                if resolution.ballots.contains_key(&pid) {
                    continue;
                }
                // In an explicit victory evaluation every major shares the
                // same objective. Civ VI awards a Diplomatic Victory Point for
                // predicting any winning resolution, including International
                // Aid, so repeated participation can end a healthy science or
                // culture race with the wrong victory. Explicit non-diplomatic
                // targets abstain; adaptive agents still participate normally.
                if self.victory_target.is_some()
                    && self.victory_target != Some(VictoryTarget::Diplomacy)
                    && g.emergency_proposal_for_resolution(&resolution.id)
                        .is_none()
                {
                    continue;
                }
                if let Some(choice) = self.congress_choice(g, pid, &resolution, plan.strategy) {
                    // A ballot aimed at the empire closest to a victory is
                    // backed with everything the treasury can spare, because a
                    // losing vote is refunded in full and a right-outcome,
                    // wrong-target one at half -- an opposition that fails
                    // costs nothing. Shipped, weight keys off the voter's own
                    // plan and never off the stakes.
                    let counters_the_leader = self.congress_counter_votes
                        && self.victory_denial(g, pid).is_some_and(|(rival, _)| {
                            let (outcome, target) = Game::congress_choice_parts(&choice);
                            // Naming the rival is not opposing it: outcome A on
                            // most of these table entries is the ballot that
                            // *helps* its target. Only the shapes that carry a
                            // penalty are worth paying for.
                            target == rival.to_string()
                                && match resolution.id.as_str() {
                                    "public_relations" => outcome == "A",
                                    _ => outcome == "B",
                                }
                        });
                    let votes = if (plan.strategy == GrandStrategy::Diplomacy
                        || counters_the_leader)
                        && g.players[pid].diplomatic_favor >= 30.0
                    {
                        3
                    } else {
                        1
                    };
                    think!(self.journal(), Diplomacy, Decision,
                           "Voting {} on {}", plain(&choice), plain(&resolution.id);
                           "{votes} vote{} behind it, on the {} plan",
                           if votes == 1 { "" } else { "s" }, plan.strategy.as_str());
                    let _ = g.apply(
                        pid,
                        &Action::CongressVote {
                            resolution: Name::new(&resolution.id),
                            choice,
                            votes,
                        },
                    );
                }
            }
        }
        let denied_partner = plan.target_player.filter(|target| {
            plan.strategy == GrandStrategy::Conquest
                || g.is_at_war(pid, *target)
                || self.rival_victory_pressure(g, *target).progress >= 78
        });
        // A peace treaty is a hard block on `start_war`, so while one holds the
        // campaign target cannot be attacked and withholding trade from it buys
        // nothing — it only forfeits the value, and the chance to load the
        // rival up with contracts that the next declaration cancels. The
        // relationship denials below are deliberately left in place: an
        // Alliance or a Friendship is the one thing that would make the war
        // itself illegal when the treaty lapses.
        let denied_trade_partner =
            denied_partner.filter(|target| g.peace_treaty_until(pid, *target).is_none());
        // Quick deals can hide a Gold component inside a balanced quote. Hold
        // all elective bilateral spending while an exact upgrade bill is
        // reserved; trade resumes immediately when the appointment ends.
        if self.war_plan.is_none() {
            self.strategic_bilateral_trade(g, pid, denied_trade_partner, plan.strategy);
        }
        self.propose_strategic_alliance(g, pid, plan, denied_partner);
        // Relationship mechanics must be part of a strategic AI turn too.
        // Send one mission to the best non-hostile major, preferring the
        // Embassy that supersedes a prior Delegation. This mirrors the basic
        // controller's cadence but uses the plan-aware relationship score.
        if g.turn % 8 == pid as u32 % 8 {
            let mission = g
                .players
                .iter()
                .filter(|other| {
                    other.id != pid
                        && other.alive
                        && !other.is_minor
                        && !other.is_barbarian
                        && g.has_met(pid, other.id)
                        && !g.is_at_war(pid, other.id)
                        && Some(other.id) != denied_partner
                        && g.players[pid]
                            .grievances
                            .get(&other.id)
                            .copied()
                            .unwrap_or(0.0)
                            < 50.0
                })
                .max_by(|left, right| {
                    g.relationship_opinion(pid, left.id)
                        .total_cmp(&g.relationship_opinion(pid, right.id))
                        .then(right.id.cmp(&left.id))
                })
                .and_then(|partner| {
                    let floor = self.war_treasury_floor(g, pid);
                    let embassy_ready = g.players[pid]
                        .civics
                        .contains(&crate::name!("diplomatic_service"))
                        && g.players[pid].gold >= floor + 25.0
                        && !g
                            .diplomatic_mission_to(pid, partner.id)
                            .is_some_and(|mission| mission.kind == "embassy");
                    if embassy_ready {
                        Some(Action::SendEmbassy { player: partner.id })
                    } else if g.players[pid].gold >= floor + 10.0
                        && g.diplomatic_mission_to(pid, partner.id).is_none()
                    {
                        Some(Action::SendDelegation { player: partner.id })
                    } else {
                        None
                    }
                });
            if let Some(action) = mission {
                let _ = g.apply(pid, &action);
            }
        }
        let my_power = g.military_power(pid);
        let (major_war_fronts, combined_major_war_power) = g
            .players
            .iter()
            .filter(|player| {
                player.id != pid
                    && player.alive
                    && !player.is_minor
                    && !player.is_barbarian
                    && g.is_at_war(pid, player.id)
            })
            .fold((0usize, 0.0), |(fronts, power), player| {
                (fronts + 1, power + g.military_power(player.id))
            });
        // This is a Firaxis live-bridge repair. Native tournament controllers
        // retain their recorded single-target recovery behavior until it is
        // deliberately repriced; `war_patience` is the existing live-only
        // war-conversion gate and is set by `enable_live_bridge`.
        let overwhelmed_on_multiple_fronts = self.war_patience
            && plan.strategy == GrandStrategy::Recovery
            && major_war_fronts >= 2
            && combined_major_war_power > my_power * MULTI_FRONT_RECOVERY_PEACE_RATIO;
        let rivals: Vec<usize> = g
            .players
            .iter()
            .filter(|p| p.id != pid && p.alive && !p.is_barbarian && g.has_met(pid, p.id))
            .map(|p| p.id)
            .collect();
        self.peace_offers.clear();
        for other in &rivals {
            let appointed_objective = self.war_plan.as_ref().is_some_and(|war| {
                war.phase == WarPhase::Exploit && war.target_player == *other
            });
            let stalled = self.major_war_since.is_some_and(|started| {
                g.turn.saturating_sub(started) >= 24
                    && g.turn.saturating_sub(self.last_campaign_progress) >= 12
            });
            // `war_patience`: a stalled war against the campaign target is
            // not offered away while the empire holds an overwhelming power
            // advantage over that target. The outmatched and Recovery offer
            // triggers below keep their shape.
            let overwhelms = self.war_patience
                && plan.strategy == GrandStrategy::Conquest
                && plan.target_player == Some(*other)
                && my_power >= g.military_power(*other) * OVERWHELMING_WAR_RATIO;
            let overwhelming = overwhelms && !self.war_patience_exhausted(g);
            let fatigued = stalled && !overwhelming;
            if stalled
                && overwhelms
                && g.is_at_war(pid, *other)
                && self.journal().wants(crate::reasoning::Level::Decision)
            {
                let their_power = g.military_power(*other);
                if overwhelming {
                    think!(self.journal(), Diplomacy, Decision,
                           "Pressing the war on {}", g.players[*other].civ;
                           "the campaign has stalled, but {my_power:.0} power against \
                            their {their_power:.0} is a war to finish, not to quit");
                } else {
                    think!(self.journal(), Diplomacy, Decision,
                           "Patience with the war on {} has run out", g.players[*other].civ;
                           "{my_power:.0} power against their {their_power:.0} and still no \
                            foreign city captured in {} turns — a walkover that never lands is a tax on \
                            the economy, so peace is offered and the plan may leave Conquest",
                           g.turn.saturating_sub(self.last_campaign_progress));
                }
            }
            let peace_pending = g.pending_deals.iter().any(|deal| {
                deal.peace
                    && ((deal.from == pid && deal.to == *other)
                        || (deal.from == *other && deal.to == pid))
                    && deal.expires >= g.turn
            });
            let envoy_reclaim = self.banked_envoy_reclaim_after_peace(g, pid, *other, plan);
            if g.is_at_war(pid, *other)
                && !g.emergency_war_pair(pid, *other)
                && !g.players[*other].is_minor
                && !peace_pending
                && (my_power < g.military_power(*other) * 0.62
                    || (plan.strategy == GrandStrategy::Recovery
                        && (plan.target_player != Some(*other)
                            || overwhelmed_on_multiple_fronts))
                    || (self.religion_sues_peace
                        && plan.strategy == GrandStrategy::Religion
                        && !appointed_objective)
                    || (!appointed_objective
                        && fatigued
                        && g.player_city_ids(*other).len() > 1)
                    || envoy_reclaim.is_some())
            {
                self.peace_offers.insert(*other);
                if self.journal().wants(crate::reasoning::Level::Decision) {
                    let their_power = g.military_power(*other);
                    let because = if let Some((minor, needed)) = envoy_reclaim {
                        format!(
                            "the plan has no campaign there and {needed} banked Envoy{} can immediately take {} after the Suzerain war ends",
                            if needed == 1 { "" } else { "s" },
                            g.players[minor].civ
                        )
                    } else if my_power < their_power * 0.62 {
                        "outmatched".to_string()
                    } else if overwhelmed_on_multiple_fronts {
                        "multiple major fronts overwhelm the recovery army".to_string()
                    } else if plan.strategy == GrandStrategy::Recovery {
                        "this is not the war the recovery plan is fighting".to_string()
                    } else if self.religion_sues_peace
                        && plan.strategy == GrandStrategy::Religion
                    {
                        "the religion plan cannot spread into a war".to_string()
                    } else {
                        "the war has stalled".to_string()
                    };
                    think!(self.journal(), Diplomacy, Decision,
                           "Offering peace to {}", g.players[*other].civ;
                           "{because}: {my_power:.0} power against their {their_power:.0}");
                }
                // Peace between majors is bilateral. The former direct
                // MakePeace let an outmatched defender terminate a winning
                // invasion on the first legal turn, even when the conqueror
                // valued the campaign. Keep fighting until the recipient's
                // normal deal valuation accepts this offer.
                let _ = g.apply(
                    pid,
                    &Action::ProposeDeal {
                        player: *other,
                        give_gold: 0.0,
                        request_gold: 0.0,
                        open_borders: false,
                        friendship: false,
                        peace: true,
                        alliance: None,
                    },
                );
            }
        }
        let major_wars = rivals
            .iter()
            .filter(|o| !g.players[**o].is_minor && g.is_at_war(pid, **o))
            .count();
        if major_wars > 0
            && matches!(
                plan.strategy,
                GrandStrategy::Conquest | GrandStrategy::Recovery
            )
        {
            self.base.levy_city_state_military(g, pid, true);
        }
        let Some(target) = plan.target_player else {
            return;
        };
        if self.timed_war_opening(g, pid, target) {
            return;
        }
        // Timed attacks already refuse an appointment that cannot finish
        // before this same scaled reserve. The direct victory-denial fallback
        // used to bypass it and could declare in the final turns with no
        // plausible path to a capture. Keep that late-game guard live-only so
        // the frozen tournament controller retains its recorded behaviour.
        if self.endgame_war_runway {
            let reserve = g.standard_duration(TIMED_WAR_ENDGAME_RESERVE);
            if g.turn.saturating_add(reserve) >= g.max_turns {
                if self.journal().wants(crate::reasoning::Level::Strategy) {
                    let runway = g.max_turns.saturating_sub(g.turn);
                    think!(self.journal(), Military, Strategy,
                           "Holding off war with {}", g.players[target].civ;
                           "{runway} turns remain, at or below the {reserve}-turn campaign reserve for a fresh declaration");
                }
                return;
            }
        }
        let emergency_target = g
            .emergency_objective(pid)
            .is_some_and(|objective| objective.target == target);
        // An ancient rush is the same decision taken earlier and on smaller
        // numbers, so it waives the two gates that are calendar rather than
        // condition — the turn-35 floor and the second city — and keeps every
        // gate that is about the war itself. It is still subject to
        // `close_enough`, to a staged stack, and to the peace deadline.
        let rushing = self
            .early_rush_victim(g, pid)
            .is_some_and(|(victim, _)| victim == target);
        if plan.strategy != GrandStrategy::Conquest
            || major_wars > 0
            || (!rushing && g.turn < 35)
            || g.turn < self.peace_until
            || (!rushing && g.player_city_ids(pid).len() < 2)
            || g.is_at_war(pid, target)
            || (!emergency_target && !self.campaign_target_legal(g, pid, target))
        {
            return;
        }
        let target_power = g.military_power(target);
        let close_enough = plan
            .target_city
            .and_then(|cid| g.cities.get(&cid))
            .is_some_and(|target_city| {
                g.player_city_ids(pid)
                    .iter()
                    .any(|cid| g.wdist(g.cities[cid].pos, target_city.pos) <= 18)
            });
        let committed_domination = self.victory_target == Some(VictoryTarget::Domination);
        // An army that has reached the enemy border is the only practical
        // answer to a rival's terminal clock.  Keep the normal power margin
        // for elective wars, but do not discard a staged denial force merely
        // because it is outnumbered: when the threat is already at the same
        // threshold that authorizes a Surprise War, waiting for superiority
        // guarantees that the rival gets the final uncontested turns.
        let urgent_denial = self.urgent_victory_threat(g, target);
        // `my_power > target_power * 1.32 + 12` is an empire-wide comparison,
        // and at turn 40 both empires are three or four units, so the `+ 12`
        // alone can outweigh the whole ratio. What decides an ancient siege is
        // not the empires' totals but how many takers are standing at the
        // objective, which is exactly what `early_rush_stack_ready` counts.
        let ready = urgent_denial
            || if rushing {
                plan.target_city
                    .and_then(|city| g.cities.get(&city))
                    .is_some_and(|city| self.early_rush_stack_ready(g, pid, target, city.id))
            } else if committed_domination {
                my_power >= target_power * 0.85 && my_power >= 30.0
            } else {
                my_power > target_power * 1.32 + 12.0
            };
        let staged = plan
            .target_city
            .and_then(|city| g.cities.get(&city))
            .is_some_and(|city| {
                self.campaign_staged_for_war(
                    g,
                    pid,
                    target,
                    city.pos,
                    // A staged rush stack is already at the objective and has
                    // counted its own takers, so hold it to the domination
                    // ratio rather than the elective-war one.
                    committed_domination || rushing,
                )
            });
        if close_enough && ready && staged {
            if let Some(action) = self.preferred_war_opening(g, pid, target) {
                if self.journal().wants(crate::reasoning::Level::Strategy) {
                    let casus = match &action {
                        Action::DeclareWarWithCasusBelli { casus_belli, .. } => {
                            format!(" under a {} casus belli", plain(casus_belli))
                        }
                        _ => String::new(),
                    };
                    think!(self.journal(), Military, Strategy,
                           "Declaring war on {}", g.players[target].civ;
                           "{my_power:.0} power against their {target_power:.0}, the army is \
                            staged within reach of the first objective{casus}{}",
                           if urgent_denial {
                               ", and they are close enough to winning that waiting loses it"
                           } else {
                               ""
                           });
                }
                self.base.war_eve_liquidation(g, pid, &action);
                let _ = g.apply(pid, &action);
            }
        } else if self.journal().wants(crate::reasoning::Level::Detail) {
            // Not opening a war is a decision too, and the observer cannot see
            // it any other way: an army that sits still for thirty turns looks
            // identical to one with no plan.
            let blocker = if !close_enough {
                "no city of theirs is within 18 tiles of one of mine"
            } else if !ready {
                "the army is not strong enough yet"
            } else {
                "the army has not finished staging"
            };
            think!(self.journal(), Military, Detail,
                   "Holding off war with {}", g.players[target].civ;
                   "{blocker}; {my_power:.0} power against their {target_power:.0}");
        }
    }

    /// The live bank is a reserve for discovery, not an unlimited vault. Keep
    /// its normal floor small, but preserve the exact price of the cheapest
    /// city-state that a negotiated Suzerain peace could immediately reclaim.
    ///
    /// Production and Envoy allocation run before diplomacy, so the pool must
    /// retain the option until that pass decides whether the peace is
    /// acceptable. Keep this check local: the recently shipped peace helper is
    /// deliberately left intact rather than mechanically refactored here.
    fn banked_envoy_liquidity_reserve(&self, g: &Game, pid: usize) -> i64 {
        if !self.bank_envoys {
            return 0;
        }
        // A campaign that names the hostile Suzerain deliberately keeps that
        // war: `banked_envoy_reclaim_after_peace` will not offer it away just
        // to reclaim the city-state. Such a minor cannot justify holding more
        // than the ordinary discovery reserve. Keep this eligibility check
        // local, alongside the other reserve-specific checks, rather than
        // weakening the campaign-protection contract in the peace helper.
        let campaign_owns_suzerain = |suzerain| {
            self.plan
                .as_ref()
                .is_some_and(|plan| plan.target_player == Some(suzerain))
                || self
                    .war_plan
                    .as_ref()
                    .is_some_and(|war| war.target_player == suzerain)
        };
        let reclaim = g
            .players
            .iter()
            .filter_map(|minor| {
                if !minor.alive
                    || !minor.is_minor
                    || minor.is_barbarian
                    || minor.is_free_city
                    || !g.has_met(pid, minor.id)
                    || !g.is_at_war(pid, minor.id)
                    || g
                        .at_war
                        .contains(&(pid.min(minor.id), pid.max(minor.id)))
                {
                    return None;
                }
                let suzerain = g.suzerain_of(minor.id)?;
                let owner = g.players.get(suzerain)?;
                if suzerain == pid
                    || !owner.alive
                    || owner.is_minor
                    || owner.is_barbarian
                    || owner.is_free_city
                    || campaign_owns_suzerain(suzerain)
                {
                    return None;
                }
                let ours = g.envoys_at(pid, minor.id);
                let rival = g
                    .players
                    .iter()
                    .filter(|player| {
                        player.id != pid
                            && player.alive
                            && !player.is_minor
                            && !player.is_barbarian
                            && !player.is_free_city
                    })
                    .map(|player| g.envoys_at(player.id, minor.id))
                    .max()
                    .unwrap_or_default();
                Some((3_i64.max(rival.saturating_add(1)) - ours).max(1))
            })
            .min()
            .unwrap_or_default();
        BANKED_ENVOY_LIQUIDITY_RESERVE.max(reclaim)
    }

    fn advanced_envoys(
        &self,
        g: &mut Game,
        pid: usize,
        strategy: GrandStrategy,
        denied_rival: Option<usize>,
    ) {
        let liquidity_reserve = self.banked_envoy_liquidity_reserve(g, pid);
        while g.players[pid].envoys_free > 0 {
            let target = g
                .players
                .iter()
                .filter(|minor| g.can_send_envoy(pid, minor.id))
                .map(|minor| {
                    let mine = g.envoys_at(pid, minor.id);
                    let rival = g
                        .players
                        .iter()
                        .filter(|p| !p.is_minor && !p.is_barbarian && p.id != pid)
                        .map(|p| g.envoys_at(p.id, minor.id))
                        .max()
                        .unwrap_or(0);
                    let needed = (3_i64.max(rival + 1) - mine).max(1);
                    let kind = g.cs_type(&minor.civ);
                    let alignment = match (strategy, kind) {
                        (GrandStrategy::Science, "scientific") => 10,
                        (GrandStrategy::Culture, "cultural") => 10,
                        (GrandStrategy::Religion, "religious") => 12,
                        (GrandStrategy::Diplomacy, _) => 10,
                        (GrandStrategy::Conquest, "militaristic") => 10,
                        (GrandStrategy::Expansion, "trade") => 8,
                        (_, "trade") => 4,
                        _ => 2,
                    };
                    let unique_alignment = match (strategy, minor.civ.as_str()) {
                        (GrandStrategy::Science, "Geneva") => 14,
                        (GrandStrategy::Science | GrandStrategy::Conquest, "Hattusa") => 11,
                        (GrandStrategy::Science | GrandStrategy::Culture, "Stockholm") => 10,
                        (GrandStrategy::Conquest, "Kabul") => 14,
                        (GrandStrategy::Conquest | GrandStrategy::Expansion, "Carthage") => 10,
                        (GrandStrategy::Expansion | GrandStrategy::Recovery, "Mohenjo-Daro") => 11,
                        (GrandStrategy::Religion, "Yerevan") => 15,
                        (GrandStrategy::Religion | GrandStrategy::Culture, "Kandy") => 12,
                        (GrandStrategy::Expansion | GrandStrategy::Recovery, "Zanzibar") => 11,
                        (_, "Zanzibar") if g.players[pid].civ == "Aztec" => 12,
                        (
                            GrandStrategy::Science
                            | GrandStrategy::Culture
                            | GrandStrategy::Conquest
                            | GrandStrategy::Expansion,
                            "Auckland",
                        ) => 9,
                        (
                            GrandStrategy::Religion
                            | GrandStrategy::Conquest
                            | GrandStrategy::Recovery,
                            "Valletta",
                        ) => 13,
                        (GrandStrategy::Culture, "Vilnius") => 14,
                        (_, "Stockholm" | "Zanzibar" | "Auckland" | "Valletta") => 5,
                        _ => 2,
                    };
                    let already_secure = g.suzerain_of(minor.id) == Some(pid) && mine > rival + 1;
                    let overfunded_uncontested =
                        self.bank_envoys && already_secure && mine >= 6;
                    let shared_from_partner = g.suzerain_of(minor.id).is_some_and(|leader| {
                        leader != pid
                            && g.alliance_with(pid, leader).is_some_and(|alliance| {
                                alliance.kind == "economic" && alliance.level >= 3
                            })
                    });
                    let type_bonus_value = g
                        .next_envoy_type_bonus(pid, minor.id)
                        .map(|(envoys, yields)| {
                            (self.yield_value(yields, strategy) * 14.0 / envoys as f64).round()
                                as i64
                        })
                        .unwrap_or(0);
                    let denial = denied_rival
                        .is_some_and(|leader| g.suzerain_of(minor.id) == Some(leader))
                        as i64
                        * 140;
                    // The amortised type bonus dips at exactly one envoy: a
                    // fresh city-state buys its level-1 yields for a single
                    // envoy, while one already opened needs two more before it
                    // pays again. With the suzerainty itself priced at zero,
                    // the cheapest step is always to open a city-state the seat
                    // will never finish -- which is what a 20.5-envoy, 0.66-
                    // suzerainty census looks like from the inside. This term
                    // rises as the seat closes on the floor (180, then 90, then
                    // 180 at one away) instead of falling.
                    let suzerain_prize = if self.price_the_suzerainty
                        && g.suzerain_of(minor.id) != Some(pid)
                    {
                        SUZERAIN_PRIZE / needed
                    } else {
                        0
                    };
                    let score = (alignment + unique_alignment) * 10
                        + type_bonus_value
                        + denial
                        + suzerain_prize
                        - needed * 7
                        - if overfunded_uncontested {
                            UNCONTESTED_POST_TIER_ENVOY_PENALTY
                        } else {
                            already_secure as i64 * 80
                        }
                        - shared_from_partner as i64 * 300;
                    (
                        score,
                        std::cmp::Reverse(needed),
                        std::cmp::Reverse(minor.id),
                        minor.id,
                    )
                })
                .max()
                .map(|(score, _, _, id)| (id, score));
            let Some((target, score)) = target else { break };
            // See `bank_envoys`: retain the bounded discovery/reclaim reserve
            // once nothing on the board is worth an Envoy. Any surplus has a
            // productive opportunity cost, so it reinforces the best available
            // city-state instead of accumulating indefinitely.
            if self.bank_envoys
                && score < 0
                && g.players[pid].envoys_free <= liquidity_reserve
            {
                think!(self.journal(), Diplomacy, Decision,
                       "Banking {} envoy{}", g.players[pid].envoys_free,
                       if g.players[pid].envoys_free == 1 { "" } else { "s" };
                       "the best placement left is {} at {score}: every met city-state is \
                        either securely ours past its paying tier or contested beyond its \
                        worth, so this {liquidity_reserve}-Envoy reserve stays ready for the \
                        next discovery or immediate reclaim",
                       g.players[target].civ);
                break;
            }
            if self.journal().wants(crate::reasoning::Level::Decision) {
                let mine = g.envoys_at(pid, target) + 1;
                let suzerain = g
                    .suzerain_of(target)
                    .and_then(|leader| g.players.get(leader))
                    .map(|leader| leader.civ.clone());
                let standing = match &suzerain {
                    Some(civ) if *civ == g.players[pid].civ => "already its Suzerain".to_string(),
                    Some(civ) => format!("{civ} holds it"),
                    None => "nobody is its Suzerain".to_string(),
                };
                think!(self.journal(), Diplomacy, Decision,
                       "Sending an envoy to {}", g.players[target].civ;
                       "a {} city-state worth {score} to the {} plan; {standing}, \
                        this makes {mine} envoy{}",
                       g.cs_type(&g.players[target].civ), strategy.as_str(),
                       if mine == 1 { "" } else { "s" });
            }
            if g.apply(pid, &Action::SendEnvoy { player: target }).is_err() {
                break;
            }
        }
    }

    /// Buy out a close Great Person race only when the person advances the
    /// active plan and the purchase leaves a useful operating reserve. Normal
    /// GPP recruitment is automatic at turn start; this phase is deliberately
    /// limited to one tempo purchase per turn.
    fn advanced_great_people(&self, g: &mut Game, pid: usize, strategy: GrandStrategy) {
        let city_count = g.player_city_ids(pid).len() as f64;
        let gold_reserve = (150.0 + 50.0 * city_count).max(self.war_treasury_floor(g, pid));
        let faith_reserve = match strategy {
            GrandStrategy::Religion => 250.0,
            GrandStrategy::Culture if g.players[pid].civics.contains(&crate::name!("cold_war")) => 700.0,
            _ => 100.0,
        };
        let mut candidates = Vec::new();
        for kind in [
            "scientist",
            "engineer",
            "writer",
            "artist",
            "musician",
            "merchant",
            "general",
            "admiral",
            "prophet",
        ] {
            let Some((_, person)) = g.current_great_person(kind) else {
                continue;
            };
            // The local named roster is only a fallback model. When the
            // Firaxis mirror names its current screen, patronage can target
            // exactly those classes and must leave every other class alone.
            if !g.great_person_class_offered_now(pid, kind) {
                continue;
            }
            if !g.can_activate_current_great_person(pid, kind) {
                continue;
            }
            // ★★★★ A CLASS THE HOST HAS RUN OUT OF CANNOT BE BOUGHT. Run
            // civvis-20260816T233226Z ended with 1,999 Faith in the bank and
            // 26 `gp_class_not_offered` refusals: from t227 the seat asked to
            // buy out the Artist race four turns running (480/428/375/322
            // Faith) and the Merchant race at t251, while the export's
            // `great_person_exhausted` listed both — every named Artist and
            // Merchant on the map was already claimed — and offered three
            // Musicians at 660 that were never asked for. CIVVIS's own roster
            // still had Artists left, so `current_great_person` said yes; the
            // host's timeline is the authority on a mirrored seat, and
            // `great_person_class_earnable` already reads it. Native boards
            // carry no such list and are unchanged.
            if g.players[pid].live_great_person_exhausted.is_some()
                && !g.great_person_class_earnable(pid, kind)
            {
                continue;
            }
            let points = g.players[pid].gpp.get(kind).copied().unwrap_or(0.0);
            let cost = g.gp_cost(pid, kind);
            let missing = (cost - points).max(0.0);
            if missing <= f64::EPSILON {
                continue;
            }
            let affinity = match (strategy, kind) {
                (GrandStrategy::Science, "scientist")
                | (GrandStrategy::Culture, "writer" | "artist" | "musician")
                | (GrandStrategy::Diplomacy, "merchant")
                | (GrandStrategy::Conquest, "general" | "admiral") => 500.0,
                (GrandStrategy::Religion, "prophet") if g.players[pid].religion.is_none() => 650.0,
                (GrandStrategy::Expansion | GrandStrategy::Recovery, "engineer" | "merchant")
                | (GrandStrategy::Science | GrandStrategy::Culture, "engineer") => 300.0,
                (_, "prophet") if g.players[pid].religion.is_some() => -1_000.0,
                _ => 100.0,
            };
            let close_fraction = missing / cost.max(1.0);
            // See `tally_great_people`: on the tally seat any Great Person the
            // bank can carry is worth its five points; the price still rises
            // with the missing points, so a near recruit stays the better buy.
            let limit = if self.tally_great_people {
                1.0
            } else if affinity >= 500.0 {
                0.40
            } else {
                0.15
            };
            if affinity < 0.0 || close_fraction > limit {
                continue;
            }
            let effect_value = person.effects.values().sum::<f64>() * 12.0;
            for (currency, bank, reserve) in [
                ("gold", g.players[pid].gold, gold_reserve),
                ("faith", g.players[pid].faith, faith_reserve),
            ] {
                let Some(price) = g.great_person_patronage_price(pid, kind, currency) else {
                    continue;
                };
                if bank + f64::EPSILON < price + reserve {
                    continue;
                }
                let opportunity = price / (bank - reserve).max(1.0);
                let score = (affinity + effect_value) * (1.0 - opportunity.min(0.95));
                candidates.push((
                    score,
                    std::cmp::Reverse((kind.to_string(), currency.to_string())),
                    Action::PatronizeGreatPerson {
                        kind: kind.to_string(),
                        currency: currency.to_string(),
                    },
                ));
            }
        }
        if let Some((score, _, action)) = candidates.into_iter().max_by(|left, right| {
            left.0
                .partial_cmp(&right.0)
                .unwrap_or(std::cmp::Ordering::Equal)
                .then_with(|| left.1.cmp(&right.1))
        }) {
            if let Action::PatronizeGreatPerson { kind, currency } = &action {
                let price = g
                    .great_person_patronage_price(pid, kind, currency)
                    .unwrap_or(0.0);
                think!(self.journal(), Economy, Decision, "Buying out the {} race", plain(kind);
                       "{price:.0} {currency}, worth {score:.0} to the {} plan",
                       strategy.as_str());
            }
            let _ = g.apply(pid, &action);
        }
    }

    /// Enumerate only purchase actions, distributing independent city menus
    /// across worker-private worlds. The game helper returns the PURCHASES
    /// and later EMPIRE contributions separately; flattening each phase in
    /// city order exactly matches the filtered stock legal-action order.
    fn legal_purchase_actions(&self, g: &Game, pid: usize) -> Vec<Action> {
        let city_ids = g.purchase_action_city_ids(pid);
        let Some(pool) = self.work_pool.as_ref() else {
            // Interactive and frozen-control agents retain the literal stock
            // enumeration path. The specialized projection is a headless
            // simulation optimization, gated by the attached work pool.
            return g
                .legal_actions_within(
                    pid,
                    ActionFamilies::PURCHASES | ActionFamilies::EMPIRE,
                )
                .into_iter()
                .filter(|action| {
                    matches!(
                        action,
                        Action::Buy { .. }
                            | Action::BuyBuilding { .. }
                            | Action::BuyDistrict { .. }
                            | Action::BuyPlot { .. }
                    )
                })
                .collect();
        };
        if pool.threads() == 1 || city_ids.len() < 2 {
            return g.legal_purchase_actions(pid);
        }

        let city_ids = Arc::new(city_ids);
        let active = pool
            .threads()
            .min(city_ids.len())
            .min(PURCHASE_MENU_MAX_WORKERS);
        let states = (0..active)
            .map(|_| g.speculative_clone())
            .collect::<Vec<_>>();
        let per_city = pool.map_stateful_limited(
            city_ids.len(),
            PURCHASE_MENU_MAX_WORKERS,
            states,
            move |game, indices| {
                let _memo = game.query_memo();
                indices
                    .map(|index| {
                        (
                            index,
                            game.legal_purchase_actions_for_city(pid, city_ids[index]),
                        )
                    })
                    .collect()
            },
        );
        let mut actions = Vec::new();
        actions.extend(
            per_city
                .iter()
                .flat_map(|(purchases, _)| purchases.iter().cloned()),
        );
        actions.extend(
            per_city
                .into_iter()
                .flat_map(|(_, empire)| empire.into_iter()),
        );
        actions
    }

    /// Spend Gold on the one thing that can still keep a besieged city alive
    /// before upgrades, patronage, or the ordinary strategic purchaser can
    /// compare it with development.
    ///
    /// The live garrison doctrine already identifies the exact immediate
    /// defense — Walls first, otherwise a land melee defender — and reclaims
    /// an unsafe production queue for it.  A completed purchase is faster
    /// than that queue.  In the live Rome siege at turn 136, however, the
    /// generic Gold evaluator chose a Builder in the capital at 171/200 city
    /// damage; the Pike and Shot it had just queued needed nine turns.  That
    /// is an emergency, not a normal reserve decision.
    ///
    /// This deliberately shares `garrison_under_fire` with the production
    /// response.  Frozen controllers leave that live-only flag false, so they
    /// return before enumerating a city, a threat, or a purchase menu.
    fn emergency_city_defense_purchase(
        &self,
        g: &mut Game,
        pid: usize,
        plan: &StrategicPlan,
    ) -> bool {
        if !self.base.garrison_under_fire {
            return false;
        }

        let mut candidates: Vec<(
            (i32, i32, i32, std::cmp::Reverse<u32>),
            u32,
            String,
            Item,
        )> = Vec::new();
        for city_id in g.player_city_ids(pid) {
            let Some(defence) = self.base.besieged_city_item(g, pid, city_id) else {
                continue;
            };
            let city = &g.cities[&city_id];
            let city_damage = CITY_MAX_HP.saturating_sub(city.hp);
            let wall_damage = g.city_max_wall_hp(city).saturating_sub(city.wall_hp);
            let combined_damage = city_damage.saturating_add(wall_damage);
            // A city already losing health is the first rescue; a known
            // threatened city then breaks ties ahead of a merely nearby raid.
            let rank = (
                city_damage,
                combined_damage,
                i32::from(plan.threatened_city == Some(city_id)),
                std::cmp::Reverse(city_id),
            );
            candidates.push((rank, city_id, city.name.clone(), defence));
        }

        if candidates.is_empty() {
            return false;
        }
        candidates.sort_by(|left, right| right.0.cmp(&left.0));
        let purchases = self.legal_purchase_actions(g, pid);
        let Some((rank, action, city_name, defence)) = candidates.into_iter().find_map(
            |(rank, city_id, city_name, defence)| {
                let action = purchases
                    .iter()
                    .find(|action| match (action, &defence) {
                        (
                            Action::Buy {
                                city,
                                unit,
                                formation,
                                currency,
                            },
                            Item::Unit { unit: wanted },
                        ) => {
                            *city == city_id
                                && *formation == 0
                                && currency == "gold"
                                && unit == wanted
                        }
                        (
                            Action::BuyBuilding {
                                city,
                                building,
                                currency,
                            },
                            Item::Building { building: wanted },
                        ) => *city == city_id && currency == "gold" && building == wanted,
                        _ => false,
                    })
                    .cloned()?;
                Some((rank, action, city_name, defence))
            },
        )
        else {
            return false;
        };
        let (city_damage, combined_damage, _, _) = rank;
        let before = g.players[pid].gold;
        if g.apply(pid, &action).is_err() {
            return false;
        }
        if self.journal().wants(crate::reasoning::Level::Decision) {
            let spent = (before - g.players[pid].gold).max(0.0);
            think!(self.journal(), Economy, Decision,
                "Buying emergency {} for {}", Self::plain_item(&defence), city_name;
                "{spent:.0} Gold defends a city with {city_damage} city and {combined_damage} combined health missing before ordinary purchases");
        }
        true
    }

    /// Convert a deep treasury into immediate tempo gains. Candidate
    /// units, buildings, and Governor-enabled districts reuse the strategic
    /// production evaluator, but are scored at their undiscounted positional
    /// value because a purchase completes now. A strategy-sensitive reserve
    /// protects Great Person patronage, Great Work deals, upgrades, and
    /// emergency reinforcement instead of treating all affordable actions as
    /// equally spendable. Late empires can earn more Gold each turn than one
    /// purchase consumes, so buy a bounded series and recompute needs after
    /// every item instead of carrying an ever-growing inert treasury.
    fn advanced_gold_spending(&self, g: &mut Game, pid: usize, plan: &StrategicPlan) -> bool {
        if self.emergency_city_defense_purchase(g, pid, plan) {
            return true;
        }
        let city_count = g.player_city_ids(pid).len();
        let reserve = match plan.strategy {
            GrandStrategy::Diplomacy | GrandStrategy::Culture => {
                300.0 + 75.0 * city_count as f64
            }
            GrandStrategy::Expansion => 250.0 + 75.0 * city_count as f64,
            GrandStrategy::Science => 250.0 + 50.0 * city_count as f64,
            GrandStrategy::Religion => 150.0 + 50.0 * city_count as f64,
            GrandStrategy::Conquest | GrandStrategy::Recovery => {
                75.0 + 25.0 * city_count as f64
            }
        }
        .max(self.war_treasury_floor(g, pid));
        let purchase_limit = city_count.clamp(1, 4);
        let unit_purchase_limit = if g.players[pid].gold > reserve + 1_000.0 {
            2
        } else {
            1
        };
        let mut purchased = false;
        let mut purchased_units = 0;
        for _ in 0..purchase_limit {
            let bank = g.players[pid].gold;
            let counts = self.counts(g, pid);
            let mut candidates = Vec::new();
            let mut plot_options = Vec::new();
            let mut purchase_options = Vec::new();
            // Every candidate asks its city for the same yields, twice — once
            // here and once inside `production_value`. The guard borrows the
            // game immutably, so those answers cannot go stale before it is
            // dropped below.
            let memo = g.query_memo();
            for action in self.legal_purchase_actions(g, pid) {
                if let Action::BuyPlot {
                    city: _,
                    pos,
                    cost,
                } = &action
                {
                    if bank + f64::EPSILON < reserve + 200.0 + cost {
                        continue;
                    }
                    let tile = &g.map.tiles[pos];
                    let resource = tile
                        .resource
                        .as_ref()
                        .and_then(|name| g.rules.resources.get(name))
                        .filter(|spec| {
                            spec.tech
                                .as_ref()
                                .is_none_or(|tech| g.players[pid].techs.contains(tech))
                                && spec
                                    .civic
                                    .as_ref()
                                    .is_none_or(|civic| g.players[pid].civics.contains(civic))
                        });
                    let mut visible_tile = tile.clone();
                    if tile.resource.is_some() && resource.is_none() {
                        visible_tile.resource = None;
                    }
                    let yields = self
                        .yield_value(g.rules.tile_yields(&visible_tile), plan.strategy)
                        * 24.0;
                    let resource = resource
                        .map(|spec| match spec.class.as_str() {
                            "luxury" => 260.0,
                            "strategic" => 230.0,
                            "bonus" => 70.0,
                            _ => 0.0,
                        })
                        .unwrap_or(0.0);
                    let wonder = tile
                        .feature
                        .as_ref()
                        .and_then(|name| g.rules.features.get(name))
                        .is_some_and(|feature| feature.natural_wonder) as u8 as f64
                        * 320.0;
                    let base_score = yields + resource + wonder - cost * 0.70;
                    // Use adjacency as a cheap shortlist signal. Exact site
                    // legality and full production value are evaluated below
                    // for only the strongest four plots, avoiding a full game
                    // clone for every border hex in a large empire.
                    let adjacency_hint = g
                        .rules
                        .districts
                        .iter()
                        .filter(|(_, spec)| {
                            spec.buildable
                                && spec
                                    .unique_to
                                    .as_ref()
                                    .is_none_or(|civ| civ == &g.players[pid].civ)
                                && spec
                                    .tech
                                    .as_ref()
                                    .is_none_or(|tech| g.players[pid].techs.contains(tech))
                                && spec
                                    .civic
                                    .as_ref()
                                    .is_none_or(|civic| g.players[pid].civics.contains(civic))
                        })
                        .map(|(district, _)| {
                            self.yield_value(g.district_yields(district, *pos), plan.strategy)
                        })
                        .fold(0.0, f64::max)
                        * 10.0;
                    plot_options.push((
                        base_score + adjacency_hint,
                        base_score,
                        std::cmp::Reverse(format!("{action:?}")),
                        action,
                    ));
                    continue;
                }
                let (city, item, currency) = match &action {
                    Action::Buy {
                        city,
                        unit,
                        formation,
                        currency,
                    } => (
                        *city,
                        if *formation == 0 {
                            Item::Unit { unit: *unit }
                        } else {
                            Item::Formation {
                                unit: *unit,
                                formation: *formation,
                            }
                        },
                        currency.as_str(),
                    ),
                    Action::BuyBuilding {
                        city,
                        building,
                        currency,
                    } => (
                        *city,
                        Item::Building {
                            building: *building,
                        },
                        currency.as_str(),
                    ),
                    Action::BuyDistrict {
                        city,
                        district,
                        pos,
                        currency,
                    } => (
                        *city,
                        Item::District {
                            district: *district,
                            pos: *pos,
                        },
                        currency.as_str(),
                    ),
                    _ => continue,
                };
                if currency != "gold" {
                    continue;
                }
                if purchased_units >= unit_purchase_limit && matches!(&item, Item::Unit { .. }) {
                    continue;
                }
                purchase_options.push((action, city, item));
            }
            let score_context = PurchaseScoreContext {
                g,
                pid,
                plan,
                counts: &counts,
                bank,
                reserve,
            };
            let purchase_scores = self.gold_purchase_scores(score_context, &purchase_options);
            for ((action, _, _), score) in purchase_options.into_iter().zip(purchase_scores) {
                if let Some(score) = score {
                    candidates.push((score, std::cmp::Reverse(format!("{action:?}")), action));
                }
            }
            // A plot is a surplus purchase. Concrete units, buildings and
            // Governor districts already proved an immediate strategic need,
            // so they keep priority whenever one clears the score floor.
            if candidates.is_empty() {
                plot_options.sort_by(|left, right| {
                    right
                        .0
                        .total_cmp(&left.0)
                        .then_with(|| left.2.cmp(&right.2))
                });
                plot_options.truncate(4);
                let plot_scores = self.gold_plot_scores(score_context, &plot_options);
                for ((_, _, _, action), score) in plot_options.into_iter().zip(plot_scores) {
                    if let Some(score) = score {
                        candidates.push((
                            score,
                            std::cmp::Reverse(format!("{action:?}")),
                            action,
                        ));
                    }
                }
            }
            drop(memo);
            let best = candidates.into_iter().max_by(|left, right| {
                left.0
                    .total_cmp(&right.0)
                    .then_with(|| left.1.cmp(&right.1))
            });
            let Some((score, _, action)) = best else { break };
            let is_unit = matches!(action, Action::Buy { .. });
            let before = g.players[pid].gold;
            if g.apply(pid, &action).is_err() {
                break;
            }
            if self.journal().wants(crate::reasoning::Level::Decision) {
                let spent = (before - g.players[pid].gold).max(0.0);
                let (city, what) = match &action {
                    Action::Buy { city, unit, formation, .. } => (
                        Some(*city),
                        if *formation == 0 {
                            plain(unit)
                        } else {
                            format!("a formation of {}", plain(unit))
                        },
                    ),
                    Action::BuyBuilding { city, building, .. } => (Some(*city), plain(building)),
                    Action::BuyDistrict { city, district, .. } => {
                        (Some(*city), format!("a {} district", plain(district)))
                    }
                    Action::BuyPlot { city, pos, .. } => {
                        (Some(*city), format!("the tile at {pos:?}"))
                    }
                    _ => (None, "something".to_string()),
                };
                let where_ = city
                    .and_then(|id| g.cities.get(&id))
                    .map(|city| city.name.clone())
                    .unwrap_or_else(|| "the empire".to_string());
                think!(self.journal(), Economy, Decision, "Buying {what} for {where_}";
                       "{spent:.0} Gold, worth {score:.0} to the {} plan; {:.0} left \
                        above a reserve of {reserve:.0}",
                       plan.strategy.as_str(), g.players[pid].gold);
            }
            purchased = true;
            purchased_units += is_unit as usize;
        }
        purchased
    }

    fn gold_purchase_score(
        &self,
        context: PurchaseScoreContext<'_>,
        action: &Action,
        city: u32,
        item: &Item,
    ) -> Option<f64> {
        let PurchaseScoreContext {
            g,
            pid,
            plan,
            counts,
            bank,
            reserve,
        } = context;
        let production = g.city_yields(city).production.max(1.0);
        let turns = g.item_remaining_cost_for_city(pid, city, item) / production;
        let production_score = self.production_value(g, pid, city, item, plan, counts);
        if production_score <= -1_000.0 {
            return None;
        }
        // Long production time can make even a strategically redundant unit
        // clear the combined purchase score below. Require the underlying
        // need itself to be meaningful before converting a deep treasury into
        // more bodies on the map.
        if matches!(item, Item::Unit { .. }) && production_score < 120.0 {
            return None;
        }
        let mut after = g.speculative_clone();
        after.apply(pid, action).ok()?;
        let cost = (bank - after.players[pid].gold).max(0.0);
        if after.players[pid].gold + f64::EPSILON < reserve {
            return None;
        }
        let positional = production_score * (7.0 + turns.max(1.0));
        let score = positional + turns.clamp(0.0, 20.0) * 6.0 - cost * 0.30;
        (score >= 120.0).then_some(score)
    }

    fn gold_purchase_scores(
        &self,
        context: PurchaseScoreContext<'_>,
        options: &[(Action, u32, Item)],
    ) -> Vec<Option<f64>> {
        options
            .iter()
            .map(|(action, city, item)| {
                self.gold_purchase_score(context, action, *city, item)
            })
            .collect()
    }

    fn gold_plot_score(
        &self,
        context: PurchaseScoreContext<'_>,
        action: &Action,
        base_score: f64,
    ) -> Option<f64> {
        let PurchaseScoreContext {
            g,
            pid,
            plan,
            counts,
            reserve,
            ..
        } = context;
        let Action::BuyPlot { city, pos, .. } = action else {
            unreachable!("plot shortlist contains only BuyPlot actions")
        };
        let mut after = g.speculative_clone();
        if after.apply(pid, action).is_err()
            || after.players[pid].gold + f64::EPSILON < reserve + 200.0
        {
            return None;
        }
        // Buying the right hex can be valuable even before a Citizen works
        // it: ownership may expose a district or Wonder site.
        let site_value = after
            .producible_items(pid, *city)
            .into_iter()
            .filter(|item| match item {
                Item::District { pos: site, .. } | Item::Wonder { pos: site, .. } => site == pos,
                _ => false,
            })
            .map(|item| self.production_value(&after, pid, *city, &item, plan, counts))
            .fold(0.0, f64::max)
            .max(0.0)
            * 0.35;
        let score = base_score + site_value;
        (score >= 120.0).then_some(score)
    }

    fn gold_plot_scores(
        &self,
        context: PurchaseScoreContext<'_>,
        options: &[(f64, f64, std::cmp::Reverse<String>, Action)],
    ) -> Vec<Option<f64>> {
        options
            .iter()
            .map(|(_, base_score, _, action)| {
                self.gold_plot_score(context, action, *base_score)
            })
            .collect()
    }

    fn counts(&self, g: &Game, pid: usize) -> EmpireCounts {
        let mut counts = EmpireCounts::default();
        for uid in g.player_unit_ids(pid) {
            counts.add_unit(g, &g.units[&uid].kind);
        }
        for cid in g.player_city_ids(pid) {
            if let Some(item) = g.cities[&cid].queue.first() {
                counts.add_item(g, item);
            }
        }
        counts
    }

    fn religious_production(&self, g: &mut Game, pid: usize) {
        let city_ids = g.player_city_ids(pid);
        let has_holy_site = city_ids
            .iter()
            .any(|cid| g.cities[cid].districts.contains_key(crate::name!("holy_site")));
        if !has_holy_site {
            let holy_site_planned = city_ids.iter().any(|cid| {
                matches!(
                    g.cities[cid].queue.first(),
                    Some(Item::District { district, .. }) if district == "holy_site"
                )
            });
            if holy_site_planned {
                return;
            }
            let mut best: Option<(f64, u32, Pos)> = None;
            for cid in &city_ids {
                if !g.cities[cid].queue.is_empty() {
                    continue;
                }
                for item in g.producible_items(pid, *cid) {
                    let Item::District { district, pos } = item else {
                        continue;
                    };
                    if district != "holy_site" {
                        continue;
                    }
                    let faith = g.district_yields(crate::name!("holy_site"), pos).faith;
                    if best
                        .map(|old| {
                            faith > old.0 || (faith == old.0 && (*cid, pos) > (old.1, old.2))
                        })
                        .unwrap_or(true)
                    {
                        best = Some((faith, *cid, pos));
                    }
                }
            }
            if let Some((_, city, pos)) = best {
                let _ = g.apply(
                    pid,
                    &Action::Produce {
                        city,
                        item: Item::District {
                            district: crate::name!("holy_site"),
                            pos,
                        },
                    },
                );
            }
            return;
        }

        let religion_unfounded = g.players[pid].religion.is_none();
        let prophet_slot_open = g.religions_founded()
            + g.players
                .iter()
                .filter(|player| player.prophet_pending)
                .count()
            < g.max_religions();
        if religion_unfounded && !g.players[pid].prophet_pending && prophet_slot_open {
            let shrine_planned = city_ids.iter().any(|cid| {
                matches!(
                    g.cities[cid].queue.first(),
                    Some(Item::Building { building }) if building == "shrine"
                )
            });
            let has_shrine = city_ids.iter().any(|cid| {
                g.cities[cid]
                    .buildings
                    .iter()
                    .any(|building| building == "shrine")
            });
            if !has_shrine && g.religions_founded() == 0 {
                if shrine_planned {
                    return;
                }
                for cid in &city_ids {
                    let item = Item::Building {
                        building: crate::name!("shrine"),
                    };
                    if g.cities[cid].queue.is_empty()
                        && g.cities[cid].districts.contains_key(crate::name!("holy_site"))
                        && g.can_produce(pid, *cid, &item)
                    {
                        let _ = g.apply(pid, &Action::Produce { city: *cid, item });
                        return;
                    }
                }
                return;
            }

            let prayers = Item::Project {
                project: crate::name!("holy_site_prayers"),
            };
            let prayer_city = {
                let _memo = g.query_memo();
                city_ids
                    .iter()
                    .filter(|cid| {
                        g.cities[cid].queue.is_empty()
                            && g.cities[cid].districts.contains_key(crate::name!("holy_site"))
                            && g.can_produce(pid, **cid, &prayers)
                    })
                    .max_by(|left, right| {
                        g.city_yields(**left)
                            .production
                            .total_cmp(&g.city_yields(**right).production)
                            .then_with(|| right.cmp(left))
                    })
                    .copied()
            };
            if let Some(city) = prayer_city {
                let _ = g.apply(
                    pid,
                    &Action::Produce {
                        city,
                        item: prayers,
                    },
                );
            }
            return;
        }

        for building in ["shrine", "temple"] {
            for cid in &city_ids {
                let item = Item::Building {
                    building: Name::new(building),
                };
                if g.cities[cid].queue.is_empty()
                    && g.cities[cid].districts.contains_key(crate::name!("holy_site"))
                    && g.can_produce(pid, *cid, &item)
                {
                    let _ = g.apply(pid, &Action::Produce { city: *cid, item });
                    return;
                }
            }
        }
    }

    /// A rival founder's religion holding the majority in one of our cities.
    /// The religious victory requires every living major, so home
    /// reconversion alone denies it — this is the trigger for the
    /// cross-strategy defense below.
    fn home_conversion_threat(&self, g: &Game, pid: usize) -> Option<String> {
        let own = g.players[pid].religion.as_deref();
        let rival_faith = |religion: &str| {
            g.players.iter().any(|o| {
                o.id != pid && o.alive && !o.is_minor && o.religion.as_deref() == Some(religion)
            })
        };
        for cid in g.player_city_ids(pid) {
            let city = &g.cities[&cid];
            // React while the conversion is still in progress: waiting for a
            // flipped majority loses the pressure race outright. Any rival
            // faith at 60% of the city's strongest pressure is a live threat.
            let top = city.pressure.values().fold(0.0f64, |a, b| a.max(*b));
            if top <= 0.0 {
                continue;
            }
            for (religion, pressure) in &city.pressure {
                if Some(religion.as_str()) == own || *pressure + 1e-9 < top * 0.6 {
                    continue;
                }
                if rival_faith(religion) {
                    return Some(religion.clone());
                }
            }
        }
        None
    }

    /// Home religious defense for civilizations whose grand strategy is NOT
    /// religion. Founders reuse the emergency spending path; everyone else
    /// buys Missionaries of an adopted non-threat majority faith, which the
    /// engine now assigns from the purchase city (stock rule).
    fn religious_defense(&self, g: &mut Game, pid: usize, threat: &str) {
        if g.players[pid].religion.is_some() {
            self.religious_spending(g, pid, false);
            return;
        }
        let defenders = g
            .units
            .values()
            .filter(|unit| unit.owner == pid && unit.kind == "missionary")
            .count();
        if defenders >= 2 {
            return;
        }
        for cid in g.player_city_ids(pid) {
            let Some(majority) = g.city_religion(&g.cities[&cid]) else {
                continue;
            };
            if majority == threat {
                continue;
            }
            if g.apply(
                pid,
                &Action::Buy {
                    city: cid,
                    unit: crate::name!("missionary"),
                    formation: 0,
                    currency: "faith".to_string(),
                },
            )
            .is_ok()
            {
                return;
            }
        }
    }

    fn city_needs_religious_support(
        g: &Game,
        pid: usize,
        city: &crate::game::City,
        religion: &str,
    ) -> bool {
        if city.owner != pid {
            return false;
        }
        let own = city.pressure.get(religion).copied().unwrap_or(0.0);
        let rival = city
            .pressure
            .iter()
            .filter(|(faith, _)| faith.as_str() != religion)
            .map(|(_, pressure)| *pressure)
            .fold(0.0_f64, f64::max);
        g.city_religion(city) != Some(religion) || (rival > 0.0 && rival * 2.0 >= own)
    }

    /// Keep a founded religion's small field corps useful after the adaptive
    /// planner changes its primary victory strategy. Previously that switch
    /// made charged Missionaries stop at home and let thousands of Faith sit
    /// idle. A large surplus may start a secondary campaign, while an active
    /// spreader keeps it moving after the initial purchase lowers the bank.
    fn religious_offensive_posture(&self, g: &Game, pid: usize, strategy: GrandStrategy) -> bool {
        if strategy == GrandStrategy::Religion {
            return true;
        }
        if !g.victory_conditions.religious {
            return false;
        }
        let Some(religion) = g.players[pid].religion.as_deref() else {
            return false;
        };
        let foreign_target = g.cities.values().any(|city| {
            city.owner != pid
                && g.players[city.owner].alive
                && !g.players[city.owner].is_minor
                && !g.players[city.owner].is_barbarian
                && !g.is_at_war(pid, city.owner)
                && g.city_religion(city) != Some(religion)
        });
        if !foreign_target {
            return false;
        }
        let active_campaign = g.units.values().any(|unit| {
            unit.owner == pid
                && unit.religion.as_deref() == Some(religion)
                && unit.charges > 0
                && g.rules.units[unit.kind].religious_spread > 0.0
        });
        active_campaign || g.players[pid].faith >= g.game_speed.scale(2_000.0)
    }

    fn religious_spending(&self, g: &mut Game, pid: usize, offensive: bool) {
        self.religious_spending_with_reserve(g, pid, offensive, 80.0);
    }

    fn religious_spending_with_reserve(
        &self,
        g: &mut Game,
        pid: usize,
        offensive: bool,
        ordinary_reserve: f64,
    ) {
        let Some(religion) = g.players[pid].religion.clone() else {
            return;
        };
        let match_point_defense = self
            .victory_denial(g, pid)
            .is_some_and(|(_, counter)| counter == GrandStrategy::Religion);
        let count_units = |kind: &str| {
            g.units
                .values()
                .filter(|unit| unit.owner == pid && unit.kind == kind)
                .count()
        };
        let missionaries = count_units("missionary");
        let apostles = count_units("apostle");
        let gurus = count_units("guru");
        let inquisitors = count_units("inquisitor");
        let defensive_targets = g
            .player_city_ids(pid)
            .into_iter()
            .filter(|cid| Self::city_needs_religious_support(g, pid, &g.cities[cid], &religion))
            .count();
        let home_under_pressure = defensive_targets > 0;
        let inquisition_launched = g.players[pid]
            .counters
            .get("inquisition")
            .copied()
            .unwrap_or(0)
            > 0;
        let spread_targets = defensive_targets
            + usize::from(offensive)
                * g.cities
                    .values()
                    .filter(|city| {
                        city.owner != pid
                            && !g.is_at_war(pid, city.owner)
                            && g.city_religion(city) != Some(religion.as_str())
                    })
                    .count();
        // A small circulating corps is enough: every Missionary has several
        // spreads, and replacements can be bought as charges are consumed.
        // Scaling gently with live targets preserves a religious push without
        // allowing one faith purchase every turn to fill the map.
        let missionary_cap = if spread_targets == 0 {
            0
        } else if offensive {
            (2 + spread_targets.div_ceil(4)).min(6)
        } else {
            (1 + defensive_targets.div_ceil(2)).min(2)
        };
        let apostle_cap = if offensive { 2 } else { 0 };
        let guru_cap = usize::from(offensive && apostles > 0);
        let inquisitor_cap = if home_under_pressure && inquisition_launched {
            2
        } else {
            0
        };
        let priorities: &[&str] = if home_under_pressure
            && inquisition_launched
            && inquisitors < 2
        {
            &["inquisitor", "apostle", "missionary", "guru"]
        } else if !offensive {
            &["missionary", "inquisitor"]
        } else if apostles < 2 {
            &["apostle", "missionary", "guru"]
        } else if gurus < 1 {
            &["guru", "apostle", "missionary"]
        } else {
            &["missionary", "apostle", "guru"]
        };
        for unit in priorities {
            let cap = match *unit {
                "missionary" => missionary_cap,
                "apostle" => apostle_cap,
                "guru" => guru_cap,
                "inquisitor" => inquisitor_cap,
                _ => 0,
            };
            let current = match *unit {
                "missionary" => missionaries,
                "apostle" => apostles,
                "guru" => gurus,
                "inquisitor" => inquisitors,
                _ => 0,
            };
            if current >= cap {
                continue;
            }
            let Some(spec) = g.rules.units.get(unit) else {
                continue;
            };
            let price = spec.cost * 2.0;
            // The ordinary buffer is useful while safely building toward a
            // victory, but it must not block the last affordable defender at
            // match point or when one of our cities is already losing its
            // religious majority.
            let reserve = if match_point_defense || home_under_pressure {
                0.0
            } else {
                ordinary_reserve
            };
            if g.players[pid].faith + f64::EPSILON < price + reserve {
                continue;
            }
            let cities = g.player_city_ids(pid);
            for cid in cities {
                // Religious units inherit the purchase city's majority.  A
                // converted Holy Site must never make the defender spend its
                // Faith strengthening the runaway rival religion.
                if g.city_religion(&g.cities[&cid]) != Some(religion.as_str()) {
                    continue;
                }
                if g.apply(
                    pid,
                    &Action::Buy {
                        city: cid,
                        unit: Name::new(unit),
                        formation: 0,
                        currency: "faith".to_string(),
                    },
                )
                .is_ok()
                {
                    return;
                }
            }
        }
    }

    fn culture_spending(&self, g: &mut Game, pid: usize) {
        let active_naturalists = g
            .units
            .values()
            .filter(|unit| unit.owner == pid && unit.kind == "naturalist")
            .count();
        if active_naturalists == 0
            && !g.national_park_sites(pid).is_empty()
            && g.players[pid].faith + f64::EPSILON >= g.naturalist_purchase_cost(pid)
        {
            for city in g.player_city_ids(pid) {
                if g.apply(
                    pid,
                    &Action::Buy {
                        city,
                        unit: crate::name!("naturalist"),
                        formation: 0,
                        currency: "faith".to_string(),
                    },
                )
                .is_ok()
                {
                    return;
                }
            }
        }
        let active_bands = g
            .units
            .values()
            .filter(|unit| unit.owner == pid && unit.kind == "rock_band")
            .count();
        if active_bands >= 2
            || !g.players[pid].civics.contains(&crate::name!("cold_war"))
            || g.players[pid].faith + f64::EPSILON < g.rules.units["rock_band"].cost
        {
            return;
        }
        for city in g.player_city_ids(pid) {
            if g.apply(
                pid,
                &Action::Buy {
                    city,
                    unit: crate::name!("rock_band"),
                    formation: 0,
                    currency: "faith".to_string(),
                },
            )
            .is_ok()
            {
                return;
            }
        }
    }

    fn faith_building_spending(&self, g: &mut Game, pid: usize, strategy: GrandStrategy) {
        let reserve = match strategy {
            GrandStrategy::Religion => 180.0,
            GrandStrategy::Culture if !g.national_park_sites(pid).is_empty() => {
                g.naturalist_purchase_cost(pid)
            }
            GrandStrategy::Culture if g.players[pid].civics.contains(&crate::name!("cold_war")) => 700.0,
            _ => 80.0,
        };
        // Every candidate below must clear `cost + reserve`, and a purchase
        // cost is never negative — so a bank under the reserve cannot buy
        // anything no matter what the menu holds. Skip building the menu at
        // all: `legal_purchase_actions` is the priciest question this
        // function asks (worker clones of the whole Game), and
        // `military_faith_spending` already banks-gates the same way.
        if g.players[pid].faith + f64::EPSILON < reserve {
            return;
        }
        let best = self
            .legal_purchase_actions(g, pid)
            .into_iter()
            .filter_map(|action| match &action {
                Action::BuyBuilding {
                    city,
                    building,
                    currency,
                } if currency == "faith" => {
                    let spec = &g.rules.buildings[building];
                    let cost = g.building_faith_purchase_cost(pid, *city, building)?;
                    if g.players[pid].faith + f64::EPSILON < cost + reserve {
                        return None;
                    }
                    let worship = spec.worship_belief.is_some() as i32;
                    let defensive_value = match strategy {
                        GrandStrategy::Conquest | GrandStrategy::Recovery => spec.outer_defense * 2,
                        _ => spec.outer_defense,
                    };
                    let score = (self.yield_value(spec.yields, strategy) * 25.0) as i32
                        + (spec.housing * 35.0 + spec.amenity * 50.0) as i32
                        + spec.great_work_slots.values().sum::<i32>() * 60
                        + spec.trade_route_capacity * 100
                        + defensive_value
                        + worship * 220
                        - (cost * 0.05) as i32;
                    Some((score, std::cmp::Reverse((*city, *building)), action))
                }
                _ => None,
            })
            .max_by_key(|(score, key, _)| (*score, *key));
        if let Some((_, _, action)) = best {
            let _ = g.apply(pid, &action);
        }
    }

    fn governor_priority(strategy: GrandStrategy) -> &'static [&'static str] {
        match strategy {
            GrandStrategy::Expansion => &[
                "magnus", "pingala", "liang", "reyna", "victor", "moksha", "amani",
            ],
            GrandStrategy::Science => &[
                "pingala", "magnus", "reyna", "liang", "victor", "moksha", "amani",
            ],
            GrandStrategy::Culture => &[
                "pingala", "reyna", "liang", "magnus", "moksha", "victor", "amani",
            ],
            GrandStrategy::Religion => &[
                "moksha", "pingala", "magnus", "amani", "liang", "victor", "reyna",
            ],
            GrandStrategy::Diplomacy => &[
                "amani", "pingala", "reyna", "magnus", "liang", "victor", "moksha",
            ],
            GrandStrategy::Conquest => &[
                "victor", "magnus", "pingala", "liang", "reyna", "moksha", "amani",
            ],
            GrandStrategy::Recovery => &[
                "victor", "reyna", "magnus", "pingala", "liang", "moksha", "amani",
            ],
        }
    }

