    /// ⚠ **Six, not nine, since 2026-08-10.** `desired_cities` is
    /// `floor + turn / cadence`, so removing the production floor of six lowers
    /// what the ramp reaches inside the window as well as where it starts. That
    /// consequence is **inside the measurement**, not a side effect of it: the
    /// arm that passed the promotion matrix at +41 Elo on deployment-online
    /// (125/65, p=0.0000) is exactly this agent, reaching six here rather than
    /// nine. The nine-city reach was part of what cost the thirty Elo.
    ///
    /// What the test still pins is the shape that matters — that the window is
    /// open at turn 270, that the plan is Expansion, and that a settler is not
    /// vetoed — so a regression that stops the ramp climbing at all still
    /// fails here.
    #[test]
    fn expansion_window_still_climbs_and_wants_a_settler_before_endgame() {
        let mut game = Game::new_full(1, 30, 18, 7_113, 500, 0, false);
        let settler = game
            .player_unit_ids(0)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .unwrap();
        game.apply(0, &Action::FoundCity { unit: settler }).unwrap();
        for tile in game.map.tiles.values_mut() {
            tile.terrain = crate::name!("grassland");
            tile.feature = None;
        }
        let city = game.player_city_ids(0)[0];
        game.cities.get_mut(&city).unwrap().pop = 6;
        game.turn = 270;

        let ai = AdvancedAi::new();
        let plan = ai.assess(&game, 0);
        assert_eq!(plan.desired_cities, 6);
        assert!(
            plan.desired_cities > 3,
            "the ramp must still climb above the base floor inside the window"
        );
        assert_eq!(plan.strategy, GrandStrategy::Expansion);
        let item = Item::Unit {
            unit: crate::name!("settler"),
        };
        let counts = ai.counts(&game, 0);
        assert!(ai.production_value(&game, 0, city, &item, &plan, &counts) > -9_000.0);

        game.turn = 300;
        assert!(!AdvancedAi::expansion_window_open(&game));
        assert!(ai.production_value(&game, 0, city, &item, &plan, &counts) < -9_000.0);
    }

    #[test]
    fn expansion_dispatch_and_late_window_are_independent_on_online() {
        let mut game = Game::new_with(GameOptions {
            speed: "online".to_string(),
            ..GameOptions::new(1, 30, 18, 7_114, 250, 0)
        });
        // These are intentionally derived from the live duration curve. The
        // earlier preregistration prose named an obsolete 150..225 range,
        // while the engine's fidelity-correct duration scaling resolves the
        // shipped formulas to this 198..217 window.
        assert_eq!(game.standard_duration(300), 198);
        assert_eq!(game.standard_duration(50), 33);
        assert_eq!(AdvancedAi::stock_expansion_deadline(&game), 198);
        assert_eq!(AdvancedAi::late_expansion_deadline(&game), 217);

        let plan = StrategicPlan {
            strategy: GrandStrategy::Expansion,
            target_player: None,
            target_city: None,
            threatened_city: None,
            desired_cities: 6,
            assessed_turn: 0,
            rush: false,
        };
        let stock = AdvancedAi::new();
        let mut dispatcher = AdvancedAi::new();
        dispatcher.expansion_dispatch = true;
        let mut late = AdvancedAi::new();
        late.late_expansion = true;
        let mut combined = AdvancedAi::new();
        combined.expansion_dispatch = true;
        combined.late_expansion = true;

        game.turn = 197;
        assert!(stock.adaptive_expansion_window_open(&game));
        assert!(late.adaptive_expansion_window_open(&game));
        game.turn = 198;
        assert!(!stock.adaptive_expansion_window_open(&game));
        assert!(late.adaptive_expansion_window_open(&game));
        game.turn = 216;
        assert!(combined.adaptive_expansion_window_open(&game));
        game.turn = 217;
        assert!(!combined.adaptive_expansion_window_open(&game));

        assert!(!stock.adaptive_expansion_dispatches(&plan, None));
        assert!(dispatcher.adaptive_expansion_dispatches(&plan, None));
        assert!(!late.adaptive_expansion_dispatches(&plan, None));
        assert!(combined.adaptive_expansion_dispatches(&plan, None));
        assert!(!combined.adaptive_expansion_dispatches(&plan, Some(VictoryTarget::Culture)));

        let targeted = AdvancedAi::targeting(VictoryTarget::Culture);
        game.turn = game.standard_duration(175) - 1;
        assert!(targeted.settler_expansion_window_open(&game, 0, 0));
        game.turn = game.standard_duration(175);
        assert!(!targeted.settler_expansion_window_open(&game, 0, 0));
    }

    #[test]
    fn conquest_can_target_an_exposed_city_state_but_preserves_its_suzerain() {
        let mut game = Game::new_full(2, 30, 18, 711, 300, 1, false);
        for pid in 0..2 {
            let settler = game
                .player_unit_ids(pid)
                .into_iter()
                .find(|unit| game.units[unit].kind == "settler")
                .unwrap();
            game.current = pid;
            game.apply(pid, &Action::FoundCity { unit: settler })
                .unwrap();
        }
        game.current = 0;
        game.turn = 200;
        let minor = game
            .players
            .iter()
            .find(|player| player.is_minor && !player.is_barbarian)
            .unwrap()
            .id;
        game.record_contact(0, 1);
        game.record_contact(0, minor);
        let rival_capital = game.cities[&game.player_city_ids(1)[0]].pos;
        for _ in 0..6 {
            game.spawn_test_unit("giant_death_robot", 1, rival_capital);
        }

        let ai = AdvancedAi::targeting(VictoryTarget::Domination);
        let exposed = ai.assess(&game, 0);
        assert_eq!(exposed.strategy, GrandStrategy::Conquest);
        assert_eq!(exposed.target_player, Some(minor));

        game.players[0].envoys = vec![(minor, 3)];
        assert_eq!(game.suzerain_of(minor), Some(0));
        let allied = ai.assess(&game, 0);
        assert_eq!(allied.target_player, Some(1));
    }

    #[test]
    fn campaign_masks_allied_rivals_and_their_suzerained_city_states() {
        let mut game = Game::new_full(2, 30, 18, 7_112, 300, 1, false);
        for pid in 0..2 {
            let settler = game
                .player_unit_ids(pid)
                .into_iter()
                .find(|unit| game.units[unit].kind == "settler")
                .unwrap();
            game.current = pid;
            game.apply(pid, &Action::FoundCity { unit: settler })
                .unwrap();
        }
        game.current = 0;
        game.turn = 200;
        let minor = game
            .players
            .iter()
            .find(|player| player.is_minor && !player.is_barbarian)
            .unwrap()
            .id;
        game.players[1].envoys = vec![(minor, 3)];
        assert_eq!(game.suzerain_of(minor), Some(1));

        let alliance = crate::game::AllianceState {
            kind: "military".to_string(),
            points: 0.0,
            level: 1,
            ends: game.turn + 30,
        };
        game.players[0].alliances.insert(1, alliance.clone());
        game.players[1].alliances.insert(0, alliance);

        let ai = AdvancedAi::targeting(VictoryTarget::Domination);
        assert!(!ai.campaign_target_legal(&game, 0, 1));
        assert!(!ai.campaign_target_legal(&game, 0, minor));
        assert_eq!(ai.assess(&game, 0).target_player, None);

        let mut stale_ai = AdvancedAi::targeting(VictoryTarget::Domination);
        stale_ai.plan = Some(StrategicPlan {
            strategy: GrandStrategy::Conquest,
            target_player: Some(1),
            target_city: game.player_city_ids(1).first().copied(),
            threatened_city: None,
            desired_cities: 3,
            assessed_turn: game.turn,
            rush: false,
        });
        assert!(
            stale_ai.plan_stale(&game, 0),
            "a new alliance must interrupt a cached hostile plan immediately"
        );

        // A loaded legacy position can contain contradictory relationship
        // state or omit the contact record. An actual war remains a forcing
        // objective until peace.
        game.players[0].met.remove(&1);
        game.players[1].met.remove(&0);
        game.at_war.insert((0, 1));
        assert!(ai.campaign_target_legal(&game, 0, 1));
        assert!(
            ai.assess(&game, 0)
                .target_player
                .is_some_and(|target| target == 1 || target == minor),
            "the suzerain or the city-state that joined its war must remain actionable"
        );
    }

    /// Off by default, set only by the live bridge, holdable off on its own —
    /// the siege-commitment term follows the same contract as every other
    /// bridge repair, so the frozen `advanced_v1` anchor keeps its ladder.
    #[test]
    fn only_the_live_bridge_finishes_a_siege() {
        let fresh = AdvancedAi::new();
        assert!(!fresh.siege_commitment);
        assert!(!AdvancedAi::legacy().siege_commitment);
        let mut live = AdvancedAi::new();
        live.enable_live_bridge();
        assert!(live.siege_commitment);
        live.disable_siege_commitment();
        assert!(!live.siege_commitment);
    }

    /// What the shipped scorer pays for fifteen turns of siege, and what the
    /// treatment pays.
    ///
    /// `defenses` credits a broken city `0.12` per point of health, so the
    /// whole health bar is worth 21 — and `core_distance * 7.0` plus
    /// `military_distance * 5.0` swing about 60 over five tiles. That is the
    /// arithmetic behind live run `civvis-20260808T142724Z` leaving Biruta at
    /// 25 hp with its walls down on t90 and re-aiming at Ziz on t91.
    #[test]
    fn siege_commitment_prices_the_health_already_stripped_from_a_breach() {
        let mut game = Game::new_full(2, 30, 18, 7_111, 300, 0, false);
        for pid in 0..2 {
            game.current = pid;
            let settler = game
                .player_unit_ids(pid)
                .into_iter()
                .find(|unit| game.units[unit].kind == "settler")
                .unwrap();
            game.apply(pid, &Action::FoundCity { unit: settler })
                .unwrap();
        }
        let enemy = game.player_city_ids(1)[0];
        let enemy_position = game.cities[&enemy].pos;
        for unit in game.units.keys().copied().collect::<Vec<_>>() {
            game.remove_unit(unit);
        }
        // A besieger of ours stands on the ring, so the city is both observed
        // and inside `SIEGE_COMMITMENT_REACH`.
        let besieger = game
            .nbrs(enemy_position)
            .into_iter()
            .find(|position| {
                game.map
                    .get(*position)
                    .is_some_and(|tile| game.rules.is_passable(tile) && !game.rules.is_water(tile))
            })
            .expect("the enemy capital has a land approach");
        game.spawn_test_unit("warrior", 0, besieger);

        let value = |ai: &AdvancedAi, game: &Game| {
            ai.campaign_city_value(game, 0, &game.cities[&enemy], GrandStrategy::Conquest)
        };
        let breach_to = |game: &mut Game, hp: i32| {
            let city = game.cities.get_mut(&enemy).unwrap();
            city.hp = hp;
            city.wall_hp = 0;
            city.buildings.retain(|building| {
                !matches!(
                    building.as_str(),
                    "walls" | "medieval_walls" | "renaissance_walls"
                )
            });
        };

        let mut shipped = AdvancedAi::targeting(VictoryTarget::Domination);
        let mut live = AdvancedAi::targeting(VictoryTarget::Domination);
        live.enable_siege_commitment();

        breach_to(&mut game, CITY_MAX_HP);
        shipped.belief.observe(&game, 0);
        live.belief.observe(&game, 0);
        let shipped_whole = value(&shipped, &game);
        let live_whole = value(&live, &game);
        assert_eq!(
            shipped_whole, live_whole,
            "a city at full health has had nothing stripped, so the treatment is inert"
        );

        breach_to(&mut game, 25);
        shipped.belief.observe(&game, 0);
        live.belief.observe(&game, 0);
        let stripped = (CITY_MAX_HP - 25) as f64;
        let shipped_broken = value(&shipped, &game);
        let live_broken = value(&live, &game);
        // The shipped credit for breaking a city almost open. `core_distance`
        // alone swings 7.0 a tile, so this loses to a fresh objective three
        // tiles nearer — which is exactly what the live run did.
        assert!(
            shipped_whole - shipped_broken < 40.0,
            "the shipped scorer prices the whole health bar at under 40 points \
             (measured {}), less than the distance terms swing",
            shipped_whole - shipped_broken
        );
        // Differencing the two controllers over the identical board isolates
        // the new term from everything else that moves with a city's health.
        assert!(
            ((shipped_broken - live_broken) - stripped * SIEGE_COMMITMENT_PER_HP).abs() < 1e-6,
            "the treatment is worth exactly {SIEGE_COMMITMENT_PER_HP} per stripped point — {} \
             here — and nothing else changes",
            stripped * SIEGE_COMMITMENT_PER_HP
        );
    }

    /// Walls standing means capture is not close, and damage nobody of ours is
    /// near is not our investment. Both keep the term at zero, so it stays
    /// inert outside the case it was measured on.
    #[test]
    fn siege_commitment_ignores_an_unbreached_city_and_a_siege_out_of_reach() {
        let mut game = Game::new_full(2, 30, 18, 7_111, 300, 0, false);
        for pid in 0..2 {
            game.current = pid;
            let settler = game
                .player_unit_ids(pid)
                .into_iter()
                .find(|unit| game.units[unit].kind == "settler")
                .unwrap();
            game.apply(pid, &Action::FoundCity { unit: settler })
                .unwrap();
        }
        let enemy = game.player_city_ids(1)[0];
        let enemy_position = game.cities[&enemy].pos;
        for unit in game.units.keys().copied().collect::<Vec<_>>() {
            game.remove_unit(unit);
        }
        let mut shipped = AdvancedAi::targeting(VictoryTarget::Domination);
        let mut live = AdvancedAi::targeting(VictoryTarget::Domination);
        live.enable_siege_commitment();

        // Differencing the two controllers over one board isolates the term.
        let gap = |shipped: &AdvancedAi, live: &AdvancedAi, game: &Game| {
            shipped.campaign_city_value(game, 0, &game.cities[&enemy], GrandStrategy::Conquest)
                - live.campaign_city_value(game, 0, &game.cities[&enemy], GrandStrategy::Conquest)
        };
        let set = |game: &mut Game, hp: i32, wall_hp: i32| {
            let city = game.cities.get_mut(&enemy).unwrap();
            city.hp = hp;
            city.wall_hp = wall_hp;
        };

        // Beaten down to 25 hp but the walls still stand: capture is not close,
        // so the term stays out of it.
        let ring = game
            .nbrs(enemy_position)
            .into_iter()
            .find(|position| {
                game.map
                    .get(*position)
                    .is_some_and(|tile| game.rules.is_passable(tile) && !game.rules.is_water(tile))
            })
            .expect("the enemy capital has a land approach");
        let besieger = game.spawn_test_unit("warrior", 0, ring);
        set(&mut game, 25, 100);
        shipped.belief.observe(&game, 0);
        live.belief.observe(&game, 0);
        assert_eq!(
            gap(&shipped, &live, &game),
            0.0,
            "with the walls up there is no breach to finish"
        );

        // Breached and beaten down, with a besieger on the ring: full credit.
        set(&mut game, 25, 0);
        shipped.belief.observe(&game, 0);
        live.belief.observe(&game, 0);
        assert!(
            (gap(&shipped, &live, &game) - 175.0 * SIEGE_COMMITMENT_PER_HP).abs() < 1e-6,
            "a breach our army is standing on is worth the health already stripped"
        );

        // Same breach, but our nearest soldier is beyond the reach horizon.
        game.remove_unit(besieger);
        let far = game
            .map
            .tiles
            .keys()
            .copied()
            .find(|position| {
                game.map
                    .get(*position)
                    .is_some_and(|tile| game.rules.is_passable(tile) && !game.rules.is_water(tile))
                    && game.wdist(enemy_position, *position) > SIEGE_COMMITMENT_REACH
            })
            .expect("the test map has ground beyond the reach horizon");
        game.spawn_test_unit("warrior", 0, far);
        shipped.belief.observe(&game, 0);
        live.belief.observe(&game, 0);
        assert_eq!(
            gap(&shipped, &live, &game),
            0.0,
            "damage dealt where no soldier of ours can finish it is not our siege"
        );
    }

    #[test]
    fn live_campaign_holds_a_major_war_city_until_capture_or_emergency() {
        let mut game = Game::new_full(2, 30, 18, 7_112, 300, 0, false);
        for pid in 0..2 {
            game.current = pid;
            let settler = game
                .player_unit_ids(pid)
                .into_iter()
                .find(|unit| game.units[unit].kind == "settler")
                .unwrap();
            game.apply(pid, &Action::FoundCity { unit: settler })
                .unwrap();
        }
        let enemy_capital = game.player_city_ids(1)[0];
        let enemy_position = game.cities[&enemy_capital].pos;
        let outpost_position = game
            .map
            .tiles
            .iter()
            .filter(|(position, tile)| {
                game.rules.is_passable(tile)
                    && !game.rules.is_water(tile)
                    && tile.owner_city.is_none()
                    && game.wdist(enemy_position, **position) >= 9
                    && game
                        .cities
                        .values()
                        .all(|city| game.wdist(city.pos, **position) >= 4)
            })
            .map(|(position, _)| *position)
            .next()
            .expect("test map has a second enemy-city site");
        game.current = 1;
        let settler = game.spawn_test_unit("settler", 1, outpost_position);
        game.apply(1, &Action::FoundCity { unit: settler })
            .expect("the enemy can found its outpost");
        let enemy_outpost = game
            .player_city_ids(1)
            .into_iter()
            .find(|city| *city != enemy_capital)
            .expect("the enemy owns two cities");
        game.current = 0;
        game.at_war.insert((0, 1));
        game.spawn_test_unit("scout", 0, game.cities[&enemy_capital].pos);
        game.spawn_test_unit("scout", 0, game.cities[&enemy_outpost].pos);

        // Let the regular ranking choose the city it would otherwise re-pick
        // on the next assessment, then preserve the other existing objective.
        let mut ranking = AdvancedAi::targeting(VictoryTarget::Domination);
        ranking.belief.observe(&game, 0);
        let ranked = ranking.assess(&game, 0);
        assert_eq!(ranked.target_player, Some(1));
        let ranked_target = ranked.target_city.expect("the major war has a city objective");
        let previous_target = [enemy_capital, enemy_outpost]
            .into_iter()
            .find(|city| *city != ranked_target)
            .expect("the enemy's other city is a valid previous objective");
        let prior_plan = StrategicPlan {
            strategy: ranked.strategy,
            target_player: Some(1),
            target_city: Some(previous_target),
            threatened_city: None,
            desired_cities: ranked.desired_cities,
            assessed_turn: game.turn.saturating_sub(1),
            rush: false,
        };

        let mut ordinary = AdvancedAi::targeting(VictoryTarget::Domination);
        ordinary.belief.observe(&game, 0);
        ordinary.plan = Some(prior_plan.clone());
        assert_eq!(
            ordinary.assess(&game, 0).target_city,
            Some(ranked_target),
            "the frozen planner still refreshes its objective from the city ranking"
        );

        let mut live = AdvancedAi::targeting(VictoryTarget::Domination);
        live.enable_siege_commitment();
        live.belief.observe(&game, 0);
        live.plan = Some(prior_plan);
        assert_eq!(
            live.assess(&game, 0).target_city,
            Some(previous_target),
            "the live major-war column keeps marching toward the city it was ordered to take"
        );

        // A live emergency is more urgent than the offensive campaign, even
        // if it names the city that the ordinary ranking would have picked.
        game.active_emergencies.push(crate::game::Emergency {
            id: 1,
            kind: "military".to_string(),
            target: 1,
            city: ranked_target,
            original_owner: 1,
            members: [0].into_iter().collect(),
            contributions: BTreeMap::new(),
            started: game.turn,
            ends: game.turn + 30,
        });
        assert_eq!(
            live.assess(&game, 0).target_city,
            Some(ranked_target),
            "an emergency may immediately override the committed campaign city"
        );
        game.active_emergencies.clear();

        // Capture invalidates the old objective. The remaining enemy city is
        // then eligible for a fresh campaign ranking immediately.
        game.cities.get_mut(&previous_target).unwrap().owner = 0;
        assert_eq!(
            live.assess(&game, 0).target_city,
            Some(ranked_target),
            "a captured city cannot keep the campaign target pinned"
        );
    }

    #[test]
    fn campaign_city_ordering_prefers_a_breach_then_the_domination_capital() {
        let mut game = Game::new_full(2, 30, 18, 7_111, 300, 0, false);
        for pid in 0..2 {
            game.current = pid;
            let settler = game
                .player_unit_ids(pid)
                .into_iter()
                .find(|unit| game.units[unit].kind == "settler")
                .unwrap();
            game.apply(pid, &Action::FoundCity { unit: settler })
                .unwrap();
        }
        let own_capital = game.player_city_ids(0)[0];
        let enemy_capital = game.player_city_ids(1)[0];
        let enemy_position = game.cities[&enemy_capital].pos;
        let capital_distance = game.wdist(game.cities[&own_capital].pos, enemy_position);
        let outpost_position = game
            .map
            .tiles
            .iter()
            .filter(|(position, tile)| {
                game.rules.is_passable(tile)
                    && !game.rules.is_water(tile)
                    && tile.owner_city.is_none()
                    && game.wdist(enemy_position, **position) >= 9
                    && game
                        .cities
                        .values()
                        .all(|city| game.wdist(city.pos, **position) >= 4)
            })
            .min_by_key(|(position, _)| {
                (
                    (game.wdist(game.cities[&own_capital].pos, **position) - capital_distance)
                        .abs(),
                    **position,
                )
            })
            .map(|(position, _)| *position)
            .expect("test map has a comparable second-city site");
        game.current = 1;
        let settler = game.spawn_test_unit("settler", 1, outpost_position);
        game.apply(1, &Action::FoundCity { unit: settler }).unwrap();
        let enemy_outpost = game
            .player_city_ids(1)
            .into_iter()
            .find(|city| *city != enemy_capital)
            .unwrap();
        for unit in game.units.keys().copied().collect::<Vec<_>>() {
            game.remove_unit(unit);
        }

        let fortify = |game: &mut Game, city: u32| {
            let position = {
                let target = game.cities.get_mut(&city).unwrap();
                target.hp = 200;
                target.wall_hp = 400;
                target.buildings.extend([
                    crate::name!("walls"),
                    crate::name!("medieval_walls"),
                    crate::name!("renaissance_walls"),
                ]);
                target.pos
            };
            for _ in 0..3 {
                game.spawn_test_unit("giant_death_robot", 1, position);
            }
        };
        let breach = |game: &mut Game, city: u32| {
            let target = game.cities.get_mut(&city).unwrap();
            target.hp = 25;
            target.wall_hp = 0;
            target.buildings.retain(|building| {
                !matches!(
                    building.as_str(),
                    "walls" | "medieval_walls" | "renaissance_walls"
                )
            });
        };
        let _capital_observer = game.spawn_test_unit("scout", 0, game.cities[&enemy_capital].pos);
        let _outpost_observer = game.spawn_test_unit("scout", 0, game.cities[&enemy_outpost].pos);
        let mut ai = AdvancedAi::targeting(VictoryTarget::Domination);

        fortify(&mut game, enemy_capital);
        breach(&mut game, enemy_outpost);
        ai.belief.observe(&game, 0);
        let exposed_outpost = ai.campaign_city_value(
            &game,
            0,
            &game.cities[&enemy_outpost],
            GrandStrategy::Conquest,
        );
        let fortified_capital = ai.campaign_city_value(
            &game,
            0,
            &game.cities[&enemy_capital],
            GrandStrategy::Conquest,
        );
        assert!(
            exposed_outpost < fortified_capital,
            "an exposed breach ({exposed_outpost}) should be searched before a fully defended capital ({fortified_capital})"
        );

        for unit in game.units.keys().copied().collect::<Vec<_>>() {
            game.remove_unit(unit);
        }
        breach(&mut game, enemy_capital);
        fortify(&mut game, enemy_outpost);
        let _capital_refresh = game.spawn_test_unit("scout", 0, game.cities[&enemy_capital].pos);
        let _outpost_refresh = game.spawn_test_unit("scout", 0, game.cities[&enemy_outpost].pos);
        ai.belief.observe(&game, 0);
        assert!(
            ai.campaign_city_value(
                &game,
                0,
                &game.cities[&enemy_capital],
                GrandStrategy::Conquest,
            ) < ai.campaign_city_value(
                &game,
                0,
                &game.cities[&enemy_outpost],
                GrandStrategy::Conquest,
            ),
            "once both geometry and defenses favor it, Domination must order the original capital first"
        );
    }

    #[test]
    fn conquest_army_stages_before_diplomacy_opens_the_war() {
        let mut game = Game::new_full(2, 30, 18, 7_114, 300, 0, false);
        // A war has to be declarable, which means the two have met.
        game.record_contact(0, 1);
        for pid in 0..2 {
            game.current = pid;
            let settler = game
                .player_unit_ids(pid)
                .into_iter()
                .find(|unit| game.units[unit].kind == "settler")
                .unwrap();
            game.apply(pid, &Action::FoundCity { unit: settler })
                .unwrap();
        }
        game.current = 0;
        game.turn = 60;
        let target_city = game.player_city_ids(1)[0];
        let objective = game.cities[&target_city].pos;

        // The declaration rule also requires a two-city operating base. Put
        // the second city close enough that this test isolates army staging.
        let second_site = game
            .map
            .tiles
            .iter()
            .filter(|(position, tile)| {
                game.rules.is_passable(tile)
                    && !game.rules.is_water(tile)
                    && tile.owner_city.is_none()
                    && game.wdist(**position, objective) <= 18
                    && game
                        .cities
                        .values()
                        .all(|city| game.wdist(city.pos, **position) >= 4)
            })
            .map(|(position, _)| *position)
            .next()
            .expect("test map has a legal second-city site");
        let settler = game.spawn_test_unit("settler", 0, second_site);
        game.apply(0, &Action::FoundCity { unit: settler })
            .unwrap();

        for unit in game.units.keys().copied().collect::<Vec<_>>() {
            game.remove_unit(unit);
        }
        for tile in game.map.tiles.values_mut() {
            tile.terrain = crate::name!("grassland");
            tile.feature = None;
            tile.hills = false;
        }
        let remote = game
            .map
            .tiles
            .keys()
            .copied()
            .find(|position| {
                game.wdist(*position, objective) >= 10
                    && game.city_at(*position).is_none()
                    && game.map.tiles[position]
                        .owner_city
                        .and_then(|city| game.cities.get(&city))
                        .is_none_or(|city| city.owner != 1)
            })
            .expect("test map has a remote muster position");
        let army: Vec<u32> = (0..4)
            .map(|_| game.spawn_test_unit("swordsman", 0, remote))
            .collect();
        let plan = StrategicPlan {
            strategy: GrandStrategy::Conquest,
            target_player: Some(1),
            target_city: Some(target_city),
            threatened_city: None,
            desired_cities: 3,
            assessed_turn: game.turn,
            rush: false,
        };
        let mut ai = AdvancedAi::targeting(VictoryTarget::Domination);

        assert!(!ai.campaign_staged_for_war(&game, 0, 1, objective, true));
        let before = game.wdist(game.units[&army[0]].pos, objective);
        assert_eq!(
            ai.campaign_staging_step(&mut game, 0, army[0], &plan),
            Some(true)
        );
        assert!(game.wdist(game.units[&army[0]].pos, objective) < before);

        ai.advanced_diplomacy(&mut game, 0, &plan);
        assert!(
            !game.players[0]
                .denounced_until
                .get(&1)
                .is_some_and(|until| *until > game.turn),
            "remote global power must not begin the diplomatic war countdown"
        );

        let staging: Vec<Pos> = game
            .wdisk(objective, 7)
            .into_iter()
            .filter(|position| {
                (3..=5).contains(&game.wdist(*position, objective))
                    && game.city_at(*position).is_none()
            })
            .take(army.len())
            .collect();
        assert_eq!(staging.len(), army.len());
        for (unit, position) in army.iter().zip(staging) {
            let tile = game.map.tiles.get_mut(&position).unwrap();
            tile.terrain = crate::name!("grassland");
            tile.feature = None;
            tile.hills = false;
            tile.owner_city = None;
            game.units.get_mut(unit).unwrap().pos = position;
        }
        assert!(ai.campaign_staged_for_war(&game, 0, 1, objective, true));

        ai.advanced_diplomacy(&mut game, 0, &plan);
        assert!(
            game.players[0]
                .denounced_until
                .get(&1)
                .is_some_and(|until| *until > game.turn),
            "the staged capture force should begin the formal-war countdown"
        );

        // A terminal threat must use the already-staged force even when the
        // rival's total military is too large for an elective war. Keep the
        // reinforcements away from the objective so this isolates the global
        // readiness gate from the local staging test above.
        game.players[0].denounced_until.remove(&1);
        game.players[1].science_projects.extend([
            "launch_earth_satellite".to_string(),
            "launch_moon_landing".to_string(),
            "launch_mars_colony".to_string(),
            "exoplanet_expedition".to_string(),
        ]);
        let rival_muster = game
            .map
            .tiles
            .keys()
            .copied()
            .find(|position| {
                game.wdist(*position, objective) >= 10 && game.city_at(*position).is_none()
            })
            .expect("test map has a remote rival muster position");
        for _ in 0..12 {
            game.spawn_test_unit("swordsman", 1, rival_muster);
        }
        assert!(
            game.military_power(0) <= game.military_power(1) * 1.32 + 12.0,
            "the usual elective-war margin must reject this outnumbered army"
        );

        // The live bridge must not spend its final campaign window on the
        // same urgent fallback. Timed attacks already reserve this scaled
        // runway, so the direct path must hold even though urgency normally
        // waives the power gate.
        let mut endgame = game.clone();
        let reserve = endgame.standard_duration(TIMED_WAR_ENDGAME_RESERVE);
        endgame.turn = endgame.max_turns.saturating_sub(reserve);
        let mut guarded = AdvancedAi::targeting(VictoryTarget::Domination);
        guarded.enable_live_bridge();
        assert!(guarded.urgent_victory_threat(&endgame, 1));
        guarded.advanced_diplomacy(&mut endgame, 0, &plan);
        assert!(
            !endgame.is_at_war(0, 1),
            "the live direct fallback must reserve enough turns to turn a declaration into a capture"
        );

        ai.advanced_diplomacy(&mut game, 0, &plan);
        assert!(
            game.is_at_war(0, 1),
            "a staged counterforce must immediately deny a terminal science threat"
        );
    }

    #[test]
    fn war_opening_waits_for_formal_war_but_interrupts_for_imminent_victory() {
        let mut game = Game::new_full(2, 24, 16, 712, 300, 0, false);
        // A denunciation needs somebody to denounce.
        game.record_contact(0, 1);
        game.current = 0;
        game.turn = 60;
        let ai = AdvancedAi::new();

        assert_eq!(
            ai.preferred_war_opening(&game, 0, 1),
            Some(Action::Denounce { player: 1 })
        );
        game.apply(0, &Action::Denounce { player: 1 }).unwrap();
        game.turn = 64;
        assert_eq!(ai.preferred_war_opening(&game, 0, 1), None);
        game.turn = 65;
        assert_eq!(
            ai.preferred_war_opening(&game, 0, 1),
            Some(Action::DeclareWarWithCasusBelli {
                player: 1,
                casus_belli: "formal_war".to_string(),
            })
        );

        let mut emergency = Game::new_full(2, 24, 16, 713, 300, 0, false);
        emergency.record_contact(0, 1);
        emergency.current = 0;
        emergency.turn = 60;
        emergency.players[1]
            .science_projects
            .insert("exoplanet_expedition".to_string());
        assert_eq!(
            ai.preferred_war_opening(&emergency, 0, 1),
            Some(Action::DeclareWar { player: 1 })
        );

        let mut religious = Game::new_full(4, 24, 16, 714, 300, 0, false);
        for pid in 0..4 {
            for other in pid + 1..4 {
                religious.record_contact(pid, other);
            }
        }
        for pid in 0..4 {
            religious.current = pid;
            let settler = religious
                .player_unit_ids(pid)
                .into_iter()
                .find(|unit| religious.units[unit].kind == "settler")
                .unwrap();
            religious.apply(pid, &Action::FoundCity { unit: settler }).unwrap();
        }
        religious.current = 0;
        religious.turn = 60;
        religious.players[1].religion = Some("Runaway Faith".to_string());
        for owner in [1, 2, 3] {
            let city = religious.player_city_ids(owner)[0];
            religious
                .cities
                .get_mut(&city)
                .unwrap()
                .pressure
                .insert("Runaway Faith".to_string(), 1_000.0);
        }
        assert_eq!(
            ai.preferred_war_opening(&religious, 0, 1),
            Some(Action::DeclareWar { player: 1 }),
            "a religious match point cannot spend five turns preparing a formal war"
        );
    }

    #[test]
    fn strategic_plan_is_stable_inside_assessment_window() {
        let mut g = Game::new(2, 24, 16, 72, 30, 0);
        let mut ai = AdvancedAi::new();
        ai.take_turn(&mut g, 0);
        let first = ai.current_plan().unwrap().clone();
        assert!(!ai.plan_stale(&g, 0));
        assert_eq!(ai.current_plan(), Some(&first));
    }

    #[test]
    fn surprise_wars_and_imminent_victories_interrupt_the_planning_window() {
        let mut game = Game::new_full(3, 30, 18, 721, 300, 0, false);
        for pid in 0..3 {
            let settler = game
                .player_unit_ids(pid)
                .into_iter()
                .find(|unit| game.units[unit].kind == "settler")
                .unwrap();
            game.current = pid;
            game.apply(pid, &Action::FoundCity { unit: settler })
                .unwrap();
        }
        game.current = 0;
        game.turn = 190;
        for rival in 1..game.players.len() {
            game.record_contact(0, rival);
        }
        let mut ai = AdvancedAi::new();
        ai.plan = Some(StrategicPlan {
            strategy: GrandStrategy::Expansion,
            target_player: Some(2),
            target_city: None,
            threatened_city: None,
            desired_cities: 4,
            assessed_turn: game.turn,
            rush: false,
        });
        assert!(!ai.plan_stale(&game, 0));

        game.at_war.insert((0, 1));
        assert!(ai.plan_stale(&game, 0), "a surprise war must replan now");

        game.at_war.clear();
        ai.plan.as_mut().unwrap().target_player = Some(1);
        game.players[2].science_projects.extend([
            "launch_earth_satellite".to_string(),
            "launch_moon_landing".to_string(),
            "launch_mars_colony".to_string(),
            "exoplanet_expedition".to_string(),
        ]);
        game.players[2].exoplanet_distance = 42.0;
        assert!(
            ai.plan_stale(&game, 0),
            "an imminent rival victory must replan now"
        );
    }

    #[test]
    fn recovery_requires_material_local_danger_and_ends_when_it_clears() {
        let mut game = Game::new_full(2, 30, 18, 7_218, 300, 0, false);
        for pid in 0..2 {
            game.current = pid;
            let settler = game
                .player_unit_ids(pid)
                .into_iter()
                .find(|unit| game.units[unit].kind == "settler")
                .unwrap();
            game.apply(pid, &Action::FoundCity { unit: settler })
                .unwrap();
        }
        for unit in game.units.keys().copied().collect::<Vec<_>>() {
            game.remove_unit(unit);
        }
        game.current = 0;
        game.turn = 90;
        game.at_war.insert((0, 1));
        let home = game.player_city_ids(0)[0];
        let home_pos = game.cities[&home].pos;
        let intruder_pos = game
            .wdisk(home_pos, 6)
            .into_iter()
            .find(|position| {
                game.wdist(*position, home_pos) == 3 && game.city_at(*position).is_none()
            })
            .unwrap();
        let observer_pos = game
            .nbrs(intruder_pos)
            .into_iter()
            .find(|position| {
                *position != home_pos
                    && game.city_at(*position).is_none()
                    && game.units_at(*position).is_empty()
            })
            .unwrap();
        let far_pos = game
            .map
            .tiles
            .keys()
            .copied()
            .find(|position| {
                game.wdist(*position, home_pos) >= 9 && game.city_at(*position).is_none()
            })
            .unwrap();
        for position in [intruder_pos, observer_pos, far_pos] {
            let tile = game.map.tiles.get_mut(&position).unwrap();
            tile.terrain = crate::name!("grassland");
            tile.feature = None;
            tile.hills = false;
        }
        game.spawn_test_unit("scout", 0, observer_pos);
        assert!(
            game.player_can_see(0, intruder_pos),
            "the staged attackers must be visible to the defender"
        );
        for _ in 0..4 {
            game.spawn_test_unit("modern_armor", 0, far_pos);
        }
        let mut intruders = vec![game.spawn_test_unit("warrior", 1, intruder_pos)];
        let mut ai = AdvancedAi::new();

        assert_eq!(
            ai.threatened_city(&game, 0),
            None,
            "one losing contact in the outer radius must not recall a dominant army"
        );
        assert_eq!(ai.assess(&game, 0).strategy, GrandStrategy::Conquest);

        for _ in 0..4 {
            intruders.push(game.spawn_test_unit("modern_armor", 1, intruder_pos));
        }
        assert_eq!(ai.threatened_city(&game, 0), Some(home));
        let recovery = ai.assess(&game, 0);
        assert_eq!(recovery.strategy, GrandStrategy::Recovery);
        assert_eq!(recovery.threatened_city, Some(home));

        ai.plan = Some(recovery);
        for unit in intruders {
            game.remove_unit(unit);
        }
        assert!(
            ai.plan_stale(&game, 0),
            "clearing the emergency must resume the campaign immediately"
        );
        assert_eq!(ai.assess(&game, 0).strategy, GrandStrategy::Conquest);
    }

    #[test]
    fn religious_denial_triggers_with_one_unconverted_civilization() {
        let mut game = Game::new_full(4, 30, 18, 7_215, 300, 0, false);
        for pid in 0..4 {
            game.current = pid;
            let settler = game
                .player_unit_ids(pid)
                .into_iter()
                .find(|unit| game.units[unit].kind == "settler")
                .unwrap();
            game.apply(pid, &Action::FoundCity { unit: settler })
                .unwrap();
        }
        game.current = 0;
        game.players[1].religion = Some("Rival Faith".to_string());
        for owner in [1, 2, 3] {
            let city = game.player_city_ids(owner)[0];
            game.cities
                .get_mut(&city)
                .unwrap()
                .pressure
                .insert("Rival Faith".to_string(), 1_000.0);
        }

        let ai = AdvancedAi::new();
        let pressure = ai.rival_victory_pressure(&game, 1);
        assert_eq!(pressure.strategy, GrandStrategy::Religion);
        assert_eq!(pressure.progress, 75);
        assert_eq!(
            ai.victory_denial(&game, 0),
            Some((1, GrandStrategy::Conquest))
        );

        // The `advanced_blind_to_leaders` ablation is silent on the same
        // position, and silent about its urgency, while reading the identical
        // pressure. An ablation that changed what the empire *sees* would
        // measure something other than the response.
        let mut blind = AdvancedAi::new();
        blind.deny_leaders = false;
        assert_eq!(blind.rival_victory_pressure(&game, 1).progress, 75);
        assert_eq!(blind.victory_denial(&game, 0), None);
        assert!(!blind.urgent_victory_threat(&game, 1));
        assert!(ai.urgent_victory_threat(&game, 1));
    }

    /// The site score is silent about barbarians and about being out of
    /// reach of your own cities. Off, it stays silent; on, both discount the
    /// site and neither can ever raise it.
    #[test]
    fn a_defensible_site_score_discounts_camps_and_isolation() {
        let mut game = Game::new_full(2, 30, 18, 7_741, 300, 0, false);
        let settler = game
            .player_unit_ids(0)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .expect("every empire starts with a settler");
        let home = game.units[&settler].pos;
        game.apply(0, &Action::FoundCity { unit: settler }).unwrap();

        // Somewhere well outside the founding city's support radius.
        let far = game
            .map
            .tiles
            .keys()
            .copied()
            .filter(|pos| game.map.get(*pos).is_some_and(|t| !game.rules.is_water(t)))
            .find(|pos| game.wdist(home, *pos) > 8)
            .expect("the map is larger than the support radius");

        let mut plain = AdvancedAi::new();
        plain.settlement_safety = false;
        let mut weighed = AdvancedAi::new();
        weighed.settlement_safety = false;
        weighed.defensible_sites = true;
        assert!(
            !plain.defensible_sites,
            "the measurement flag ships off"
        );

        // With no camp anywhere, only the isolation term can fire.
        assert!(game.barb_camps.is_empty());
        assert_eq!(weighed.defensibility(&game, 0, home), 0.0);
        assert!(
            weighed.defensibility(&game, 0, far) < 0.0,
            "a site out of reach of every friendly city is discounted"
        );
        assert_eq!(
            plain.settle_value(&game, 0, far),
            weighed.settle_value(&game, 0, far) - weighed.defensibility(&game, 0, far),
            "the flag adds exactly the defensibility term and nothing else"
        );

        // A camp beside the home tile discounts it; the untreated agent
        // scores that site exactly as it did before, which is the gap this
        // flag exists to measure.
        let before = plain.settle_value(&game, 0, home);
        let camp = *game
            .nbrs(home)
            .iter()
            .find(|pos| {
                game.map
                    .get(**pos)
                    .is_some_and(|t| !game.rules.is_water(t))
            })
            .expect("a founded city has a passable neighbour");
        game.barb_camps.insert(camp, 0);
        assert!(
            weighed.defensibility(&game, 0, home) < 0.0,
            "a camp one tile away discounts the site"
        );
        assert_eq!(
            plain.settle_value(&game, 0, home),
            before,
            "and the shipped score does not notice the camp at all"
        );
        assert!(
            weighed.settle_value(&game, 0, home) < before,
            "while the weighed score does"
        );
    }

    #[test]
    fn settlement_site_score_prioritizes_growth_water_and_future_districts() {
        let game = Game::new_full(2, 30, 18, 8_114, 120, 0, false);
        let center = game
            .map
            .tiles
            .keys()
            .copied()
            .find(|position| {
                game.wdisk(*position, 3)
                    .into_iter()
                    .all(|near| game.map.get(near).is_some())
                    && game.map.get(*position).is_some_and(|tile| {
                        !game.rules.is_water(tile) && game.rules.is_passable(tile)
                    })
            })
            .expect("the test map has an interior land tile");
        let food_tile = game
            .nbrs(center)
            .into_iter()
            .find(|position| game.map.get(*position).is_some())
            .expect("the center has a neighbor");
        let mut food = game.clone();
        let mut production = game.clone();
        for candidate in [&mut food, &mut production] {
            for position in candidate.wdisk(center, 1) {
                if let Some(tile) = candidate.map.tiles.get_mut(&position) {
                    tile.terrain = Name::new("desert");
                    tile.feature = None;
                    tile.resource = None;
                    tile.river_edges = [false; 6];
                }
            }
        }
        food.map.tiles.get_mut(&food_tile).unwrap().terrain = Name::new("grassland");
        production.map.tiles.get_mut(&food_tile).unwrap().terrain = Name::new("plains");
        let ai = AdvancedAi::new();
        assert!(
            ai.settle_value(&food, 0, center) > ai.settle_value(&production, 0, center) + 1.0,
            "early food should beat the same tile's production-only alternative"
        );

        let mut freshwater = food.clone();
        assert!(freshwater.map.set_river_edge(center, food_tile, true));
        assert!(
            ai.settle_value(&freshwater, 0, center) > ai.settle_value(&food, 0, center) + 10.0,
            "fresh water should be a material founding advantage"
        );

        let mut district = game.clone();
        for position in district.wdisk(center, 3) {
            if let Some(tile) = district.map.tiles.get_mut(&position) {
                tile.terrain = Name::new("plains");
                tile.feature = None;
                tile.resource = None;
                tile.river_edges = [false; 6];
            }
        }
        let district_site = district
            .nbrs(center)
            .into_iter()
            .find(|position| {
                district.map.get(*position).is_some_and(|tile| {
                    !district.rules.is_water(tile) && district.rules.is_passable(tile)
                })
            })
            .expect("the normalized ring has a district site");
        let mountain = district
            .nbrs(district_site)
            .into_iter()
            .find(|position| {
                *position != center
                    && district.wdist(center, *position) <= 3
                    && district.map.get(*position).is_some()
            })
            .expect("the district site has an adjacency tile");
        let without_mountain = ai.settlement_adjacency_value(&district, 0, center);
        district.map.tiles.get_mut(&mountain).unwrap().terrain = Name::new("mountain");
        let with_mountain = ai.settlement_adjacency_value(&district, 0, center);
        assert!(
            with_mountain > without_mountain + 0.1,
            "future campus adjacency should survive into the founding score: \
             with={with_mountain}, without={without_mountain}"
        );
    }

    #[test]
    fn settlement_atlas_parallel_misses_match_uncached_values_and_invalidate_on_map_write() {
        let mut game = Game::new_full(1, 60, 40, 8_123, 120, 0, false);
        let positions = game
            .map
            .tiles
            .keys()
            .copied()
            .filter(|position| {
                game.map
                    .get(*position)
                    .is_some_and(|tile| !game.rules.is_water(tile) && game.rules.is_passable(tile))
            })
            .take(48)
            .collect::<Vec<_>>();
        assert_eq!(positions.len(), 48, "the fixture needs a wide score batch");

        let visible = game.player_vision_now(0);
        let units = game
            .units
            .values()
            .filter(|unit| game.sees(&visible, unit.pos) && game.unit_visible_to(unit.id, 0))
            .map(|unit| unit.id)
            .collect();
        let mut ai = AdvancedAi::new();
        ai.battlefront_frame = Some(BattlefrontFrame { visible, units });
        ai.work_pool = Some(Arc::new(WorkPool::new(4)));

        let expected = positions
            .iter()
            .map(|position| ai.settlement_static_value_uncached(&game, 0, *position))
            .collect::<Vec<_>>();
        let cloned_game = game.clone();
        let cloned = positions
            .iter()
            .map(|position| ai.settlement_static_value_uncached(&cloned_game, 0, *position))
            .collect::<Vec<_>>();
        assert_eq!(cloned, expected, "a worker game clone must preserve static site values");
        let cloned_ai = ai.clone();
        let cloned_controller = positions
            .iter()
            .map(|position| cloned_ai.settlement_static_value_uncached(&game, 0, *position))
            .collect::<Vec<_>>();
        assert_eq!(cloned_controller, expected, "a worker controller clone must preserve static site values");
        ai.settlement_atlas_values(&game, 0, &positions);
        let actual = positions
            .iter()
            .map(|position| ai.settlement_atlas_value(&game, 0, *position))
            .collect::<Vec<_>>();
        assert_eq!(actual, expected, "parallel atlas scoring must be bit-identical");
        assert_eq!(ai.settlement_atlas.borrow().values.len(), positions.len());

        let changed = positions[0];
        game.map.tiles.get_mut(&changed).unwrap().terrain = Name::new("desert");
        let uncached = ai.settlement_static_value_uncached(&game, 0, changed);
        let refreshed = ai.settlement_atlas_value(&game, 0, changed);
        assert_eq!(refreshed, uncached, "a map epoch change must refresh the atlas");
    }

    fn settlement_forecast_fixture(seed: u64) -> (Game, Pos, Vec<Pos>, Vec<Pos>) {
        let mut game = Game::new_full(1, 24, 16, seed, 120, 0, false);
        let center = game
            .map
            .tiles
            .keys()
            .copied()
            .find(|position| {
                game.wdisk(*position, 2).len() == 19
                    && game.map.get(*position).is_some_and(|tile| {
                        !game.rules.is_water(tile) && game.rules.is_passable(tile)
                    })
            })
            .expect("forecast fixture has an interior land tile");
        for position in game.wdisk(center, 2) {
            let tile = game.map.tiles.get_mut(&position).unwrap();
            tile.terrain = crate::name!("desert");
            tile.feature = None;
            tile.hills = false;
            tile.resource = None;
            tile.improvement = None;
            tile.pillaged = false;
            tile.district = None;
            tile.district_foundation = None;
            tile.wonder = None;
            tile.owner_city = None;
            tile.river_edges = [false; 6];
        }
        let mut first = game.nbrs(center).to_vec();
        first.sort_unstable();
        let mut second = game
            .wdisk(center, 2)
            .into_iter()
            .filter(|position| game.wdist(center, *position) == 2)
            .collect::<Vec<_>>();
        second.sort_unstable();
        (game, center, first, second)
    }

    fn shape_forecast_tile(
        game: &mut Game,
        position: Pos,
        terrain: &str,
        hills: bool,
        resource: Option<&str>,
    ) {
        let tile = game.map.tiles.get_mut(&position).unwrap();
        tile.terrain = Name::new(terrain);
        tile.hills = hills;
        tile.resource = resource.map(Name::new);
    }

    #[test]
    fn settlement_forecast_values_the_actual_first_four_jobs_across_both_rings() {
        let (mut game, center, first, second) = settlement_forecast_fixture(8_116);
        shape_forecast_tile(&mut game, first[0], "grassland", false, Some("rice"));
        shape_forecast_tile(&mut game, first[1], "plains", true, None);
        shape_forecast_tile(&mut game, second[0], "grassland", false, Some("horses"));
        shape_forecast_tile(&mut game, second[1], "grassland", true, None);
        assert!(game.map.set_river_edge(center, first[5], true));

        let forecast = AdvancedAi::new().settlement_growth_forecast(&game, 0, center);
        assert_eq!(forecast.reached_population, 4);
        assert_eq!(forecast.worked.len(), 4);
        assert_eq!(forecast.worked[0].pos, first[0]);
        assert_eq!(forecast.worked[0].ring, 1);
        assert!(forecast.worked.iter().any(|tile| tile.ring == 2));
        assert!(
            forecast.turns_to_four.is_some_and(|turns| turns < 30.0),
            "the four useful jobs should grow the city promptly: {forecast:?}"
        );
    }

    #[test]
    fn settlement_forecast_prefers_four_sustainable_jobs_to_one_spike() {
        let (mut spike, center, first, second) = settlement_forecast_fixture(8_117);
        let mut broad = spike.clone();
        shape_forecast_tile(&mut spike, first[0], "grassland", false, Some("rice"));
        for position in [first[0], first[1], second[0], second[1]] {
            shape_forecast_tile(&mut broad, position, "grassland", true, None);
        }
        assert!(spike.map.set_river_edge(center, first[5], true));
        assert!(broad.map.set_river_edge(center, first[5], true));

        let ai = AdvancedAi::new();
        let spike = ai.settlement_growth_forecast(&spike, 0, center);
        let broad = ai.settlement_growth_forecast(&broad, 0, center);
        assert!(spike.reached_population < 4, "one tile should stall: {spike:?}");
        assert_eq!(broad.reached_population, 4, "four jobs should mature: {broad:?}");
        assert!(
            broad.score > spike.score,
            "a useful four-pop city should outrank a one-tile mirage: broad={broad:?}, spike={spike:?}"
        );
    }

    #[test]
    fn settlement_forecast_delays_second_ring_jobs_and_models_water_housing() {
        let (mut game, center, first, second) = settlement_forecast_fixture(8_118);
        shape_forecast_tile(&mut game, first[0], "grassland", false, None);
        shape_forecast_tile(&mut game, second[0], "grassland", false, Some("citrus"));
        let forecast = AdvancedAi::new().settlement_growth_forecast(&game, 0, center);
        assert_eq!(
            forecast.worked.first().map(|tile| tile.pos),
            Some(first[0]),
            "the rich second-ring tile is not owned for the first citizen"
        );
        assert_eq!(AdvancedAi::settlement_base_housing(&game, center), 2.0);

        let mut coast = game.clone();
        shape_forecast_tile(&mut coast, first[5], "coast", false, None);
        assert_eq!(AdvancedAi::settlement_base_housing(&coast, center), 3.0);

        let mut fresh = game;
        assert!(fresh.map.set_river_edge(center, first[5], true));
        assert_eq!(AdvancedAi::settlement_base_housing(&fresh, center), 5.0);
    }

    /// The defect and the repair of issue #1378 in one shape: a plain
    /// breadbasket against the same site with the Matterhorn on its first
    /// ring. Live run `civvis-20260807T202450Z` t93 founded a 64.6-point
    /// breadbasket while `FEATURE_MATTERHORN` stood revealed inside the
    /// candidate radius, because the shipped scorer prices a wonder only
    /// through the worked tiles it can forecast. With the treatment the
    /// wonder's modeled sheet (appeal 2, +1 culture onto the ring) is credited
    /// and the wonder ring outbids the breadbasket; held off, the shipped
    /// score is reproduced exactly.
    #[test]
    fn a_wonder_ring_site_outbids_the_breadbasket_only_when_the_bridge_prices_it() {
        let (mut breadbasket, center, first, second) = settlement_forecast_fixture(8_120);
        for position in &first {
            shape_forecast_tile(&mut breadbasket, *position, "grassland", false, None);
        }
        let mut wonder_ring = breadbasket.clone();
        // The breadbasket adds a production hill on its second ring; the
        // wonder site gives up a workable grassland for an impassable mountain
        // carrying the Matterhorn — strictly worse ground until the wonder
        // itself is priced.
        shape_forecast_tile(&mut breadbasket, second[0], "grassland", true, None);
        {
            let tile = wonder_ring.map.tiles.get_mut(&first[0]).unwrap();
            tile.terrain = Name::new("mountain");
            tile.hills = false;
            tile.feature = Some(Name::new("matterhorn"));
            tile.resource = None;
        }

        let shipped = AdvancedAi::new();
        let shipped_bread = shipped.settle_value(&breadbasket, 0, center);
        let shipped_wonder = shipped.settle_value(&wonder_ring, 0, center);
        assert!(
            shipped_bread > shipped_wonder,
            "the defect: without the treatment the breadbasket outbids the wonder \
             ring (bread {shipped_bread:.1} vs wonder {shipped_wonder:.1})"
        );

        let mut bridged = AdvancedAi::new();
        bridged.enable_wonder_ring_settle_value();
        let priced_wonder = bridged.settle_value(&wonder_ring, 0, center);
        let priced_bread = bridged.settle_value(&breadbasket, 0, center);
        assert!(
            priced_wonder > priced_bread,
            "the repair: with the treatment the wonder ring outbids the \
             breadbasket (wonder {priced_wonder:.1} vs bread {priced_bread:.1})"
        );

        // The credit is the Matterhorn's own modeled sheet — appeal 2 plus one
        // hex ring of its +1 culture projection at the shared culture weight —
        // not a flat constant.
        let sheet = 2.0 * NATURAL_WONDER_APPEAL_WEIGHT + 1.2 * NATURAL_WONDER_RING_TILES;
        assert!(
            (priced_wonder - shipped_wonder - sheet).abs() < 1e-9,
            "the wonder credit must equal the modeled sheet: got {:.3}, sheet {sheet:.3}",
            priced_wonder - shipped_wonder
        );
        // A site with no wonder in its work radius gains nothing from the
        // treatment, and holding it off reproduces the shipped score exactly.
        assert_eq!(priced_bread, shipped_bread);
        bridged.disable_wonder_ring_settle_value();
        assert_eq!(bridged.settle_value(&wonder_ring, 0, center), shipped_wonder);
    }

    /// Pricing the ring must not price the summit. A PASSABLE wonder — the
    /// Pantanal walks like ordinary grassland — is the sharp case: only
    /// `tile_is_natural_wonder`, not impassability, keeps the candidate out,
    /// however large the credit its own ring now carries.
    #[test]
    fn the_priced_wonder_ring_still_refuses_to_settle_on_the_wonder() {
        let (mut game, center, first, _second) = settlement_forecast_fixture(8_121);
        for position in &first {
            shape_forecast_tile(&mut game, *position, "grassland", false, None);
        }
        {
            let tile = game.map.tiles.get_mut(&first[0]).unwrap();
            tile.terrain = Name::new("grassland");
            tile.feature = Some(Name::new("pantanal"));
        }
        let mut bridged = AdvancedAi::new();
        bridged.enable_wonder_ring_settle_value();
        let sites = bridged.settle_sites(&game, 0, center, 4);
        assert!(
            sites.iter().all(|(pos, _)| *pos != first[0]),
            "the wonder tile itself must never be offered as a founding site"
        );
        assert!(
            sites.iter().any(|(pos, _)| *pos == center),
            "while the site beside it stays on the menu"
        );
    }

    #[test]
    fn a_retarget_does_not_resolve_a_settler_delay() {
        // ⚠ The existing release test sets `settler_blocked_turns` by hand, so it
        // passes whether or not the counter can ever REACH the threshold in play.
        // This pins the reset rule that decides whether it does.
        //
        // Measured on live run `civvis-20260804T011632Z`: a settler stranded 84
        // turns at full movement while retargeting every turn, so the old
        // `advanced = retargeted || closer` reset cleared the counter on each of
        // them. No settler was ordered for the last 128 turns of that run while
        // `desired_cities` was 6-7 and the empire held 5.
        assert!(
            !AdvancedAi::settler_delay_is_resolved(true, false),
            "a retarget with no progress must NOT clear the empire-wide counter"
        );
        assert!(
            !AdvancedAi::settler_delay_is_resolved(true, true),
            "closer to a DIFFERENT target is not progress on the delay that stalled \
             the pipeline; the strand is what the counter measures"
        );
        assert!(
            AdvancedAi::settler_delay_is_resolved(false, true),
            "genuine progress toward the same target resolves the delay"
        );
        assert!(
            !AdvancedAi::settler_delay_is_resolved(false, false),
            "same target, no progress: still blocked"
        );
    }

    /// The live seat walks two Settlers at once from two cities on, while the
    /// empire is at least two seats short; every default constructor and the
    /// frozen anchor keep the one-at-a-time gate in both settler routes.
    #[test]
    fn parallel_settlers_open_a_second_pipeline_slot() {
        let mut ai = AdvancedAi::new();
        assert!(!ai.parallel_settlers && !ai.base.parallel_settlers, "off unless the bridge asks");
        assert_eq!(ai.settler_in_flight_allowed(8, 3, 1), 1);
        assert!(!AdvancedAi::legacy().parallel_settlers);
        assert!(!AdvancedAi::legacy().base.parallel_settlers);

        ai.enable_parallel_settlers();
        assert!(ai.parallel_settlers && ai.base.parallel_settlers, "both routes see the flag");
        assert_eq!(ai.settler_in_flight_allowed(8, 3, 1), 2, "three cities, one walker, five short");
        assert_eq!(ai.settler_in_flight_allowed(8, 2, 0), 2, "two cities open the second slot");
        assert_eq!(ai.settler_in_flight_allowed(8, 1, 1), 1, "one city keeps a single walker");
        assert_eq!(ai.settler_in_flight_allowed(3, 2, 0), 1, "one seat short: one walker covers it");
        assert_eq!(ai.settler_in_flight_allowed(4, 2, 1), 1, "the walker already covers the seat but one");
        assert_eq!(ai.settler_in_flight_allowed(5, 2, 1), 2);
    }

    #[test]
    fn a_repeatedly_blocked_settler_releases_only_the_next_missing_slot() {
        let mut ai = AdvancedAi::new();
        ai.settler_blocked_turns.insert(41, 2);
        assert_eq!(ai.settler_in_flight_allowed(3, 1, 1), 1);
        ai.settler_blocked_turns.insert(41, 3);
        assert_eq!(ai.settler_in_flight_allowed(3, 1, 1), 2);
        assert_eq!(
            ai.settler_in_flight_allowed(2, 1, 1),
            1,
            "a Settler already covers the final missing city"
        );

        let mut legacy = AdvancedAi::legacy();
        legacy.settler_blocked_turns.insert(41, 99);
        assert_eq!(legacy.settler_in_flight_allowed(4, 1, 1), 1);
    }

    #[test]
    fn advanced_settler_refuses_a_visible_direct_attack_tile() {
        let mut game = Game::new_full(2, 30, 18, 8_115, 120, 0, false);
        let initial = game
            .player_unit_ids(0)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .expect("player zero starts with a settler");
        let home = game.units[&initial].pos;
        let origin = game
            .map
            .tiles
            .keys()
            .copied()
            .find(|position| {
                game.wdist(home, *position) > 8
                    && game.map.get(*position).is_some_and(|tile| {
                        !game.rules.is_water(tile) && game.rules.is_passable(tile)
                    })
                    && game
                        .units
                        .values()
                        .all(|unit| unit.owner != 0 || game.wdist(unit.pos, *position) > 2)
            })
            .expect("the map has a quiet land origin");
        let settler = game.spawn_test_unit("settler", 0, origin);
        let target = game
            .wdisk(origin, 2)
            .into_iter()
            .find(|position| {
                game.wdist(origin, *position) == 2
                    && game.map.get(*position).is_some_and(|tile| {
                        !game.rules.is_water(tile) && game.rules.is_passable(tile)
                    })
                    && game.route_step(settler, *position, 0).is_some()
            })
            .expect("the start has a reachable two-tile target");
        let next = game
            .route_step(settler, target, 0)
            .expect("the target has a first route step");
        let threat = game
            .nbrs(next)
            .into_iter()
            .find(|position| {
                *position != home
                    && *position != target
                    && game.units_at(*position).is_empty()
                    && game.map.get(*position).is_some_and(|tile| {
                        !game.rules.is_water(tile) && game.rules.is_passable(tile)
                    })
            })
            .expect("the route has a visible attack square");
        let enemy = game.spawn_test_unit("warrior", 1, threat);
        game.at_war.insert((0, 1));
        let ai = AdvancedAi::new();
        let visible = ai.battlefront_visibility(&game, 0);
        let planned_risk = ai.settlement_tile_risk(&game, 0, Some(settler), next, &visible);
        assert!(game.sees(&visible, threat));
        assert!(
            planned_risk > SETTLER_STEP_RISK_LIMIT,
            "the visible warrior should make the planned tile obviously unsafe: \
             risk={planned_risk}, distance={}, at_war={}",
            game.wdist(threat, next),
            game.is_at_war(0, 1)
        );
        let moving = ai;
        let _ = moving.settler_step_toward_safe(&mut game, 0, settler, target);
        assert_ne!(
            game.units[&settler].pos, next,
            "a settler must not step into a visible direct attack envelope"
        );
        assert!(game.units.contains_key(&enemy));
    }

