    #[test]
    fn strategic_plan_denies_an_imminent_victory_instead_of_farming_a_weak_rival() {
        let establish_capitals = |game: &mut Game| {
            for pid in 0..3 {
                let settler = game
                    .player_unit_ids(pid)
                    .into_iter()
                    .find(|unit| game.units[unit].kind == "settler")
                    .unwrap();
                game.current = pid;
                game.apply(pid, &Action::FoundCity { unit: settler })
                    .unwrap();
            }
            game.current = 0;
            game.turn = 190;
            for rival in 1..game.players.len() {
                game.record_contact(0, rival);
            }
        };

        let mut science = Game::new_full(3, 36, 22, 761, 300, 0, false);
        establish_capitals(&mut science);
        science.players[2].science_projects.extend([
            "launch_earth_satellite".to_string(),
            "launch_moon_landing".to_string(),
            "launch_mars_colony".to_string(),
            "exoplanet_expedition".to_string(),
        ]);
        science.players[2].exoplanet_distance = 42.0;
        let ai = AdvancedAi::new();
        let pressure = ai.rival_victory_pressure(&science, 2);
        assert_eq!(pressure.strategy, GrandStrategy::Science);
        assert!(pressure.progress >= 95);
        let plan = ai.assess(&science, 0);
        assert_eq!(plan.strategy, GrandStrategy::Conquest);
        assert_eq!(plan.target_player, Some(2));

        let mut culture = Game::new_full(3, 36, 22, 762, 300, 0, false);
        establish_capitals(&mut culture);
        culture.players[1].tourism_lifetime = 300_000.0;
        culture.players[0].culture_lifetime = 100.0;
        culture.players[2].culture_lifetime = 100.0;
        let pressure = ai.rival_victory_pressure(&culture, 1);
        assert_eq!(pressure.strategy, GrandStrategy::Culture);
        assert_eq!(pressure.progress, 100);
        let plan = ai.assess(&culture, 0);
        assert_eq!(plan.strategy, GrandStrategy::Culture);
        assert_eq!(plan.target_player, Some(1));
    }

    #[test]
    fn science_denial_starts_when_the_final_expedition_launches() {
        let mut game = Game::new_full(3, 36, 22, 76_120, 300, 0, false);
        for pid in 0..3 {
            let settler = game
                .player_unit_ids(pid)
                .into_iter()
                .find(|unit| game.units[unit].kind == "settler")
                .unwrap();
            game.current = pid;
            game.apply(pid, &Action::FoundCity { unit: settler })
                .unwrap();
        }
        game.current = 0;
        game.turn = 190;
        for rival in 1..game.players.len() {
            game.record_contact(0, rival);
        }
        game.players[2]
            .science_projects
            .insert("exoplanet_expedition".to_string());

        let ai = AdvancedAi::new();
        let pressure = ai.rival_victory_pressure(&game, 2);
        assert_eq!(pressure.strategy, GrandStrategy::Science);
        assert_eq!(pressure.progress, 78);
        assert_eq!(
            ai.victory_denial(&game, 0),
            Some((2, GrandStrategy::Conquest)),
            "the final launch must leave the defender time to begin its counter-campaign"
        );
        let plan = ai.assess(&game, 0);
        assert_eq!(plan.strategy, GrandStrategy::Conquest);
        assert_eq!(plan.target_player, Some(2));

        // The three response shapes on one position, so the arms cannot
        // silently converge: ship declares, `counter_in_lane` races the same
        // rival, `counter_stand_down` lets this threat pass. All three read
        // the identical pressure, so what separates them is the answer and
        // never the perception.
        let mut in_lane = AdvancedAi::new();
        in_lane.counter_in_lane = true;
        assert_eq!(
            in_lane.victory_denial(&game, 0),
            Some((2, GrandStrategy::Science))
        );

        let mut stand_down = AdvancedAi::new();
        stand_down.counter_stand_down = true;
        assert_eq!(stand_down.victory_denial(&game, 0), None);
        assert_eq!(stand_down.rival_victory_pressure(&game, 2).progress, 78);
    }

    /// ★★★★ In the last quarter the shipped score term reads whoever leads on
    /// score as "close to winning", and the stock counter is a war: run
    /// civvis-20260816T110555Z declared on a rival with twice its score at
    /// t211 and lost a city. See `counter_in_lane`. On the live seat the same
    /// alarm asks for the Expansion lane; the stock controller still declares.
    #[test]
    fn the_live_seat_races_the_score_leader_instead_of_declaring_on_it() {
        let mut game = Game::new_full(3, 36, 22, 76_121, 300, 0, false);
        for pid in 0..3 {
            let settler = game
                .player_unit_ids(pid)
                .into_iter()
                .find(|unit| game.units[unit].kind == "settler")
                .unwrap();
            game.current = pid;
            game.apply(pid, &Action::FoundCity { unit: settler })
                .unwrap();
        }
        game.current = 0;
        game.turn = 240; // the last quarter of 300
        for rival in 1..game.players.len() {
            game.record_contact(0, rival);
        }
        // Rival 2 leads the tally by a wide margin: sixty techs at two points each.
        let techs: Vec<Name> = game.rules.techs.keys().take(60).copied().collect();
        for tech in techs {
            game.players[2].techs.insert(tech);
        }
        assert!(
            game.score(2) > 2 * game.score(0),
            "fixture precondition: rival 2 leads on score ({} vs {})",
            game.score(2),
            game.score(0)
        );

        let stock = AdvancedAi::new();
        let pressure = stock.rival_victory_pressure(&game, 2);
        assert_eq!(pressure.strategy, GrandStrategy::Expansion, "the score clock names the leader");
        assert!(pressure.progress >= 78, "and calls it close to winning ({})", pressure.progress);
        assert_eq!(
            stock.victory_denial(&game, 0),
            Some((2, GrandStrategy::Conquest)),
            "the stock controller answers the score leader with a war"
        );

        let mut live = AdvancedAi::new();
        live.enable_live_bridge();
        assert!(live.counter_in_lane, "the live seat carries the treatment");
        assert_eq!(
            live.victory_denial(&game, 0),
            Some((2, GrandStrategy::Expansion)),
            "the live seat races the leader in its lane and declares on nobody"
        );
        let plan = live.assess(&game, 0);
        assert_ne!(
            (plan.strategy, plan.target_player),
            (GrandStrategy::Conquest, Some(2)),
            "no denial war on the live seat: {:?}",
            (plan.strategy, plan.target_player)
        );

        // Withheld: the same seat declares as the stock controller does.
        let mut withheld = AdvancedAi::new();
        withheld.enable_live_bridge();
        withheld.disable_counter_in_lane();
        assert_eq!(withheld.victory_denial(&game, 0), Some((2, GrandStrategy::Conquest)));
        assert!(!AdvancedAi::new().counter_in_lane);
        assert!(!AdvancedAi::legacy().counter_in_lane);
    }

